window.JASTROW_CHUNKS[56]={"22400":{"h":"פִּיטְרוֹפִּין","r":"Q00640","html":"<div class=\"sense\">, <span class=\"citation\">Y. Pes. VIII, 35ᵈ</span> <a href=\"#\" data-headword=\"פְּקוֹלִי\">הפ׳</a> = <span dir=\"rtl\">האֶפִּיטְרוֹפִּין</span>, v. <a href=\"#\" data-headword=\"אֶפִּיטְרוֹפּוֹס\">אֶפִּיטְרוֹפּוֹס</a></div>","alt":[]},"22401":{"h":"פיטרין","r":"Q00641","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוֹטִירִין\">פּוֹטִירִין</a></div>","alt":[]},"22402":{"h":"פִּיטַרְכָא","r":"Q00642","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּטָטַרְכָא\">פְּטָטַרְכָא</a></div>","alt":[]},"22403":{"h":"פִּיטְרָס","r":"Q00643","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיטְרוֹס\">פִּיטְרוֹס</a></div>","alt":[]},"22404":{"h":"פיטרתא","r":"Q00644","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to III, 11</span>, v. <a href=\"#\" data-headword=\"פִּרְטְתָא II\"><span dir=\"rtl\">פִּרְטְתָא</span> II</a></div>","alt":[]},"22405":{"h":"פַּיּיוֹטוֹת","r":"Q00645","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּיּוֹטוֹת\">פַּיּוֹטוֹת</a></div>","alt":[]},"22406":{"h":"פַּיְיטָן","r":"Q00646","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*פּוּט\">פוט</a>, v. <a href=\"#\" data-headword=\"פִּיּוּט\">פִּיּוּט</a>) <i>speaker</i>, esp. (by adaptation to ποιήτης) <i>composer of alphabetical acrostics, poet</i>. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">דהוה … פ׳ ודרשן</span> he was teacher of Bible and of Mishnah, speaker (poet) and preacher; Pesik. U’kaḥ., p. 179ᵃ (Ar. ed. Koh. <a href=\"#\" data-headword=\"פּוֹיְיטָן\">פּוֹיְיטָן</a>, oth. ed. <span dir=\"rtl\">פייטם</span>, <span dir=\"rtl\">פייטס</span>, corr. acc.); <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">פייטויי</span> (corr. acc.). <span class=\"citation\">Ib. to I, 1</span> <span dir=\"rtl\">הדין פ׳ כד עביד וכ׳</span> when a poet writes &amp;c., v. <a href=\"#\" data-headword=\"אלפ\">אלפ&quot;א</a>; <span class=\"citation\">Koh. R. to I, 13</span> <a href=\"#\" data-headword=\"פּוֹיְיטָן\">פּוֹיְיטָנָא</a>.—<i>Pl.</i> (h.) <span dir=\"rtl\">פַּיְיטָנִים</span>. <span class=\"citation\">Yalk. Cant. 983</span> (ref. to <span dir=\"rtl\">חרוזים</span>, <span class=\"citation\">Cant. I, 10</span>) <span dir=\"rtl\">אלו הפ׳</span> this refers to the poets (in Israel).</div>","alt":["פַּיְיטָנָא","פַּיְיטָנָה"]},"22407":{"h":"פְּיָילָא","r":"Q00647","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּיָילִי I\"><span dir=\"rtl\">פְּיָילִי</span> I</a></div>","alt":[]},"22408":{"h":"פיילדה","r":"Q00648","html":"<div class=\"sense\">, a corrupt., perh. for <a href=\"#\" data-headword=\"פִּילוּסָא\">פִּילוּרָא</a> m. (πυλωρός) <i>janitor</i>. <span class=\"citation\">Koh. R. to III, 9</span> (some ed. <a href=\"#\" data-headword=\"פיילן\">פיילן</a>); [Ar. thinking of <a href=\"#\" data-headword=\"פְּיָילִי I\">פיילי</a>: <i>potter</i>].</div>","alt":[]},"22409":{"h":"פְּיָילִי I","r":"Q00649","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (φιάλη, fiala) <i>a broad, flat bowl</i>. <span class=\"citation\">Targ. Y. I Gen. XL, 12</span>. <span class=\"citation\">Targ. Y. I Num. VII, 13</span> <a href=\"#\" data-headword=\"פְּיוֹלי\">פְּיוֹלִי</a> (Y. II <a href=\"#\" data-headword=\"פְּיָילִי I\">פַּיְילִי</a>; h. text <a href=\"#\" data-headword=\"קְעָרָה\">קערה</a>). <span class=\"citation\">Targ. Is. LI, 17</span>; <span class=\"citation\">22</span> <span dir=\"rtl\">פ׳ כסא</span> (ed. Wil. <a href=\"#\" data-headword=\"פְּיָלִי\">פַּיְלִי</a>; h. text <span dir=\"rtl\">קבעת כוס</span>); a. fr.—Tanḥ. Naso 1 <span dir=\"rtl\">פְּיָאלִי של חרש</span> an earthen bowl; Sifra M’tsorʿa, Par. 1, ch. 1 <span dir=\"rtl\">פיי׳ של חרס</span>; <span class=\"citation\">Sot. II, 2</span> (<span class=\"citation\">15ᵇ</span>; Bab. ed. <a href=\"#\" data-headword=\"פְּיָלִי\">פְּיָלִי</a>); a. fr.—<span class=\"citation\">Gen. R. s. 10</span>, a. fr. <span dir=\"rtl\">פ׳ פוטירין</span>, v. <a href=\"#\" data-headword=\"פּוֹטִירִין\">פּוֹטִירִין</a>.—[<span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">קדום פ׳</span>, <span dir=\"rtl\">קודם פ׳</span>, read: <a href=\"#\" data-headword=\"פִּילֵי\">פִּילִי</a>.]—[<span class=\"citation\">Sabb. 90ᵇ</span> פיילי ביירי Rashi, v. <a href=\"#\" data-headword=\"פַּלְיָא\">פַּלְיָא</a>.]—<i>Pl.</i> (ch.) <a href=\"#\" data-headword=\"פַּיְלָוָון\">פַּיְילָוָון</a>, <a href=\"#\" data-headword=\"פַּיְלָוָון\">פַּיְילְוָותָא</a>, <span dir=\"rtl\">פַּיְילָ׳</span>, <span dir=\"rtl\"><span dir=\"rtl\">פַּיְלָ׳</span> (פִּילָ׳</span>). <span class=\"citation\">Targ. Am. VI, 6</span> (ed. Lag. <a href=\"#\" data-headword=\"פִּלְוָון\">פִּלְוָון</a>). <span class=\"citation\">Targ. Y. Num. IV, 7</span> (ed. Vien. <span dir=\"rtl\">פִּילַיָּו׳</span>); a. e.—(Masc. form) <a href=\"#\" data-headword=\"פְּיָילִי I\">פְּיָילֵי</a>, <a href=\"#\" data-headword=\"פְּיָילִי I\">פַּיְילֵי</a>, <span dir=\"rtl\">פְּיָילַיָּא</span>, <span dir=\"rtl\">פְּיָלַ׳</span>. <span class=\"citation\">Targ. II Chr. IV, 8</span>; <span class=\"citation\">11</span>; a. e.</div>","alt":["פְּיָילָא"]},"22410":{"h":"פְּיָילִי II","r":"Q00650","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bar-Piali</i>. <span class=\"citation\">Ḥull. 96ᵃ</span> Ar. (ed. <a href=\"#\" data-headword=\"פְּיוֹלי\">פְּיוֹלִי</a>).</div>","alt":["בַּר פ׳"]},"22411":{"h":"פייליה","r":"Q00651","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 94</span>, end <span dir=\"rtl\">ופ׳</span>, read: <span dir=\"rtl\">ופייסוהו</span>, v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a></div>","alt":[]},"22412":{"h":"פיילן","r":"Q00652","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פיילדה\">פיילדה</a></div>","alt":[]},"22413":{"h":"פְּיַילְתָּא","r":"Q00653","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"פְּיָילִי I\"><span dir=\"rtl\">פְּיָילִי</span> I</a>. <span class=\"citation\">Targ. Y. II, Num. VII, 13</span>. <span class=\"citation\">Targ. Y. ib. 85</span>.—Pl. with suffix: <span dir=\"rtl\">פַּיַילְתּוֹי</span>. <span class=\"citation\">Targ. Y. Ex. XXV, 29</span>.—[<span dir=\"rtl\">פיילת חיוא</span>, v. <a href=\"#\" data-headword=\"פָּלְיַית\">פָּלְיַית</a>.]</div>","alt":["פַּיְילָתָא"]},"22414":{"h":"פַּיָּיס","r":"Q00654","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּיס\">פִּיס</a>) <i>brittle stone</i>. <span class=\"citation\">Sabb. 81ᵃ</span> פייס Ms. O. (ed. <span dir=\"rtl\">פאיי׳</span>; Ms. M. <a href=\"#\" data-headword=\"פַּיָּאס\">פַּיָּאס</a>; v. Rabb. D. S. a. l. note), expl. <span dir=\"rtl\">כרשיני בבלייתא</span>, v. <a href=\"#\" data-headword=\"כַּרְשִׁינָא I\"><span dir=\"rtl\">כַּרְשִׁינָא</span> I</a>.</div>","alt":["(פָּאיָיס)"]},"22415":{"h":"פַּיִיס","r":"Q00655","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּיס\">פִּיס</a>) <i>division</i>, (cmp. <a href=\"#\" data-headword=\"פּוּר\">פּוּר</a>, a. <a href=\"#\" data-headword=\"בָּצַע\">בָּצַע</a>) <i>compromise, arbitration</i>, esp. by counting out a certain number on the raised fingers of those among whom a decision is to be made (v. <a href=\"#\" data-headword=\"צָבַע I\">צָבַע</a><i>Hif.</i>), <i>allotment.</i> <span class=\"citation\">Yoma II, 2</span> <span dir=\"rtl\">התקינו … אלא בפ׳</span> it was ordained that the cleansing of the altar should not be done (by whosoever was the first to reach it) but according to arbitration by counting &amp;c. Ib. <span dir=\"rtl\">וזה הפ׳ הראשון</span> and this was the first arbitration (on the Day of Atonement). Ib. 3 <span dir=\"rtl\">הפ׳ השני מי וכ׳</span> the second count was to decide who was to slaughter &amp;c.; a. fr.—Pl. <span dir=\"rtl\">פְּיָיסוֹת</span>. Ib. 2 <span dir=\"rtl\">ארבע פ׳ היו שם</span> four times arbitration took place there (on the Day of Atonement). <span class=\"citation\">Y. Pes. VI, 33ᵇ</span> <span dir=\"rtl\">מפני קילקול פ׳</span> because it disturbs the arrangement of the various services allotted severally to the priests; a. e.</div>","alt":[]},"22416":{"h":"פְּיָיסָא","r":"Q00656","html":"<div class=\"sense\"><b>1)</b> <i>compromise, peace</i>. <span class=\"citation\">Nidd. 37ᵃ</span> <span dir=\"rtl\">עבדו רבנן פ׳</span> the Rabbis have made peace (have been reconciled).</div><div class=\"sense\"><b>—2)</b> <i>lot, balloting</i>. Targ. II Esth. III, 7 <a href=\"#\" data-headword=\"פ׳\">פ׳</a>, a. <span dir=\"rtl\">פ׳ דעדבין</span>. Targ. I, II Esth. IX, 24. <span class=\"citation\">Targ. Prov. I, 14</span>; a. e.—<span class=\"citation\">Yoma 22ᵃ</span> <span dir=\"rtl\">תקינו לה … פ׳</span> the scholars arranged balloting (by counting fingers, v. <a href=\"#\" data-headword=\"פַּיִיס\">preced.</a>). <span class=\"citation\">Ib. 23ᵃ</span>; a. e.</div>","alt":["פַּיְסָא","(פִּיסָא)"]},"22417":{"h":"*פַּיְיסוֹנָא","r":"Q00657","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פִּיסוֹן\">פִּיסוֹן</a>, <i>mason</i>. <span class=\"citation\">Y. Yeb. XII, end, 13ᵃ</span> <span dir=\"rtl\">הדין פ׳ דפַיְיסַנְתָּךְ</span> (ed. Krot. <span dir=\"rtl\">פייסינא</span>) is this (R. Levy whom you recommended) a mason of thy mason’s guild (a pupil of thy school)?</div>","alt":[]},"22418":{"h":"פַּיְיסַנְתָּא","r":"Q00658","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*פַּיְיסוֹנָא\">preced.</a>) <i>masonry, mason’s guild</i>, v. <a href=\"#\" data-headword=\"*פַּיְיסוֹנָא\">preced.</a></div>","alt":[]},"22419":{"h":"*פַּיְישׂוֹנָא","r":"Q00659","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פַּיָּיס\">פַּיָיס</a>) [<i>pebble</i>,] name of a species of <i>beans</i> (cmp. <a href=\"#\" data-headword=\"כַּרְשִׁינָא I\">כַּרְשִׁינָא</a> I a. III), called in Hebrew <i>sappir</i>. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> top, R. S. to <span class=\"citation\">Kil. I, 1</span> (ed. <a href=\"#\" data-headword=\"פושונה\">פושונה</a>), v. <a href=\"#\" data-headword=\"סַפִּיר\">סַפִּיר</a>.</div>","alt":[]},"22420":{"h":"פִּיל","r":"Q00660","html":"<div class=\"sense\"> imper. of <a href=\"#\" data-headword=\"נְפַל\">נְפַל</a>.</div>","alt":[]},"22421":{"h":"פִּיל I","r":"Q00661","html":"<div class=\"sense\"> m., <span dir=\"rtl\">בעל הפ׳</span>, v. <a href=\"#\" data-headword=\"*פּוּל\">פּוּל</a></div>","alt":[]},"22422":{"h":"פִּיל II","r":"Q00662","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">פלא</span>, cmp. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a>) <i>elephant.</i> <span class=\"citation\">Kil. VIII, 6</span>. <span class=\"citation\">Men. 69ᵃ</span>; <span class=\"citation\">B. Bath. 22ᵃ</span>. <span class=\"citation\">Lev. R. s. 6</span>; a. e.—Pl. <span dir=\"rtl\">פִּילִים</span>, <a href=\"#\" data-headword=\"פילין\">פִּילִין</a>. <span class=\"citation\">Gen. R. s. 31</span>, end., v. <a href=\"#\" data-headword=\"זְמוֹרָה\">זְמוֹרָה</a>. <span class=\"citation\">Y. Sabb. XVIII, 16ᶜ</span>; <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 8</span>; a. e.—<span class=\"citation\">Gen. R. s. 15</span>, end <span dir=\"rtl\">בן הפילים</span> some ed., v. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a>.</div>","alt":[]},"22423":{"h":"פִּיל ²","r":"Q00663","html":"<div class=\"sense\">; <span dir=\"rtl\">שן דפ׳</span>, or <a href=\"#\" data-headword=\"פ׳\">פ׳</a> (sub. <a href=\"#\" data-headword=\"שֵׁן\">שן</a>) <i>ivory</i>. <span class=\"citation\">Targ. I Kings X, 22</span>. <span class=\"citation\">Ib. XXII, 39</span>; a. e.—<span class=\"citation\">Y. Shebu. III, 34ᵈ</span> bot., a. e., v. <a href=\"#\" data-headword=\"עֲנִיבָה II\"><span dir=\"rtl\">עֲנִיבָה</span> II</a>. <span class=\"citation\">Ber. 55ᵇ</span> bot. <span dir=\"rtl\">דלא מחוו ליה … ולא פ׳ דעייל וכ׳</span> man is never shown in a dream a golden palm tree or an elephant passing through a needle’s eye (man dreams only of what he thinks of when awake). <span class=\"citation\">B. Mets. 38ᵇ</span> <span dir=\"rtl\">דילמא … דמעיילין פ׳</span> art thou perhaps of Pumb’ditha where they make an elephant pass through a needle’s eye (are subtle)? <span class=\"citation\">Num. R. s. 10</span>; <span class=\"citation\">Lev. R. s. 5</span>, v. <a href=\"#\" data-headword=\"עֶרֶס\">עַרְסָא</a>; a. e.—Pl. <a href=\"#\" data-headword=\"פִּילְיָא\">פִּילַיָּא</a>, constr. <a href=\"#\" data-headword=\"פִּילֵי\">פִּילֵי</a>. <span class=\"citation\">Targ. Cant. VI, 8</span>. <span class=\"citation\">Targ. Nah. II, 4</span> (h. text <span dir=\"rtl\">פלדות</span>!).</div>","alt":["פִּילָא I"]},"22424":{"h":"פִּיל III","r":"Q00664","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (part. pass. of <span dir=\"rtl\">פול</span> or <span dir=\"rtl\">פלל</span>; cmp. <a href=\"#\" data-headword=\"בָּלַל\">בלל</a>; cmp. <a href=\"#\" data-headword=\"פְּלֵי\">פְּלֵי</a>) <i>permeated, soaked</i>. <span class=\"citation\">Targ. O. Lev. XIV, 21</span> (h. text <a href=\"#\" data-headword=\"בָּלוּל\">בלול</a>). <span class=\"citation\">Ib. VII, 10</span>; a. fr.—Pl. f. <span dir=\"rtl\">פִּילַן</span>. <span class=\"citation\">Ib. 12</span>; a. e.</div>","alt":["פִּילָא II"]},"22425":{"h":"פִּילָא III","r":"Q00665","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פִּיל III\">preced.</a>) <i>split, crack, furrow</i>.—Pl. <a href=\"#\" data-headword=\"פִּילֵי\">פִּילֵי</a>. <span class=\"citation\">Pes. 76ᵃ</span> bot. <span dir=\"rtl\">אית ביה פ׳</span> if there are splits (in the crusty surface of the roast); <span class=\"citation\">Ḥull. 112ᵃ</span>. <span class=\"citation\">Sabb. 33ᵇ</span> <span dir=\"rtl\">הוו ביה פ׳ בגופיה</span> had cuts in his skin (from living in a cave). <span class=\"citation\">M. Kat. 3ᵃ</span>; <span class=\"citation\">Succ. 44ᵇ</span> <span dir=\"rtl\">סתומי פ׳</span> to close up fissures in the soil which covers the roots. <span class=\"citation\">B. Bath. 54ᵃ</span> top. <span class=\"citation\">Taan. 4ᵃ</span>, v. <a href=\"#\" data-headword=\"עוּרְפִּילָא\">עוּרְפִּילָא</a>; a. e.</div>","alt":[]},"22426":{"h":"פִּילָא IV","r":"Q00666","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>pila</i>, name of an <i>aromatic plant</i> (Rashi: <i>polion</i>, v. Sm. Ant. s. v. Polion). <span class=\"citation\">Keth. 77ᵇ</span></div>","alt":[]},"22427":{"h":"פילא","r":"Q00667","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 33</span>; <span class=\"citation\">Cant. R. to III, 4</span>, v. <a href=\"#\" data-headword=\"פַּלִּיָיא\">פַּלִּיָיא</a>.</div>","alt":["פילאי"]},"22428":{"h":"פִּילָאוֹת","r":"Q00668","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"פִּילֵי\">פִּילֵי</a> q. v.</div>","alt":[]},"22429":{"h":"פִּילָגוֹס","r":"Q00669","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πέλαγος) <i>high sea</i>. <span class=\"citation\">Targ. Ps. XLVI, 3</span> <span dir=\"rtl\">פ׳ דימא</span> (ed. Wil. <a href=\"#\" data-headword=\"פַּלְגּוֹס\">פַּלְגוּס</a>; h. text <span dir=\"rtl\">לב ים</span>). <span class=\"citation\">Targ. Y. Ex. XV, 8</span>.—<span class=\"citation\">Lev. R. s. 12</span>, beg. <span dir=\"rtl\">בפ׳ דימא</span>, v. <a href=\"#\" data-headword=\"אִילפָא I\"><span dir=\"rtl\">אִילְפָא</span> I</a>; <span class=\"citation\">Esth. R. to II, 1</span> <span dir=\"rtl\">(ר׳ עזריה</span>); <span class=\"citation\">Yalk. Prov. 960</span> <span dir=\"rtl\">בפ׳</span> (without <span dir=\"rtl\">ימא</span>). <span class=\"citation\">Koh. R. to III, 6</span> [read:] <span dir=\"rtl\">כד עללין אנן לפ׳ אנן וכ׳</span> when we get out on the high sea, we shall kill him.</div>","alt":["פִּילְגוֹס"]},"22430":{"h":"פילגס","r":"Q00670","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינוֹלֵס\">פִּינוֹלֵס</a></div>","alt":[]},"22431":{"h":"פִּילֶּגֶשׁ","r":"Q00671","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּלֶּגֶשׁ\">פִּלֶּגֶשׁ</a></div>","alt":[]},"22432":{"h":"פילה","r":"Q00672","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kil. I, 27ᵃ</span> top, v. <a href=\"#\" data-headword=\"פּוֹלָא\">פּוֹלָא</a>.—<span class=\"citation\">Y. Ber. IX, 14ᵇ</span> <span dir=\"rtl\">יודן בן פ׳</span>, v. <a href=\"#\" data-headword=\"פִּילְיָא\">פִּילְיָא</a>.</div>","alt":[]},"22433":{"h":"פִּילּוּג","r":"Q00673","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּלַג\">פָּלַג</a>) <i>division, separation</i>. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> bot. <span dir=\"rtl\">וכל פ׳ מי בראשית מתפלגין מתחתיו</span> whatever be the divisions into which the waters of creation parted, they started from under it (the tree of life); (<span class=\"citation\">Gen. R. s. 15</span>, a. e. <span dir=\"rtl\">וכל מימי בראשית מתפלגין מתחתיו</span>).</div>","alt":[]},"22434":{"h":"פִּילּוּג ²","r":"Q00674","html":"<div class=\"sense\"><b>1)</b> <i>distribution</i>. <span class=\"citation\">Targ. Y. Num. X, 32</span>.</div><div class=\"sense\"><b>—2)</b> <i>decision, decree</i>; <span dir=\"rtl\">פִּילּוּג דינא</span> <i>judgment</i>. <span class=\"citation\">Targ. O. Gen. XIV, 7</span> (h. text <span dir=\"rtl\">עין משפט</span>; v. Targ. Y. ib.) <span class=\"citation\">Targ. Joel IV, 2</span> (h. text <a href=\"#\" data-headword=\"יְהוֹשָׁפָט\">יהושפט</a>); a. e.</div><div class=\"sense\"><b>—3)</b> <i>part</i>, v. <a href=\"#\" data-headword=\"פְּלַג II\"><span dir=\"rtl\">פְּלַג</span> II</a>.</div>","alt":["פִּילּוּגָא","פִּלּ׳"]},"22435":{"h":"פַּיְלָוָון","r":"Q00675","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּיָילִי I\"><span dir=\"rtl\">פְּיָילִי</span> I</a></div>","alt":["פַּיְלָוָותָא","פִּילָ׳"]},"22436":{"h":"פִּילוֹטִימְיָא","r":"Q00676","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (φιλοτιμία, S.) <i>display, public show</i>, esp. <i>gladiatorial exhibition, combats of beasts</i> &amp;c. (v. Sachs Beitr. I, p. 120). <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">שמע שפ׳ נעשית</span> (not <a href=\"#\" data-headword=\"פלוטמיא\">פלוטמיא</a>) he heard that a show is coming up; <span dir=\"rtl\">שאל … פ׳</span> he asked a gladiator <a href=\"#\" data-headword=\"לוּדָר\">(לוּדָר</a>), when will the show take place?; <span dir=\"rtl\">שאל לאותו שעושה פ׳</span> he asked him who was to give the show (‘editor’).</div>","alt":[]},"22437":{"h":"פִּילּוּל","r":"Q00677","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּלַל\">פָּלַל</a>) <i>pleading, pillul</i>, one of the terms for prayer. <span class=\"citation\">Sifré Deut. 26</span>; <span class=\"citation\">Deut. R. s. 2</span>; <span class=\"citation\">Yalk. ib. 811</span>. <span class=\"citation\">Yalk. Ex. 260</span> <span dir=\"rtl\">עלה פ׳ תפלתן וכ׳</span> (not <span dir=\"rtl\">תכלתן</span>) the pleading of the prayer of the patriarchs arose &amp;c.; (Mekh. B’shall., Vayassʿa, s. 3 <span dir=\"rtl\">עלתה תפלתן</span>).</div>","alt":["פּלּ׳"]},"22438":{"h":"*פִּילוֹמָא","r":"Q00678","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πήλωμα, S.) <i>mud, clay ground</i>. <span class=\"citation\">Sabb. XXII, 6</span> (<span class=\"citation\">147ᵃ</span>) <span dir=\"rtl\">אין יורדין לפ׳</span> Y. ed., a. Ms. M. (v. Rabb. D. S. a. l. note; Bab. ed. a. Mish. <a href=\"#\" data-headword=\"קורדימא\">קורדימא</a>, v. <a href=\"#\" data-headword=\"קֵירוֹמָא\">קִירוֹמָא</a>) you must not go down to the clay ground (of the brickyard, on the Sabbath).</div>","alt":[]},"22439":{"h":"פִּילוֹן","r":"Q00679","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πυλών, πυλεών) <i>gateway</i>. <span class=\"citation\">Lev. R. s. 30</span>, beg. (ref. to <span class=\"citation\">Ps. XVI, 11</span>) <span dir=\"rtl\">הודיעני איזה פ׳ מפולש וכ׳</span> Ar. (ed. <span dir=\"rtl\">תודיעני באיזה</span>) let me know which is the open gate leading to life everlasting. <span class=\"citation\">Gen. R. s. 59</span>, [read as:] <span class=\"citation\">Yalk. ib. 103</span> (ref. to <span class=\"citation\">Gen. XXIV, 1</span>) <span dir=\"rtl\">בא בפ׳ מפולש וכ׳</span> he had entered on the gateway leading &amp;c. <span class=\"citation\">Gen. R. s. 66</span>, end <span dir=\"rtl\">פִּילְיוֹנוֹ של וכ׳</span> (not <a href=\"#\" data-headword=\"פֶּתֶן ²\">פו׳</a>) Isaac’s gateway was open from both sides, so that the one came in from one side, and the other from the other side; [ib. s. 48 <span dir=\"rtl\">פלן של אבינו אברהם וכ׳</span>; <span class=\"citation\">Yalk. ib. 82</span> <span dir=\"rtl\">פוולונו</span> (corr. acc., or <a href=\"#\" data-headword=\"פָּפִילְיוֹן\">פָּפִילְיוֹנוֹ</a>, v. <a href=\"#\" data-headword=\"פָּפִילְיוֹן\">פָּפִילְיוֹן</a>]. <span class=\"citation\">Lev. R. s. 18</span> <span dir=\"rtl\">הכל נכנסין בפ׳ אחד</span> (not <span dir=\"rtl\">בפולין</span>, <span dir=\"rtl\">בפילין</span>) all enter town by the same gateway [or read: <span dir=\"rtl\">בפילי אחת</span>, v. <a href=\"#\" data-headword=\"פִּילֵי\">פִּילי</a>]; <span class=\"citation\">Koh. R. to XII, 5</span> <span dir=\"rtl\">בפילין אגון אחת</span> (<span dir=\"rtl\">בפילי</span>) (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כד אתין לפילין</span> (ed. Wil. <span dir=\"rtl\">לפילן</span>, corr. acc.) when they arrived at the gateway (of the Sepphorean’s residence); a. e.—[<span class=\"citation\">Yalk. Ex. 178</span> <span dir=\"rtl\">פלומי פ׳</span>, v. <a href=\"#\" data-headword=\"פְּלוֹמוֹפִּילוֹן\">פְּלוּמוֹפִּילוֹן</a>.]</div>","alt":["פִּילְיוֹן"]},"22440":{"h":"פִּילֹּון","r":"Q00680","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (φύλλον, sub. Ἰνδικόν; folium) <i>aromatic leaves</i> (Malabathrum). Sifra Vayikra, Ḥoba, Par. 12, ch. XXII <span dir=\"rtl\">המערב … עלי גפנים בפ׳</span> who adulterates phyllon with vine leaves; <span class=\"citation\">Tosef. B. Bath. V, 6</span> <span dir=\"rtl\">בפיליון</span> (corr. acc.); <span class=\"citation\">Koh. R. to IX, 13</span> <span dir=\"rtl\">בפלפלין</span> (corr. acc.); <span class=\"citation\">ib. to VI, 1</span> <span dir=\"rtl\">בפליון</span> (corr. acc.); <span class=\"citation\">Yalk. Lev. 479</span>. <span class=\"citation\">Sabb. 62ᵃ</span>; <span class=\"citation\">Gitt. 69ᵇ</span>, v. <a href=\"#\" data-headword=\"חוּמַרְתָּא\">חוּמַרְתָּא</a>.</div>","alt":[]},"22441":{"h":"פִּילוֹנִיקְיָא","r":"Q00681","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (φιλονικεία) <i>love of strife, contentiousness</i>. Tanḥ. Vaëra 11 (ref. to <span class=\"citation\">Is. XLVI</span>, 10ᵇ) <span dir=\"rtl\">כל הקורא פסוק זה סבור שמא פ׳ וכ׳</span> (not <a href=\"#\" data-headword=\"פלוניקיא\">פלוניקיא</a>) he who reads this verse will think, is there a contest of opinions above (in heaven)?; ib. ed. Bub. 11 <a href=\"#\" data-headword=\"פקלוניא\">פקלוניא</a> (corr. acc.); <span class=\"citation\">Ex. R. s. 9</span>, beg. <a href=\"#\" data-headword=\"פלינקרא\">פלינקרא</a>, <a href=\"#\" data-headword=\"פלינקרא\">פלינקריא</a> (corr. acc.); (Tanḥ. Thazr. 7 <span dir=\"rtl\">עיות הדין</span>, ed. Bub. 9 <span dir=\"rtl\">עיבור הדין</span>).</div>","alt":[]},"22442":{"h":"פִּילוֹנֵס","r":"Q00682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינוֹלֵס\">פִּינוֹלֵס</a></div>","alt":[]},"22443":{"h":"פילוס","r":"Q00683","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. IX</span>; Yalk. ib. 642 <span dir=\"rtl\">פיליש</span>, read <span dir=\"rtl\">פִּילִיפּוֹס</span>, v. <a href=\"#\" data-headword=\"פוליא\">פוליא</a></div>","alt":[]},"22444":{"h":"פִּילוּסָא","r":"Q00684","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Pilusa</i> (Pelusium). <span class=\"citation\">Ab. Zar. 39ᵃ</span> Mus. (ed. <span dir=\"rtl\">פלוסא</span>, Ms. M. <a href=\"#\" data-headword=\"פולסא\">פולסא</a>; ed. Pes. a. oth. <span dir=\"rtl\">פלמוסא</span>, v. Rabb. D. S. a. l. note).—V. <a href=\"#\" data-headword=\"פִּילוּסִין I\">פִּילוּסִין</a>.</div>","alt":[]},"22445":{"h":"פִּילוֹסָאָה","r":"Q00685","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּילוּסָא\">preced.</a>) <i>Pelusian.</i> Pl. <a href=\"#\" data-headword=\"פִּילוֹסָאָה\">פִּילוֹסָאֵי</a>. <span class=\"citation\">Targ. Y. II, Gen. X, 14</span> (h. text <span dir=\"rtl\">פתרסים</span>).</div>","alt":[]},"22446":{"h":"פִּילוֹסוֹפוֹס","r":"Q00686","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (φιλόσοφος) <i>philosopher, one living a life of speculation and self-denial, monk</i> (v. Gr. Dict. s. v.). <span class=\"citation\">Y. Sabb. III, 6ᵃ</span> bot. <span dir=\"rtl\">חד פ׳ שאל וכ׳</span> (not <span dir=\"rtl\">פיוס …</span>) a certain philosopher (Christian?) asked &amp;c.; <span class=\"citation\">Y. Bets. II, 61ᶜ</span>. <span class=\"citation\">Treat. Der. Er. ch. V</span> (v. Brüll, Jahrb. 1879, p. 41). <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">פ׳ אחד שאל וכ׳</span> (ed. Wil. <span dir=\"rtl\">פילסופי</span>, corr. acc.) a philosopher asked R. G.; <span class=\"citation\">Ab. Zar. 54ᵇ</span> <span dir=\"rtl\">פלוספוס</span>; a. fr.—Pl. <span dir=\"rtl\">פִּילוֹסוֹפִים</span>, <span dir=\"rtl\">פִּילוֹסוֹפִין</span>, <span dir=\"rtl\">(פְּלוֹ׳</span>). Ib.; <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 7</span>. <span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">לא עמדו פ׳ בעולם וכ׳</span> no philosophers ever arose as wise as Balaam &amp;c. <span class=\"citation\">Gen. R. s. 61</span> <span dir=\"rtl\">ישבו פ׳ וחשבו</span> (= <a href=\"#\" data-headword=\"סוֹפִיסְטָא\">סופיסטיס</a>) accountants sat down and calculated; a. fr.</div>","alt":[]},"22447":{"h":"פִּילוּסִים","r":"Q00687","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילוּסִין II\"><span dir=\"rtl\">פִּילוּסִין</span> II</a></div>","alt":[]},"22448":{"h":"פִּילוּסִין I","r":"Q00688","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Πηλούσιον) <i>Pelusium</i>, a town in Lower Egypt. <span class=\"citation\">Targ. Y. I Gen. XLVII, 11</span> <span dir=\"rtl\">ארעא דפ׳</span> (Y. II <span dir=\"rtl\">ופילוסים</span>, corr. acc.; h. text <span dir=\"rtl\">ארץ רעמסס</span>). <span class=\"citation\">Targ. Y. Ex. I, 11</span> <a href=\"#\" data-headword=\"*פִּקּוּסִים\">פִּלּוּסִין</a> ed. Vien. (II <span dir=\"rtl\">תין …</span>, corr. acc.); a. fr.</div>","alt":[]},"22449":{"h":"פִּילוּסִין II","r":"Q00689","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּילוּסִין I\">preced.</a>) <i>Pelusian linen.</i> <span class=\"citation\">Yoma III, 7</span> (<span class=\"citation\">34ᵇ</span>) <span dir=\"rtl\">היה לובש פי׳ וכ׳</span> Y. ed. (Bab. ed. a. Mish. <span dir=\"rtl\">פל׳</span>) he wore garments of Pelusian linen of the value of &amp;c. Y. ib. III, 40ᵈ top <span dir=\"rtl\">שני של פ׳</span> second class Pelusian linen; a. e.</div>","alt":["פּילוּסִים"]},"22450":{"h":"*פּילוֹסְפָא","r":"Q00690","html":"<div class=\"sense\"> m. = h. <a href=\"#\" data-headword=\"פִּילוֹסוֹפוֹס\">פִּילוֹסוֹפוֹס</a>. <span class=\"citation\">Sabb. 116ᵃ</span> bot. <span dir=\"rtl\">הוה האי פ׳ בשיבבותיה וכ׳</span> (Ms. M. <span dir=\"rtl\">פלנספא קבא</span>, prob. for <span dir=\"rtl\">פלוספא סבא</span>; Ms. O. <span dir=\"rtl\">פילאספא</span>; Var. in Tosaf. <span dir=\"rtl\">פילא סבא</span>, v. Rabb. D. S. a. l. note 70) there was a philosopher (a Christian judge) in his (R. G.’s) neighborhood who had the reputation of incorruptibility.</div>","alt":[]},"22451":{"h":"פילוספוס","r":"Q00691","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. III, 4</span>, v. <a href=\"#\" data-headword=\"פְּלוֹסְלוֹס II\"><span dir=\"rtl\">פְּלוֹסְלוֹס</span> II</a></div>","alt":[]},"22452":{"h":"פִּילְחָא","r":"Q00692","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּלְחָא\">פִּלְחָא</a></div>","alt":[]},"22453":{"h":"פילטא","r":"Q00693","html":"<div class=\"sense\">, read: <span dir=\"rtl\">פֹּלְיָטָא</span> = <a href=\"#\" data-headword=\"פּוֹלְיָטוֹן\">פֹּוליָטוֹן</a>. <span class=\"citation\">Cant. R. to IV, 14</span> (expl. <a href=\"#\" data-headword=\"אָהֳלוֹת\">אהלות</a>).</div>","alt":[]},"22454":{"h":"פְּיָלִי","r":"Q00694","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּיָילִי I\">פְּיָילִי</a></div>","alt":["פַּיְלִי"]},"22455":{"h":"פִּילֵי","r":"Q00695","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (πύλαι) <i>gate</i> of a town, <i>entrance</i>. <span class=\"citation\">Targ. Y. II, Gen. XIX, 1</span>.—Y. Yeb. XII, 12ᵈ top; <span class=\"citation\">Y. Sabb. VI, 8ᵃ</span> bot. <span dir=\"rtl\"><span dir=\"rtl\">מן דמטון</span> (<a href=\"#\" data-headword=\"ל\">ל</a>) <a href=\"#\" data-headword=\"פ׳\">פ׳</a></span> (not <a href=\"#\" data-headword=\"פֶּתֶן ²\">פו׳</a>) when they arrived at the gates. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a>) <span dir=\"rtl\">בתרע פ׳ דההיא וכ׳</span></span> at the gate of the entrance to that city. <span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">פ׳ דפנייס</span> the gate of Paneas; a. fr.—Ib., a. e. <a href=\"#\" data-headword=\"פְּיָילִי I\">פיילי</a> (corr. acc.).—Tanḥ., ed. Bub., Miḳḳ. 10 <span dir=\"rtl\">בפולי אחד</span> (read: <span dir=\"rtl\">בפי׳ אחת</span>).—<i>Pl.</i> ch. <a href=\"#\" data-headword=\"פַּיְלָוָון\">פִּילְוָותָא</a>. <span class=\"citation\">Targ. Y. I Deut. XX, 11</span> <span dir=\"rtl\">פִּילְוָותָהּ</span> (Y. II <span dir=\"rtl\">פִּלְוָותָא</span>, corr. acc.).—Hebr. pl. <a href=\"#\" data-headword=\"פִּילָאוֹת\">פִּילָאוֹת</a>. Tanḥ. l. c. <span dir=\"rtl\">הושיב שומרים על פתחי פ׳</span> (not <span dir=\"rtl\">פתח</span>) he placed guards at all entrances.</div>","alt":[]},"22456":{"h":"פִּילְיָא","r":"Q00696","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Pilia</i>. <span class=\"citation\">Lev. R. s. 24</span> <span dir=\"rtl\">יודן בר פ׳</span>; <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> <span dir=\"rtl\">בן פילה</span>; <span class=\"citation\">Midr. Till. to Ps. CI</span> <a href=\"#\" data-headword=\"פַּלִּיָיא\">פִּלְיָיא</a> ed. Bub. (oth. ed. <a href=\"#\" data-headword=\"שִׁילָא\">שילא</a>, corr. acc.). <span class=\"citation\">Y. Shebi. V, beg. 35ᵈ</span> פליא Fr. M’bo, p. 95ᵇ (ed. Krot. <span dir=\"rtl\">פדיא</span>).</div>","alt":["פִּלְ׳"]},"22457":{"h":"פיליא","r":"Q00697","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְיָא\">פַּלְיָא</a></div>","alt":["פ׳ ביארי"]},"22458":{"h":"פִּילְיוֹן I","r":"Q00698","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (pilleum, πιλίον) <i>felt-cap.</i> <span class=\"citation\">Kel. XXIX, 1</span>, v. <a href=\"#\" data-headword=\"*אַפִּילְיוֹן III\"><span dir=\"rtl\">אַפִּילְיוֹן</span> III</a>.—[<span class=\"citation\">Y. Sabb. XVI, 15ᵈ</span> top <span dir=\"rtl\">ופי׳</span>, read: <span dir=\"rtl\">ופַלְיוֹן</span>, v. <a href=\"#\" data-headword=\"אַפַּלְיוֹן\">אַפַּלְיוֹן</a>.]</div>","alt":[]},"22459":{"h":"פִּילְיוֹן II","r":"Q00699","html":"<div class=\"sense\"> m. (πυλεών), v. <a href=\"#\" data-headword=\"פִּילוֹן\">פִּילוֹן</a></div>","alt":[]},"22460":{"h":"פיליוס","r":"Q00700","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ber. II, 4ᶜ</span> bot. <span dir=\"rtl\">בפ׳</span>, read: <span dir=\"rtl\">בפַלְיוּם</span>.</div>","alt":[]},"22461":{"h":"פילין","r":"Q00701","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילוֹן\">פִּילוֹן</a></div>","alt":[]},"22462":{"h":"פילינון","r":"Q00702","html":"<div class=\"sense\">, <span class=\"citation\">Lam. R. to II, 2</span> Ar., read: <span dir=\"rtl\">פִּילוֹנִין</span>, v. <a href=\"#\" data-headword=\"פִּינוֹלֵס\">פִּינוֹלֵס</a></div>","alt":["פילינין"]},"22463":{"h":"פיליסמוסטיט","r":"Q00703","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Prov. 950</span> some ed., corrupt. of <a href=\"#\" data-headword=\"אֶפִּימְלֵיטֵיס\">אֶפִּימְלֵיטֵיס</a>.</div>","alt":[]},"22464":{"h":"פִּילִיפִּי","r":"Q00704","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלִיפָּא\">פְּלִיפָּא</a></div>","alt":[]},"22465":{"h":"פִּילְכ־","r":"Q00705","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּלֶךְ\">פֶּלֶךְ</a></div>","alt":["פִּילְכָא"]},"22466":{"h":"פילכיה","r":"Q00706","html":"<div class=\"sense\">, <span class=\"citation\">Y. Dem. IV, 24ᵃ</span> bot., v. <a href=\"#\" data-headword=\"פִּיוְולָא\">פִּיוְולָא</a></div>","alt":[]},"22467":{"h":"פִּילֵס","r":"Q00707","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּלַס\">פְּלַס</a>; cmp. <a href=\"#\" data-headword=\"פּוּלְסָא\">פּוּלְסָא</a>) <i>a circular disk, plate</i>, used as a weight. <span class=\"citation\">Targ. I Sam. XXX, 12</span> (h. text <span dir=\"rtl\">פלח</span>). <span class=\"citation\">Targ. Ez. IV, 10</span> (h. text <span dir=\"rtl\">שקל</span>).—<span class=\"citation\">B. Mets. 47ᵇ</span> <span dir=\"rtl\">פִּילְסָא</span>, Ar., v. <a href=\"#\" data-headword=\"פּוּלְסָא\">פּוּלְסָא</a>.</div>","alt":["פִּילַס"]},"22468":{"h":"פילסונו","r":"Q00708","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 60</span> הוא פ׳ Ar., ed. <span dir=\"rtl\">הוא ופלסונו</span>; Yalk. ib. 109 <span dir=\"rtl\">הוא ופלסטינו</span>, a corruption;—perh. to be read: <span dir=\"rtl\">הוא ופַלָּטִינוֹ</span> (palatinus) he and his <i>chamberlain</i> (the guardian angel accompanying him).</div>","alt":[]},"22469":{"h":"פִּילְפּוּל","r":"Q00709","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פִּילְיָא\">פִּלְ׳</a>.</div>","alt":["פִּילְפּוּלָא"]},"22470":{"h":"פִּילְפִּי","r":"Q00710","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלִיפָּא\">פְּלִיפָּא</a></div>","alt":[]},"22471":{"h":"פִּילְפֵּל","r":"Q00711","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פִּילְיָא\">פִּלְ׳</a>.</div>","alt":["פִּילְפָּל","פִּילְפְּלָא","פִּילְפְּלָן","פִּילְפֶּלֶת"]},"22472":{"h":"פִּילָקִי","r":"Q00712","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (φυλακή) <i>prison</i>. Pesik. U’lkaḥ., p. 182ᵃ <span dir=\"rtl\">איתייהב בפ׳</span> was put in prison; <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">איתחבש בפ׳</span>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">נתנה בפ׳</span> he put her in prison. <span class=\"citation\">Ex. R. s. 30</span>, v. <a href=\"#\" data-headword=\"בָּעַט II\"><span dir=\"rtl\">בָּעַט</span> II</a>; a. fr.—<span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">חבשתינון בסלקי</span> (corr. acc.).—Pl. <span dir=\"rtl\">פִּילָקִיוֹת</span>, <a href=\"#\" data-headword=\"פִּילָקִי\">פִּלָ׳</a>. Pesik. Vayhi, p. 67ᵃ; <span class=\"citation\">Pesik. R. s. 17</span>. <span class=\"citation\">Pesik. R. s. 42</span> (ref. to <span class=\"citation\">Esth. II, 18</span>, <span dir=\"rtl\">והנחה</span>) <span dir=\"rtl\">פיתח הפ׳</span> he opened the prisons.</div>","alt":["פִּלָ׳"]},"22473":{"h":"פִּילְקִין","r":"Q00713","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πέλεκυς) <i>axe</i>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 47</span> <span dir=\"rtl\">כפ׳ היה יורד הברד וכ׳</span> (not <span dir=\"rtl\">בפ׳</span>) the hail came down like an axe (or <i>axes, </i> pl.) and cut all the trees; <span class=\"citation\">Ex. R. s. 12</span>; <span class=\"citation\">Midr. Till. to Ps. CV, 33</span> <span dir=\"rtl\">כפילקיס הזה</span>; Tanḥ. Vaëra 14 <span dir=\"rtl\">בפלכין</span>; <span class=\"citation\">Yalk. Ps. 820</span> <span dir=\"rtl\">בפיקלין</span> (corr. acc.).</div>","alt":["פִּילְקִיס"]},"22474":{"h":"פִּילַּקְתָּא","r":"Q00714","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּלַּקְתָּא\">פִּלַּקְתָּא</a></div>","alt":[]},"22475":{"h":"פילרוס","r":"Q00715","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְדֵּיס\">פּלְדֵּיס</a></div>","alt":[]},"22476":{"h":"פימוסקא","r":"Q00716","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*פַּרְמוּסְקָא\">פַּרְמוּסְקָא</a></div>","alt":[]},"22477":{"h":"פימלאות","r":"Q00717","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינוֹלֵס\">פִּינוֹלֵס</a></div>","alt":["פימליאות"]},"22478":{"h":"פִּימְלַנְיָיה","r":"Q00718","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּמְלַנְיָא\">פִּמְלַנְיָא</a></div>","alt":[]},"22479":{"h":"פִּין","r":"Q00719","html":"<div class=\"sense\">, <span class=\"citation\">Kel. XI, 4</span> <span dir=\"rtl\">הפין</span>, v. <a href=\"#\" data-headword=\"חָף\">חָף</a> end.</div>","alt":[]},"22480":{"h":"פִּינָּה","r":"Q00720","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>turn, movement</i>.—Pl. <span dir=\"rtl\"><a href=\"#\" data-headword=\"פִּיּוֹת\">פִּינּוֹת</a> (פּוֹנוֹת</span>). <span class=\"citation\">Yoma 58ᵇ</span> <span dir=\"rtl\">כל פי׳ שאתה פונה וכ׳</span> (Ms. M. 2 <span dir=\"rtl\">פנות</span>; Ms. O. <a href=\"#\" data-headword=\"פֶּתֶן ²\">פו׳</a>) all the turns you make (in the Temple) must be towards the right; <span class=\"citation\">ib. 15ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"פֶּתֶן ²\">פו׳</a>); <span class=\"citation\">Zeb. 62ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"פֶּתֶן ²\">פו׳</a>); <span class=\"citation\">Sot. 15ᵇ</span> <a href=\"#\" data-headword=\"פֶּתֶן ²\">פו׳</a>; <span class=\"citation\">Yalk. Lev. 446</span> <span dir=\"rtl\">פְּנִיּוֹת</span>; a. e.—[With the exception of Sot. l. c. our editions read <span dir=\"rtl\">פינות</span>].</div><div class=\"sense\"><b>—2)</b> <i>corner</i>. <span class=\"citation\">Ex. R. s. 37</span>, beg. (ref. to <span class=\"citation\">Zech. X, 4</span>) <span dir=\"rtl\">ממנו פ׳ זה וכ׳</span> ‘from him (Israel) the cornerstone is taken’, this refers to King David (with ref. to <span class=\"citation\">Ps. XVIII, 22</span>). <span class=\"citation\">Ab. d’R. N. ch. XXVIII</span> <span dir=\"rtl\">שלש מידות … אבן פ׳ וכ׳</span> there are three qualities of scholars, a hewn stone (seated in the wall), a corner stone &amp;c.; <span dir=\"rtl\">אבן פ׳ שיש לו שתי פיות וכ׳</span> (one versed in Midrash and Halakhah) is a corner stone which has two faces only.—Pl. as ab. <span class=\"citation\">Midd. I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">על ארבע</span> (<span dir=\"rtl\">פִּינּוֹתֶיהָ</span>) <span dir=\"rtl\">פִּינּוֹתָיו</span></span> in its four corners. <span class=\"citation\">Erub. 11ᵃ</span>, v. <a href=\"#\" data-headword=\"פֵּאָה\">פֵּאָה</a>.</div>","alt":["פִּנָּה"]},"22481":{"h":"פִּינּוּי","r":"Q00721","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>) <i>emptying, clearing.</i> <span class=\"citation\">Neg. XII, 5</span>; Sifra M’tsorʿa, <span class=\"citation\">Neg., ch. III</span>, Par. 5 (ref. to <span class=\"citation\">Lev. XIV, 36</span>) <span dir=\"rtl\">עסק הוא לפ׳</span> is the clearing of the house such important business?; <span class=\"citation\">Yalk. Lev. 566</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בכהן הצווי ופ׳ בכל אדם</span> the order must be issued by the priest, but the clearing may be done by anybody; a. e.</div>","alt":["פִּנּ׳"]},"22482":{"h":"פִּינּוּכָא","r":"Q00722","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּנַךְ\">פְּנַךְ</a>) <i>driving, speeding</i>. <span class=\"citation\">Targ. Jud. V, 22</span>.</div>","alt":["פִּנּ׳"]},"22483":{"h":"פִּינוֹלֵס","r":"Q00723","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (φαινόλης, φαιλόνης S. = pænula) <i>a travelling cloak, pænula</i>. Treat. Tsitsith (ed. Kirchh. p. 22) <a href=\"#\" data-headword=\"פילגס\">פילגס</a> (corr. acc.; <span class=\"citation\">Sifré Deut. 234</span> <a href=\"#\" data-headword=\"תכלא\">תכלא</a>; <span class=\"citation\">Yalk. ib. 933</span> <a href=\"#\" data-headword=\"תכלא\">תיכלא</a>, prob. to be read: <span dir=\"rtl\">פִּינוּלָא</span>). <span class=\"citation\">Y. Ned. X, end, 42ᵇ</span> <span dir=\"rtl\">מהו להתיר בפלונס</span> (not <span dir=\"rtl\">ם …</span>) is it permitted to act as judge in absolving from vows wrapped in a pænula (in place of a Tallith)?; <span class=\"citation\">Y. Ḥag. I, 76ᵈ</span> top <a href=\"#\" data-headword=\"פלנים\">פלנים</a> (corr. acc.).—Pl. <span dir=\"rtl\">פִּינוֹלִין</span>, <span dir=\"rtl\">פִּילוֹנִין</span>. <span class=\"citation\">Lam. R. to II, 2</span> מוכרי פילינין Ar. (ed. Koh. <a href=\"#\" data-headword=\"פילינון\">פילינון</a>, corr. acc.; ed. <span dir=\"rtl\">מוכרי טהרות</span>) sellers of pænulæ; <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> bot. <span dir=\"rtl\">אורגי פלגס</span> (corr. acc.) weavers of material for pænulæ.—<span class=\"citation\">Tosef. Kel. B. Bath. V, 11</span> <span dir=\"rtl\">פמליאות</span>, <span dir=\"rtl\">פימ׳</span> (R. S. to <span class=\"citation\">Kel. XXVIII, 8</span> <a href=\"#\" data-headword=\"פמילאות\">פמילאות</a>) read: <span dir=\"rtl\">פִּינוֹלָאוֹת</span>.</div>","alt":["פִּילוֹנֵס"]},"22484":{"h":"פִּינוֹן","r":"Q00724","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πῖλος, pilleum; <a href=\"#\" data-headword=\"נ\">נ</a> for <a href=\"#\" data-headword=\"ל\">ל</a>, cmp. <a href=\"#\" data-headword=\"לוּמָּא\">לוּמָּא</a>) <i>felt</i>; <span dir=\"rtl\">מנעלות הפ׳</span> felt-shoes. <span class=\"citation\">Kil. IX, 7</span>.</div>","alt":[]},"22485":{"h":"פינוסות","r":"Q00725","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. B. Bath. VI, 3</span>, sq., v. <a href=\"#\" data-headword=\"פִּיטּוּס\">פִּיטּוּס</a></div>","alt":[]},"22486":{"h":"פינוסין","r":"Q00726","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. IX, 2</span> <span dir=\"rtl\">בפ׳</span>, ed. Bub. <span dir=\"rtl\">בפיטסין</span>, read: <span dir=\"rtl\">בפִיסְטִין</span>.</div>","alt":[]},"22487":{"h":"פִּינּוּקָא","r":"Q00727","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּנַק\">פְּנַק</a>) <i>treating too tenderly, spoiling</i>. <span class=\"citation\">Targ. Prov. XIX, 10</span> (h. text <a href=\"#\" data-headword=\"תַּענוּג\">תענוג</a>).</div>","alt":["פִּנּ׳"]},"22488":{"h":"פִּינְחָס","r":"Q00728","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינְחָס\">פִּנְחָס</a></div>","alt":[]},"22489":{"h":"פִּינְטִיגוֹן","r":"Q00729","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּנְטִיגוֹן\">פֶּנְטִיגוֹן</a></div>","alt":[]},"22490":{"h":"פִּינִיתָא","r":"Q00730","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פִּינָּה\">פִּינָּה</a>, <i>street-corner</i>. <span class=\"citation\">Targ. Prov. VII, 8</span>, v. <a href=\"#\" data-headword=\"*עֵינוּתָא\">עֵינוּתָא</a>. <span class=\"citation\">Ib. 12</span>.</div>","alt":["פִּינְתָא","פִּנְ׳"]},"22491":{"h":"פִּינָךְ","r":"Q00731","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πίναξ) <i>dish, plate</i>. <span class=\"citation\">Y. Snh. XI, 30ᶜ</span> top <span dir=\"rtl\">פ׳ דסולת</span> a dish of fine flour. <span class=\"citation\">Y. Sabb. III, 6ᵇ</span> top. <span class=\"citation\">Ḥull. 111ᵇ</span> (Ar. ed. pr. <a href=\"#\" data-headword=\"פִּינְקָא\">פִּינְקָא</a>). <span class=\"citation\">Taan. 24ᵇ</span> (Ar. <a href=\"#\" data-headword=\"פִּינְקָא\">פינקא</a>); a. e.—Pl. <span dir=\"rtl\">פִּינָכֵי</span>. <span class=\"citation\">Pes. 49ᵃ</span> <span dir=\"rtl\">מלחיך פ׳</span> (Ar. Var. <span dir=\"rtl\">פִּינָקֵי</span>), v. <a href=\"#\" data-headword=\"לְחַךְ\">לְחַךְ</a>.</div>","alt":["פִּינְכָא"]},"22492":{"h":"פִּינָס","r":"Q00732","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a corrupt. of <a href=\"#\" data-headword=\"פִּינוֹלֵס\">פִּינוֹלֵס</a> q. v.) <i>travelling cloak</i>. <span class=\"citation\">Gen. R. s. 84</span> (ref. to <span dir=\"rtl\">ויפשיטו</span>, <span class=\"citation\">Gen. XXXVII, 23</span>) <span dir=\"rtl\">זה הפ׳</span> this refers to his cloak; Yalk. ib. 142. Ib. 133 <span dir=\"rtl\">עד שמכר פ׳ שלו</span> when he was compelled to sell his travelling cloak; (Yalk. Gen. s. 78 <span dir=\"rtl\">הסוס שלו</span>).</div>","alt":[]},"22493":{"h":"*פינסור","r":"Q00733","html":"<div class=\"sense\">, Tanḥ. Shof’ṭim 10 <span dir=\"rtl\">והיה הפ׳ שלה עומד וכ׳</span>, a corrupt., read: <span dir=\"rtl\">הקוּסְטוֹס</span> or <span dir=\"rtl\">הקוּסְטוֹד</span> (custos, -odis) the <i>guard</i> of the fort stood at the entrance, and when he entered and saw them &amp;c.; v. <a href=\"#\" data-headword=\"קוּסְטוֹדְיָא\">קוּסְטוּדְיָא</a>.</div>","alt":["פינסיר"]},"22494":{"h":"פִּינְקָא","r":"Q00734","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינָךְ\">פִּינְכָא</a></div>","alt":[]},"22495":{"h":"פִּינְקַאי","r":"Q00735","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Pinkay</i>. <span class=\"citation\">Ker. 28ᵃ</span>; <span class=\"citation\">Pes. 57ᵃ</span> <span dir=\"rtl\">פנ׳</span> (Ms. M. 2 <a href=\"#\" data-headword=\"פֶּנְטִיגוֹן\">פינ׳</a>; Ms. O. <a href=\"#\" data-headword=\"פִּינְקָא\">פִּינְקַי</a>, v. Rabb. D. S. a. l. note 3).</div>","alt":["פִּנְ׳"]},"22496":{"h":"פינקטין","r":"Q00736","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנִּיקְטִין\">פַּנִּיקְטִין</a></div>","alt":[]},"22497":{"h":"פִּינְקֵס","r":"Q00737","html":"<div class=\"sense\"> c. (πίναξ) <i>board, tablet</i>, esp. (πίνακες) the folded <i>writing tablets; register, list</i>. <span class=\"citation\">Sabb. XII, 4</span>, v. <a href=\"#\" data-headword=\"לוּחַ II\"><span dir=\"rtl\">לוּחַ</span> II</a>. <span class=\"citation\">Ib. 5</span> <span dir=\"rtl\">על שני דפי פ׳</span> on two boards of a pinax (Rashi: two columns on one tablet). <span class=\"citation\">Nidd. 30ᵇ</span> the embryo in the womb <span dir=\"rtl\">דומה לפ׳ שמקופל</span> resembles in position a folded pinax. <span class=\"citation\">Gen. R. s. 69</span> (ref. to <span class=\"citation\">Gen. XXVIII, 13</span>) <span dir=\"rtl\">קפלה כפ׳ ונתנה וכ׳</span> he (the Lord) folded it (the land) like a pinax and placed it under his (Jacob’s) head; a. fr.—Esp. <i>the merchant’s accounts, book.</i> <span class=\"citation\">Ab. III, 16</span> <span dir=\"rtl\">הפ׳ פתוח והיד וכ׳</span> the book of (God’s) accounts lies open, and the hand writes, and whosoever wishes to borrow may come and borrow &amp;c. <span class=\"citation\">Shebu. VII, 1</span> החנוני על פִּינַקְסוֹ Y. ed. (Mish. a. Bab. ed. <span dir=\"rtl\">פנ׳</span>), v. <a href=\"#\" data-headword=\"חֶנְוָונִי\">חֶנְוָונִי</a>. Ib. <span dir=\"rtl\">כתוב בפִינַקְסִי וכ׳</span> Y. ed. (Mish. a. Bab. <span dir=\"rtl\">על פנ׳</span>) it is written in my book that thou owest me &amp;c. Y. Ned. I, 36ᵈ <span dir=\"rtl\">פינקסו נפתחת</span> his account book is open (his sins will be visited); <span class=\"citation\">ib.</span> <a href=\"#\" data-headword=\"פינקסתו\">פינקסתו</a> (corr. acc.). <span class=\"citation\">Gen. R. s. 81</span>, v. <a href=\"#\" data-headword=\"בָּקַר\">בָּקַר</a>; a. fr.—Pl. <span dir=\"rtl\">פִּינַקְסִין</span>, <span dir=\"rtl\">פִּינַקְסָאוֹת</span>, <span dir=\"rtl\">פִּינַקְסָיוֹת</span>, <a href=\"#\" data-headword=\"פִּינְקֵס ²\">פִּנַ׳</a>. <span class=\"citation\">Kel. XXIV, 7</span>, v. <a href=\"#\" data-headword=\"אִפֹּופֹּודִין\">אִפּוֹפּוֹדִין</a>. <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">דיפתראות ופ׳ יש לו</span> he (the builder) has before him rolls and tablets (plans and descriptions). <span class=\"citation\">Y. R. Hash. I, 57ᵃ</span> bot. <span dir=\"rtl\">שלש פ׳ וכ׳</span> there are three books (before the Lord), one for the perfectly righteous &amp;c. (Bab. <span class=\"citation\">ib. 16ᵇ</span> <span dir=\"rtl\">ספרים</span>); a. e.</div>","alt":["פִּנְקֵס"]},"22498":{"h":"פִּינְקֵס ²","r":"Q00738","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ez. IX, 2</span>, sq. (h. text <span dir=\"rtl\">קסת</span>). Targ. II Esth. IV, 1 <span dir=\"rtl\">ופִינְקְסֵיה</span>; a. e.—<span class=\"citation\">Y. Sabb. V, end, 7ᶜ</span>, v. <a href=\"#\" data-headword=\"גִּימוֹן\">גִּימוֹן</a>. Ib. XII, end, 13ᵈ <span dir=\"rtl\">מאן דאמר חוקק כגון ההן פ׳</span> he who says the term <a href=\"#\" data-headword=\"כְּתַב I\">כתב</a> applies also to engraving, means engraving like that on the wax-covered tablet, opp. <span dir=\"rtl\">בולט</span>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot. I saw in my dream <span dir=\"rtl\">לביש חד פ׳ וכ׳</span> (<span dir=\"rtl\">דהוינא</span>) that I was covered with a pinax of twelve tablets; <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">רבתי דהוינא טעין חד פ׳ וכ׳</span> (<span dir=\"rtl\">חד כות׳</span>) that I was carrying a pinax &amp;c. <span class=\"citation\">Y. Maasr. II, 49ᵈ</span> bot. <span dir=\"rtl\">אשכחון כתיב בפִינַקְסֵיה וכ׳</span> (not <a href=\"#\" data-headword=\"כְּתַב I\">כתב</a>) they found written in a memorandum of &amp;c.; a. e.—Pl. <span dir=\"rtl\">פִּינַקְסִין</span>, constr. <span dir=\"rtl\">פִּינְקְסֵי</span>, <a href=\"#\" data-headword=\"פִּינּוּי\">פִּנָ׳</a>. <span class=\"citation\">Targ. Y. Gen. XXXIX, 11</span>.</div>","alt":["פִּינַקְסָא","פִּינַקְסָה","פִּנַ׳"]},"22499":{"h":"פינקסתו","r":"Q00739","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינְקֵס\">פִּינְקֵס</a> h.</div>","alt":[]},"22500":{"h":"פַּיִס","r":"Q00740","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פַּיִיס\">פַּיִיס</a>), v. <a href=\"#\" data-headword=\"פִּיסְטִין\">פִּיסְטִין</a>.—[Pl. <a href=\"#\" data-headword=\"פִּיסִּים\">פִּיסִּים</a>, <a href=\"#\" data-headword=\"פִּיסִּים\">פִּיסִּין</a> q. v.]</div>","alt":["פִּיס"]},"22501":{"h":"פִּיס","r":"Q00741","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>) <i>to split, divide, distribute</i>.</div><div class=\"sense\"><b>Hif. הֵפִיס</b> <div class=\"sense\"><b>1)</b> <i>to penetrate</i>, (cmp. <a href=\"#\" data-headword=\"בָּדַק\">בָּדַק</a>); <i>to cause abdominal trouble</i>. <span class=\"citation\">Pes. 107ᵃ</span> <span dir=\"rtl\">מִיסְרָן ומֵפִיס</span> this drink is a tempter and then gives pain (Ms. M. <span dir=\"rtl\">ומֵיפֵיס</span>; Ms. O. <span dir=\"rtl\">מייסרן ומיפיס</span>, v. <a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>; ed. <span dir=\"rtl\">ומפייס</span>, v. infra).—[<span dir=\"rtl\">מפיס מורסא</span>, v. <a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to break a person’s anger</i> or <i>will, to pacify, persuade, comfort</i>. <span class=\"citation\">Shebu. 45ᵃ</span> <span dir=\"rtl\">כדי להָפִיס דעתו וכ׳</span> in order to satisfy the mind of the employer (to convince him that he was mistaken). Y. ib. VIII, 38ᵈ top; Y. Snh. III, 21ᶜ bot. <span dir=\"rtl\">מצוה להֲפִיסוֹ</span> it is proper to give him (the owner of the lost animal) satisfaction (by stating the cause of the loss); v. <i>Pi.</i>—<span class=\"citation\">Ab. Zar. 71ᵃ</span> <span dir=\"rtl\">צא והָפֵס עלי מנת המלך</span> go and satisfy for me the royal taxes (settle for me as best you can), v. <a href=\"#\" data-headword=\"מְנָת\">מְנָת</a>.</div><div class=\"sense\"><b>—3)</b> <i>to arbitrate, decide</i> (cmp. <a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>). <span class=\"citation\">Sabb. 33ᵃ</span> <span dir=\"rtl\">מי מֵפִיס</span> who will decide (as to the cause of my disease)? <span class=\"citation\">Ib. 54ᵃ</span> <span dir=\"rtl\">מי מפיס וכ׳</span> who will decide which udders are tied up for the purpose of drying them up and which for the purpose of preserving the milk?—Esp. <i>to decide by chance, by drawing lots, counting a certain number</i> &amp;c. (v. <a href=\"#\" data-headword=\"פַּיִיס\">פַּיִיס</a>). <span class=\"citation\">Tam. I, 2</span> <span dir=\"rtl\">מי שטבל יבוא ויָפִיס</span> let those who have bathed, come and take part in the count of chance; <span dir=\"rtl\">הֵפִיסוּ זכה וכ׳</span> after they have drawn, he who has won, has won (no appeal is permitted). <span class=\"citation\">Yoma 24ᵇ</span> <span dir=\"rtl\">למה מְפִיסִין וחוזרין וכ׳</span> why did they draw once and again (why not at once for all the functions to be distributed)? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">במה מפיסין</span> (Rashi: <span dir=\"rtl\">מפייסין</span>) what garments do they wear when drawing? <span class=\"citation\">Gen. R. s. 84</span> (play on <span dir=\"rtl\">פסים</span>, <span class=\"citation\">Gen. XXXVII, 23</span>) <span dir=\"rtl\">שהפיסו עליה וכ׳</span> they drew lots about it (the coat) as to who should carry it to his father &amp;c. <span class=\"citation\">Sabb. XXIII, 2</span> (<span class=\"citation\">148ᵇ</span>) <span dir=\"rtl\"><span dir=\"rtl\">מפיס</span> (<span dir=\"rtl\">אדם</span>) <span dir=\"rtl\">עם וכ׳</span></span> a man may decide by lot (on the Sabbath) the shares of honor at the table &amp;c.; ib. 149ᵇ; a. e.</div></div><div class=\"sense\"><b>Pi. פִּיֵּיס</b> <div class=\"sense\"><i>to pacify, conciliate, persuade</i>. Pes. l. c. <span dir=\"rtl\">מְיַסְּרָן ומְפַיֵּיס</span> (that drink) chastises us (gives us pain), and yet is so persuasive (tempting). <span class=\"citation\">Ber. 28ᵇ</span> אני יכול לפַיְּיסוֹ בדברים וכ׳ I might appease him with words or bribe him with money. <span class=\"citation\">B. Bath. 9ᵇ</span> <span dir=\"rtl\">כל הנותן … והמְפַיְּיסוֹ בדברים וכ׳</span> he who gives a poor man a coin will be blessed with six blessings, but he who speaks kindly to him, will be blessed with eleven blessings. <span class=\"citation\">Gen. R. s. 93</span>, end <span dir=\"rtl\">כשם שלא פ׳ … אלא וכ׳</span> as Joseph pacified his brothers only by weeping &amp;c. Y. Snh. l. c. <span dir=\"rtl\">מצוה להפיסו … ואינו מְפַיְּיסוֹ על שקר</span> it is right to satisfy his mind by stating the truth, but one must not do so by a falsehood; Y. Shebu. l. c. <span dir=\"rtl\">מפייסו … אינו מפייסו וכ׳</span>. <span class=\"citation\">Lev. R. s. 19</span>, end <span dir=\"rtl\">נלך ונְפַיֵּיס לגדלת</span>, v. <a href=\"#\" data-headword=\"גַּדֶּלֶת\">גַּדֶּלֶת</a>; a. fr.—<span class=\"citation\">Gen. R. s. 94</span>, end <span dir=\"rtl\">ופייליה</span>, read: <span dir=\"rtl\">ופִיְּיסוּהוּ</span> and they appeased him (Nebuchadnezzar).—Part. pass. <span dir=\"rtl\">מְפוּיָּיס</span>. <span class=\"citation\">Ex. R. s. 51</span> הריני מפ׳ שמחלת וכ׳ I am convinced that thou hast forgiven Israel.</div></div><div class=\"sense\"><b>Hithpa. הִתְפַּיֵּיס</b> </div><div class=\"sense\"><b>Nithpa. נִתְפַּיֵּיס</b> <div class=\"sense\"><i>to be appeased, satisfied, persuaded</i>. Ib. <span dir=\"rtl\">אותה שעה נֵתְפַּיְּיסוּ … על וכ׳</span> now all Israelites were satisfied with regard to the work of the Tabernacle (that everything was correct). <span class=\"citation\">Ber. 33ᵃ</span> <span dir=\"rtl\">נתפ׳ אותו השר</span> that prince’s anger was appeased. <span class=\"citation\">Pesik. R. s. 10</span> <span dir=\"rtl\">הרי הגורן בא והכל מִתְפַּיְּיסִים בשביל וכ׳</span> when harvesting time comes, all (that now are disputing) will be convinced for whose sake the field has been sown. <span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">ספק מִתְפַּיֵּיס הימנו וכ׳</span> it is doubtful whether he will or will not accept his apology; <span dir=\"rtl\">ספק מתפייס בדברים וכ׳</span> it is doubtful whether he will be appeased by mere words (without demanding a fine or public satisfaction) &amp;c.; a. fr.</div></div>","alt":[]},"22502":{"h":"פִּיס ²","r":"Q00742","html":"<div class=\"sense\"><b>1)</b> <i>to distribute</i>, v. <a href=\"#\" data-headword=\"פְּסַס\">פְּסַס</a>.</div><div class=\"sense\"><b>—2)</b> <i>to break, desecrate</i>, v. infra.</div><div class=\"sense\"><b>Af. אָפֵיס</b> <div class=\"sense\">, (<a href=\"#\" data-headword=\"פְּסַס\">אַפֵּיס</a>) <i>to break, weaken; to desecrate</i>. <span class=\"citation\">Targ. Y. II, Num. XV, 31</span> (h. text <span dir=\"rtl\">הפר</span>). <span class=\"citation\">Targ. Hos. IV, 9</span> (ed. Wil. <a href=\"#\" data-headword=\"*אָפִיס\">אֲפִיס</a> <i>Pe.</i>). Ib. <span dir=\"rtl\">לַאֲפָסָא</span>. <span class=\"citation\">Targ. Y. Lev. XIX, 8</span> (h. text <a href=\"#\" data-headword=\"חָלַל\">חלל</a>). <span class=\"citation\">Ib. XXI, 8</span> <span dir=\"rtl\">תַפְסִינֵיה</span> (fr. <a href=\"#\" data-headword=\"פסי\">פסי</a>). <span class=\"citation\">Ib. 6</span> <span dir=\"rtl\">יַפְסוּן</span> (ed. Vien., a. Y. II <span dir=\"rtl\">יִפְסוּן</span>, <i>Pe.</i>). <span class=\"citation\">Targ. Job XV, 4</span> <span dir=\"rtl\">תָּפֵישׂ</span> (ed. Wil. <span dir=\"rtl\">תָּפֵשׁ</span>, corr. acc.; h. text <span dir=\"rtl\">תפר</span>). <span class=\"citation\">Targ. Y. Num. XXV, 1</span> <span dir=\"rtl\">לאוֹפָסָא</span> (cmp. <a href=\"#\" data-headword=\"אוֹקִים\">אוֹקִים</a> fr. <a href=\"#\" data-headword=\"קוּם\">קוּם</a>). <span class=\"citation\">Targ. Ps. LIII, 1</span> <span dir=\"rtl\">מַפְסִין</span> (some ed. <span dir=\"rtl\">מְפַסִּין</span> <i>Pa.</i>, fr. <a href=\"#\" data-headword=\"פסי\">פסי</a>); a. fr.—<span class=\"citation\">Targ. Y. I Deut. XXIII, 18</span> <span dir=\"rtl\">תִפְסוּן</span> ed. Amst. (ed. Vien. <span dir=\"rtl\">תספון</span>, corr. acc.).—Part. pass. f. <span dir=\"rtl\">מַפְסָה</span>. <span class=\"citation\">Targ. Y. II, Lev. XXI, 7</span> (h. text <span dir=\"rtl\">חללה</span>).—V. <a href=\"#\" data-headword=\"פְּסַס\">פְּסַס</a>.</div></div><div class=\"sense\"><b>Pa. פַּיֵּיס</b> <div class=\"sense\"><b>1)</b>  (with (with <a href=\"#\" data-headword=\"ב\">ב־</a>) [<i>to split, drive into</i>, v. <a href=\"#\" data-headword=\"*פְּצַר\">פְּצַר</a>,] <i>to press, urge</i>. <span class=\"citation\">Targ. Y. Gen. XIX, 3</span> (h. text <span dir=\"rtl\">ויפצר</span>).</div><div class=\"sense\"><b>—2)</b> <i>to break a man’s vehemence; to quiet, appease, reconcile, persuade, pray</i>. <span class=\"citation\">Targ. Esth. VIII, 3</span> <span dir=\"rtl\">ופַיְיסַת ליה</span> (h. text <span dir=\"rtl\">ותתחנן</span>). <span class=\"citation\">Targ. Y. Gen. XLII, 21</span>; a. e.—<span class=\"citation\">Ḥull. 95ᵃ</span> top <span dir=\"rtl\">אי הוות פַּיְיסַת מינאי וכ׳</span> if thou hadst asked my pardon (made peace with me) &amp;c. <span class=\"citation\">Ib. 94ᵃ</span> [read:] <span dir=\"rtl\">פַּיְּיסֵיה למבורין</span> secure the good will of our ferryman (make him a present); <span dir=\"rtl\">פייסיה ואיקפד</span> he offered him a present, and he (the ferryman) became angry. <span class=\"citation\">Yoma 87ᵃ</span> איזיל אנא לפַיּוּסֵי ליה I will go and make peace with him. Y. Snh. XI, 30ᶜ top; Y. Ber. IX, 13ᵈ top <span dir=\"rtl\">פייסיה עלי</span> make him (the idol) favorably disposed towards me. <span class=\"citation\">Taan. 24ᵃ</span> ומְפַיַּיסְנָא ליה וכ׳ Ms. M. (ed. <span dir=\"rtl\">ומְפַיְּיסִינָן</span>) and I persuade him (the pupil), until he comes and reads. <span class=\"citation\">Meg. 12ᵃ</span> <span dir=\"rtl\">דבני מאתיה … מפייס להו</span> for, as to the residents of his own place, he can win their favor, whenever he wants; a. fr.—Part. pass. <span dir=\"rtl\">מְפַיַּיס</span>; f. <span dir=\"rtl\">מְפַיְּיסָא</span>; pl. <span dir=\"rtl\">מְפַיְּיסִין</span>; <span dir=\"rtl\">מְפַיְּיסָן</span>. Y. Ab. Zar. II, 41ᵈ bot. <span dir=\"rtl\">ישכח אפין מפייסן</span> (not <span dir=\"rtl\">מפייסא</span>) he may find a friendly face (a well-disposed judge).</div></div><div class=\"sense\"><b>Ithpe. אִיתְּפִיס  אִיתְּפֵס</b> <div class=\"sense\"><b>1)</b> <i>to be broken, degraded</i>. <span class=\"citation\">Targ. Job XV, 20</span> <span dir=\"rtl\">מִתְּפִיס</span> (ed. Lag. <span dir=\"rtl\">מתפס</span>; ed. Wil. <span dir=\"rtl\">מִתַּפֵּס</span>, <i>Ithpa.</i> of <span dir=\"rtl\">פסס</span> or of <a href=\"#\" data-headword=\"תְּפַס II\"><span dir=\"rtl\">תְּפַס</span> II</a>; h. text <span dir=\"rtl\">מתחולל</span>).—[<span class=\"citation\">Targ. Y. I Deut. XXIII, 18</span> <span dir=\"rtl\">יִתְפַּס</span> ed. Amst., v. <a href=\"#\" data-headword=\"תְּפַס II\"><span dir=\"rtl\">תְּפַס</span> II</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to be appeased; to yield</i>. <span class=\"citation\">Targ. Prov. VI, 35</span> (h. text <span dir=\"rtl\">יאבה</span>).</div></div><div class=\"sense\"><b>Ithpa. אִתְפַּיֵּיס  אִיפַּ׳</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"פִּיס\">same</a>. <span class=\"citation\">Targ. Y. Gen. XXXIV, 15</span> (h. text <span dir=\"rtl\">נאות</span>). <span class=\"citation\">Ib. 22</span>; a. e. (v. <a href=\"#\" data-headword=\"טְפַס\">טְפַס</a>).—<span class=\"citation\">Yoma 23ᵃ</span> <span dir=\"rtl\">דמפייסו ליה ומִיפַּיֵּיס</span> when they ask his pardon, and he is appeased (forgives). <span class=\"citation\">Num. R. s. 5</span>, end <span dir=\"rtl\">מאן פייסך דאִיפַּיְּיסַת</span> who asked thy pardon, that thou wast appeased?; <span class=\"citation\">Sot. 35ᵇ</span>; a. fr.</div></div>","alt":["(פְּסֵי)"]},"22503":{"h":"פִּיסָא","r":"Q00743","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּיס ²\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"פַּיָּיס\">פַּיָּיס</a> <i>lump of brittle stone</i>. <span class=\"citation\">Snh. 64ᵃ</span> <span dir=\"rtl\">שקל פ׳ שדא ביה</span> he took up a lump and threw it at it (the idolatrous statue). <span class=\"citation\">Macc. 8ᵃ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  = h. <a href=\"#\" data-headword=\"פַּיִיס\">פַּיִיס</a>, v. <a href=\"#\" data-headword=\"פְּיָיסָא\">פְּיָיסָא</a></div>","alt":[]},"22504":{"h":"פִּיסָּא","r":"Q00744","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּס II\"><span dir=\"rtl\">פַּס</span> II</a> ch.</div>","alt":[]},"22505":{"h":"פִּיסְגָּא","r":"Q00745","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּסְגָּא\">פִּסְגָּא</a></div>","alt":[]},"22506":{"h":"פִּיסָּה","r":"Q00746","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"פִּיסָּא\">פִּיסַּת</a>, v. <a href=\"#\" data-headword=\"פַּס II\"><span dir=\"rtl\">פַּס</span> II</a> h.</div>","alt":[]},"22507":{"h":"פִּיסּוּגָא","r":"Q00747","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסוּגָא\">פְּסוּגָא</a></div>","alt":[]},"22508":{"h":"פִּיסּוּל","r":"Q00748","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַל\">פָּסַל</a>) <i>cutting off</i> dry twigs, <i>trimming.</i> <span class=\"citation\">Shebi. II, 3</span> <span dir=\"rtl\">כפִיסּוּלָהּ של חמישית</span> the trimming as it is done in the fifth year, contrad. to <a href=\"#\" data-headword=\"זֵירוּד I\">זֵירוּד</a>. Ib. <span dir=\"rtl\">כל זמן … רשאי אני בפִסּוּלוֹ</span> as long as I am permitted to do what is necessary to cultivate the tree, I am also permitted to trim it; Y. ib. 33ᵈ אני רשאי בפיסולו עד העצרת ‘I am permitted to trim it’, that means up to the festival of Shabuoth.—Pl. <span dir=\"rtl\">פִּיסּוּלִים</span>, <span dir=\"rtl\">פִּיסּוּלִין</span>, <a href=\"#\" data-headword=\"פִּיסּוּל\">פִּסּ׳</a> <i>chiselled</i> (millstones). <span class=\"citation\">Ḥull. 88ᵇ</span>, v. <a href=\"#\" data-headword=\"נִקְרָה\">נִקְרָה</a>.</div>","alt":["פִּסּ׳"]},"22509":{"h":"פִּיסּוּלָא","r":"Q00749","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פְּסוּל\">פְּסוּל</a>, <i>disqualification, blemish; disqualified, unworthy person</i>. <span class=\"citation\">Targ. Y. Gen. XXXV, 22</span>; a. e.—Pl. <a href=\"#\" data-headword=\"פִּיצּוּלַיָּא\">פִּיסּוּלַיָּא</a>. <span class=\"citation\">Targ. Y. Lev. XXI, 14</span>.</div>","alt":[]},"22510":{"h":"פִּיסוֹן","r":"Q00750","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּיס\">פִּיס</a>, v. <a href=\"#\" data-headword=\"פִּיסָא\">פִּיסָא</a>) <i>mortar-maker, mason</i>.—Pl. <span dir=\"rtl\">פִּיסוֹנוֹת</span>. <span class=\"citation\">Kel. XX, 2</span>.</div>","alt":[]},"22511":{"h":"פִּיסּוּק","r":"Q00751","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>) </div><div class=\"sense\"><b>1)</b> <i>separation, interruption, pause</i>. <span class=\"citation\">Zeb. 53ᵇ</span> פ׳ ארבע מתנות Rashi a. Ms. R. (v. Rabb. D. S. a. l. note 60; ed. <span dir=\"rtl\">וארבע</span>) four separate manipulations (with pauses between them), v. <a href=\"#\" data-headword=\"מַתָּנָה\">מַתָּנָה</a>; <span class=\"citation\">Yalk. Lev. 441</span>.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">פ׳ טַעֲמִים</span> (or sub. <span dir=\"rtl\">טעמים</span>; v. <a href=\"#\" data-headword=\"טַעַם\">טַעַם</a>) <i>the division of words into clauses in accordance with the sense, punctuation</i>. <span class=\"citation\">Ned. 37ᵃ</span> <span dir=\"rtl\">שכר פ׳</span> (<a href=\"#\" data-headword=\"ט׳\">ט׳</a>) remuneration for teaching the values of punctuation signs or accents, v. <a href=\"#\" data-headword=\"פֶּסֶק\">פֶּסֶק</a>.</div><div class=\"sense\"><b>—3)</b> <i>setting a price on fruits before they are harvested</i>. <span class=\"citation\">Y. B. Mets. V, 10ᶜ</span> bot. <span dir=\"rtl\">בפ׳ איתפלגון</span> they differ as to permission to fix the price &amp;c., opp. to <span dir=\"rtl\">מלוה</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אבל בפונדק</span> (corr. acc.).</div><div class=\"sense\"><b>—4)</b>  פ׳ רַגְלַיִם <i>spreading the feet</i>. <span class=\"citation\">Keth. 39ᵇ</span> <span dir=\"rtl\">צער של פ׳ הר׳</span> the pain caused by forcing her feet apart (ref. to <span class=\"citation\">Ez. XVI, 25</span> <span dir=\"rtl\">ותפשקי</span>).</div>","alt":["פִּסּ׳"]},"22512":{"h":"פִּ","r":"Q00752","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְחָא\">פִּסְחָא</a></div>","alt":["י","סְחָא"]},"22513":{"h":"פִּיסְטִין","r":"Q00753","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (πίστις) <i>trust</i>. <span class=\"citation\">Yalk. Ps. 672</span> <span dir=\"rtl\">נוטלין … ופורעין בפ׳</span> they borrow from one another in trust (without witnesses or note) and pay in trust; <span class=\"citation\">Midr. Till. to Ps. XIX</span> <span dir=\"rtl\">בפינוסין</span>, ed. Bub. <span dir=\"rtl\">בפטסין</span> (corr. acc.).—Esp. <span dir=\"rtl\">שטר פ׳</span> <i>a deed of trust</i>, an instrument by which property is conveyed to a person in trust (fideicommissum) to use it in a certain way; <i>a feigned sale</i> or <i>donation</i> (for the purpose of eluding creditors &amp;c.). <span class=\"citation\">Y. Keth. II, 26ᵇ</span> bot. <span dir=\"rtl\">נאמנין … ושטר פ׳ הוא</span> (not <a href=\"#\" data-headword=\"פוסיטים\">פוסיטים</a>, <a href=\"#\" data-headword=\"פיסיטים\">פיסיטים</a>) witnesses (signed on an instrument) are credited when they say, it was a deed of trust (v. <a href=\"#\" data-headword=\"אֲמָנָה\">אֲמָנָה</a>), or it was a feigned transfer. <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Job XI, 14</span>) ‘if there be wrong in thy house, remove it’, this means a deed &amp;c.; Bab. <span class=\"citation\">Keth. 19ᵇ</span> <span dir=\"rtl\">פסים</span>, (read with Ar. <a href=\"#\" data-headword=\"פָּסִיס\">פָּסִיס</a> q. v.). Ib. 79ᵃ <span dir=\"rtl\">הרוצה … כותבת שטר פסים לאחרים</span> if a woman desires to withhold her property from her husband’s control, she may write out a deed of trust (a feigned transfer) to a third person (prior to her marriage); Tosef. ib. IX, 2 <span dir=\"rtl\">כותבן שטר פטים לאחר</span> ed. Zuck. (Var. <span dir=\"rtl\">בטפיח</span>, <span dir=\"rtl\">כותבתן בטפוס</span>, corr. acc.). <span class=\"citation\">B. Bath. 154ᵇ</span> <span dir=\"rtl\">אם אמר שטר פסים הוא זה</span> (Ms. H. <span dir=\"rtl\">פיס</span>) if he says, it was a feigned sale (you persuaded me to a nominal sale in order to make people believe that you are a man of means).</div>","alt":["פִּיסְטִיס","פִּסְ׳"]},"22514":{"h":"פיסטירין","r":"Q00754","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְטוֹר\">מִסְטוֹר</a></div>","alt":[]},"22515":{"h":"פִּיסְטַלְיוֹת","r":"Q00755","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (an adapt. of ἐπιστύλια, as if a reduplic. of <a href=\"#\" data-headword=\"פָּסַל\">פָּסַל</a>) <i>lintels on the top of a pillar, epistyles</i>. <span class=\"citation\">Y. Succ. I, 52ᵃ</span> bot. [read:] <span dir=\"rtl\">ארבעה עמודים ועליהם ארבע פ׳</span> (Mus. <span dir=\"rtl\">אפיס׳</span>) four columns and on top of them four epistyles (extending beyond the columns); <span class=\"citation\">Y. Erub. I, 19ᶜ</span> <span dir=\"rtl\">פִּצְטַלְיוֹת</span>.</div>","alt":[]},"22516":{"h":"פִּיסְטְקִין","r":"Q00756","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (πιστάκια) <i>pistachio-nuts</i>. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> bot. (Ar. <a href=\"#\" data-headword=\"פִּסְתְּקָא\">פסתקין</a>), v. <a href=\"#\" data-headword=\"בּוּטְמָא\">בּוּטְמָא</a>. Y. Maasr. I, 48ᵈ bot. <span dir=\"rtl\">איפסט׳</span> (v. <a href=\"#\" data-headword=\"אַפִּסְטְקִין\">אַפִּסְטְקִין</a>; <span class=\"citation\">Tosef. Maasr. I, 1</span> <span dir=\"rtl\">הפרסקין</span> (corr. acc.).—V. <a href=\"#\" data-headword=\"פִּיסְתְּקָא\">פִּיסְתְּקָא</a>.</div>","alt":[]},"22517":{"h":"פיסיאו","r":"Q00757","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*פיספיסאי\">פיספיסאי</a></div>","alt":[]},"22518":{"h":"פִּיסָּיוֹן","r":"Q00758","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פִּיסּוּל\">פִּס׳</a>.</div>","alt":["פִּיסְיוֹן","פִּיסְיוֹנָא","פִּיסְיוֹנִי"]},"22519":{"h":"פיסיטים","r":"Q00759","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְטִין\">פִּיסְטִיס</a></div>","alt":["פיסיטיס"]},"22520":{"h":"פִּיסִּים","r":"Q00760","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>, v. <a href=\"#\" data-headword=\"פַּס II\"><span dir=\"rtl\">פַּס</span> II</a>) [<i>distributions</i>, cmp. Lat. tributum,] <i>taxes</i>, esp. <i>pissim, pissin</i>, name of a <i>Roman tax</i> laid on the community and distributed by the latter according to assessments (v. Sm. Ant. s. v. Vectigalia). <span class=\"citation\">Y. Peah I, 15ᵇ</span> bot. (ref. to <span class=\"citation\">Prov. III, 26</span>) <span dir=\"rtl\">אם נתת … משמרך מן הפ׳ וכ׳</span> if thou givest charity out of thy pocket (voluntarily), the Lord will guard thee from tributes, fines &amp;c.; <span class=\"citation\">Gen. R. s. 1</span>. <span class=\"citation\">Y. Ab. Zar. IV, 44ᵇ</span>; <span class=\"citation\">Y. Shebi. IV, 35ᵇ</span> <span dir=\"rtl\">אתם מגלגלין עלינו פ׳ וזימיות וכ׳</span> you impose upon us tributes and fines &amp;c. <span class=\"citation\">Yalk. Jer. 312</span> <span dir=\"rtl\">משתעבדין … בפ׳ ובהוניות וכ׳</span> are oppressed by tributes, confiscations &amp;c.; Pesik. Baḥod. p. 151ᵃ <span dir=\"rtl\">במסים</span> (corr. acc.); a. fr.</div>","alt":["פִּיסִּין","פִּסּ׳"]},"22521":{"h":"פִּיסְעָא","r":"Q00761","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַע\">פְּסַע</a>) <i>step</i>. <span class=\"citation\">Targ. I Sam. XX, 3</span> (h. text <span dir=\"rtl\">פשע</span>).—V. <a href=\"#\" data-headword=\"פְּסִיעֲתָא\">פְּסִיעֲתָא</a>.</div>","alt":["פִּסְ׳"]},"22522":{"h":"*פיספיסאי","r":"Q00762","html":"<div class=\"sense\">, Pesik. Vattom., p. 131ᵃ <span dir=\"rtl\">פ׳ פיסיאו</span> (Ms. O. <span dir=\"rtl\">פיספיאי</span>, Ms. Parma <span dir=\"rtl\">פיספין</span>), a corrupt. of a Greek sentence, prob. ὅπως ποιοῦσι ποιήσω, as they act, so will I act, expl. in Chald. <span dir=\"rtl\">אינין עבדין ואנא עבדית</span>.</div>","alt":[]},"22523":{"h":"פִּיסְפֵּס","r":"Q00763","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְפֵּס I\">פִּסְפֵּס</a></div>","alt":[]},"22524":{"h":"פִּיסְפָּס","r":"Q00764","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִיפָּס\">פְּסִיפָּס</a></div>","alt":[]},"22525":{"h":"פִּיסָּק","r":"Q00765","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>) </div><div class=\"sense\"><b>1)</b> <i>interruption.</i>—Pl. <span dir=\"rtl\">פִּיסְּקִין</span>. <span class=\"citation\">Y. Shek. III, 47ᵇ</span> bot. <span dir=\"rtl\">לשתותן בפ׳</span> to drink them (the four cups) at intervals, v. <a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>.</div><div class=\"sense\"><b>—2)</b> <i>slope</i> or <i>embankment by the roadside.</i>—<i>Pl.</i> as ab. Tosef. Erub. X (VII), 2 <span dir=\"rtl\">ההרים והפ׳ וכ׳</span> ed. Zuck. (oth. ed. <span dir=\"rtl\">החרים והפסקן</span>; El. Wil. emends <a href=\"#\" data-headword=\"פסקן\">פסקנין</a>) hills, slopes, or a ship by the side of a public road (v. <span class=\"citation\">Tosef. Sabb. X</span> (<span class=\"citation\">XI), 4</span>).</div>","alt":[]},"22526":{"h":"פִּיסְקָא","r":"Q00766","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְקָא\">פִּסְקָא</a></div>","alt":[]},"22527":{"h":"פִּיסְקוֹן","r":"Q00767","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>) <i>Pisḳon</i> (<i>Arguer</i>), surname of the angel Gabriel. <span class=\"citation\">Snh. 44ᵇ</span>, v. <a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>.—<i>Fem</i>. <a href=\"#\" data-headword=\"פִּסְקוֹן\">פִּסְקוֹנִית</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">רוח פ׳</span> (Rashi: <a href=\"#\" data-headword=\"פִּסְקָנִית\">פִּסְקָנִית</a>) the arguing spirit (Gabriel). Tanḥ. V’zoth 6.</div>","alt":[]},"22528":{"h":"פִּיסְקְיָא","r":"Q00768","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פְּסִיקְיָא</a></div>","alt":[]},"22529":{"h":"פִּיסְקִינוֹת","r":"Q00769","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (piscina) <i>fish-ponds</i>, in gen. <i>ponds, reservoirs</i>. <span class=\"citation\">Koh. R. to II, 6</span> (expl. <span dir=\"rtl\">ברכות מים</span> ib.) <span dir=\"rtl\">פי׳</span> (not <span dir=\"rtl\">פו סקינוס</span>); <span class=\"citation\">Yalk. ib. 967</span> <a href=\"#\" data-headword=\"פיסקניות\">פיסקניות</a> (corr. acc.).—[V., however, <a href=\"#\" data-headword=\"פְּסֵיקָה\">פְּסֵיקָה</a>.]</div>","alt":[]},"22530":{"h":"פיסקניות","r":"Q00770","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְקִינוֹת\">preced.</a></div>","alt":[]},"22531":{"h":"פִּיסְקְתָא","r":"Q00771","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a>) <i>a small share, portion</i>. <span class=\"citation\">B. Bath. 151ᵃ</span> <span dir=\"rtl\">פ׳ דפרדיסא</span> (Ms. F. <a href=\"#\" data-headword=\"פְּסִיקְתָּא\">פְּסִיקְתָּא</a>) a small portion of an orchard.</div>","alt":[]},"22532":{"h":"פִּיסְּתָא","r":"Q00772","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"פַּס\">פַּסָּא</a>, </div><div class=\"sense\"><b>1)</b>  פִּיסַּת ידא <i>the hand up to the wrist</i>; <span dir=\"rtl\">פ׳ כף רגלא</span> <i>the foot up to the ankle</i>. <span class=\"citation\">Targ. I Kings XVIII, 44</span>; a. e.—<span class=\"citation\">Yeb. 115ᵃ</span> <span dir=\"rtl\">פ׳ דידא וכ׳</span> (see) the hand that lies here (of the remains of the burned husband); a. e.—Pl. <a href=\"#\" data-headword=\"פִּיסְּתָא\">פִּיסָּתָא</a>, constr. <a href=\"#\" data-headword=\"פִּיסָּא\">פִּיסַּת</a>, <span dir=\"rtl\">פִּסַּת</span>. <span class=\"citation\">Targ. I Sam. V, 4</span>. <span class=\"citation\">Targ. Esth. VIII, 10</span>.</div><div class=\"sense\"><b>—2)</b> <i>piece</i>, esp. <i>bread</i> (v. <a href=\"#\" data-headword=\"פִּיתָּא\">פִּיתָּא</a>). <span class=\"citation\">Y. Ber. VI, 10ᵇ</span> bot. <span dir=\"rtl\">בגין דאנא אכל פִּיסְּתִי … דהדין פסא וכ׳</span> when I eat my bread and, not knowing how to say grace, I say, blessed be he who has created this piece &amp;c. (Bab. <span class=\"citation\">ib. 40ᵇ</span> <span dir=\"rtl\">מריה דהאי פיתא</span>). <span class=\"citation\">Y. Sabb. VII, end, 10ᵈ</span> <span dir=\"rtl\">קופדה משלים לפ׳ פ׳ וכ׳</span> meat may serve as a complement to bread (to complete the legal size), but bread cannot serve as a complement to meat. Tanḥ. Ekeb 7, v. <a href=\"#\" data-headword=\"לִפְתּוּתָא\">לִפְתּוּתָא</a>.—Pl. <a href=\"#\" data-headword=\"פִּיסְּתָא\">פִּיסָּתָא</a> <i>crumbs</i>. <span class=\"citation\">Y. Pes. VI, 33ᶜ</span> <span dir=\"rtl\">צריך מבערה פ׳</span> must remove the crumbs.</div>","alt":["פִּיסְּתָה","פִּסְּ׳"]},"22533":{"h":"פִּיסְתְּקָא","r":"Q00773","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פִּיסְטְקִין\">פִּיסְטְקִין</a>) <i>pistachio-nut</i>. <span class=\"citation\">Gitt. 59ᵃ</span> <span dir=\"rtl\">כפ׳ ופלגיה דפ׳</span> (not <span dir=\"rtl\">ופלגי</span>) compressed to the size respectively of a pistachio-nut and half a pistachio-nut (Rashi: <i>acorn</i>). Pl. <a href=\"#\" data-headword=\"פִּסְתְּקָא\">פִּיסְתְּקִין</a>, <span dir=\"rtl\">פִּיסְתְּקַיָּה</span>, <a href=\"#\" data-headword=\"פִּיסְטִין\">פִּסְ׳</a>. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> bot. Ar., v. <a href=\"#\" data-headword=\"פִּיסְטְקִין\">פִּיסְטְקִין</a>. Ib. 27ᵇ <span dir=\"rtl\">הוה משקי פ׳ בשביל למתקן</span> (not <span dir=\"rtl\">פרסתקי׳ … למתקה</span>) put pistachio-nuts in boiled wine to sweeten them.</div>","alt":["פִסְ׳"]},"22534":{"h":"פִּיעוּר","r":"Q00774","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּעַר\">פָּער</a>) <i>uncovering one’s self</i>, obscene worship of the idol Peor. <span class=\"citation\">Snh. 106ᵃ</span>; <span class=\"citation\">Yalk. Num. 771</span> <span dir=\"rtl\">פעור</span>. V. <a href=\"#\" data-headword=\"פְּעִירָה\">פְּעִירָה</a>.</div>","alt":["פִּעוּר"]},"22535":{"h":"פִּיעפּוּעָא","r":"Q00775","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּעְפּוּעָא I\">פַּעְפּוּעָא</a></div>","alt":[]},"22536":{"h":"פִּיף","r":"Q00776","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (apocop. reduplic. of <a href=\"#\" data-headword=\"פֶּה\">פֶּה</a>; cmp. <a href=\"#\" data-headword=\"פִּיפִיּוֹת\">פִּיפִיּוֹת</a>) <i>fringe</i>, knotted to the border. <span class=\"citation\">Kil. IX, 9</span> <span dir=\"rtl\">פ׳ של צמר וכ׳</span> (Mish. ed. <a href=\"#\" data-headword=\"פִּיו\">פיו</a>, corr. acc.; v. Rabb. D. S. a. l. note 10) it is forbidden to attach woolen and linen fringes (to a garment), because they may be mixed up with the web; Y. ib. 32ᵈ.—Trnsf. <i>knots surrounding the anus</i>. <span class=\"citation\">Tosef. Mikv. VII</span> (<span class=\"citation\">VIII), 10</span> <span dir=\"rtl\">בפ׳ או ביציאה</span> ed. Zuck. (oth. ed. <span dir=\"rtl\">בסוף או בצואה</span>, read <span dir=\"rtl\">בפיף</span>).</div>","alt":[]},"22537":{"h":"פִּיפָה","r":"Q00777","html":"<div class=\"sense\"> <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> top, v. <a href=\"#\" data-headword=\"נֵבֶל\">נֵבֶל</a> ch.</div>","alt":[]},"22538":{"h":"פיפוס","r":"Q00778","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּפּוּס\">פַּפּוֹס</a></div>","alt":[]},"22539":{"h":"פֵּיפוּר","r":"Q00779","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"פִּרְפּוּר\">פרפור</a>; <a href=\"#\" data-headword=\"פָּרַר\">פָּרַר</a>; cmp. <a href=\"#\" data-headword=\"אַפִּיפְיָירוֹת\">אַפִּיפְיָירוֹת</a>) <i>trellis</i>. <span class=\"citation\">Y. Kil. VI, 30ᶜ</span> <span dir=\"rtl\">אם … לפסע בין פ׳ לפ׳ וכ׳</span> if he is in the habit of stepping from one trellis to the other (in one step), they are considered (for purposes of mixed seeds, <a href=\"#\" data-headword=\"כִּלְאַיִם\">כִּלְאַיִם</a>) as one espalier; [Levy quotes <a href=\"#\" data-headword=\"פִּיפְיוֹר\">פִּיפְיוֹר</a>.]—Pl. f. <a href=\"#\" data-headword=\"אַפִּיפְיָירוֹת\">פִּיפָרוֹת</a>. <span class=\"citation\">Ib.</span> (Levy quotes <a href=\"#\" data-headword=\"אַפִּיפְיָירוֹת\">פִּיפְיָרוֹת</a>].</div>","alt":[]},"22540":{"h":"פֵּיפוּרָא","r":"Q00780","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"פֵּיפוּר\">preced.</a>) <i>decorative frame.</i>—Pl. <span dir=\"rtl\">פֵּיפוּרַיָּיא</span>. <span class=\"citation\">Targ. Y. Deut. XXVI, 3</span> (not <span dir=\"rtl\">רְיָיא …</span>).</div>","alt":[]},"22541":{"h":"פיפורין","r":"Q00781","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 74</span>, end <span dir=\"rtl\">והעביר פ׳ מעליו</span>, read: <a href=\"#\" data-headword=\"פּוּרְפּוּרְיוֹן\">פּוּרְפּוּרִין</a>; (<span class=\"citation\">Yalk. Sam. 147</span> <span dir=\"rtl\">פּוּרְפִּירָא</span>; some ed. <a href=\"#\" data-headword=\"פּוּרְפּוּרְיָא\">פורפריא</a>).</div>","alt":[]},"22542":{"h":"פיפיאורות","r":"Q00782","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. VI, 6</span> ed. Zuck., read: <a href=\"#\" data-headword=\"פִּיפְיָארוֹת\">פִּיפְיָארוּת</a>, v. <a href=\"#\" data-headword=\"אַפִּיפְיָירוֹת\">אַפִּיפְיָירוֹת</a></div>","alt":[]},"22543":{"h":"פִּיפְיָארוֹת","r":"Q00783","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיפְיָיארוֹת\">פִּיפְיָיארוֹת</a></div>","alt":[]},"22544":{"h":"פִּיפְיוֹר","r":"Q00784","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֵּיפוּר\">פֵּיפוּר</a></div>","alt":[]},"22545":{"h":"פִּיפְיוֹרָא","r":"Q00785","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּיפְיוֹר\">preced.</a> wds.; cmp. <a href=\"#\" data-headword=\"פּוּרְיָא\">פּוּרְיָא</a>) <i>royal litter</i>. <span class=\"citation\">Ab. Zar. 11ᵃ</span> [read:] <span dir=\"rtl\">ניפרא נקיט נורא קמי פ׳ אפיפיורא לדוכסא דוכסא וכ׳</span> the torchbearer carries the light in front of the litter, the chief <i>lecticarius</i> (behind the litter, carries the light) for the <i>dux</i>, the <i>dux</i> for the <i>hegemon, the hegemon</i> for the <i>comes</i>; does the <i>comes</i> carry the light before the people (that follow the procession)?—[V. Sachs Beitr. II, p. 111 on the custom of carrying fire.]</div>","alt":[]},"22546":{"h":"פִּיפִיּוֹת","r":"Q00786","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּה\">פֶּה</a></div>","alt":[]},"22547":{"h":"פִּיפְיָיארוֹת","r":"Q00787","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפִּיפְיָירוֹת\">אַפִּיפְיָירוֹת</a></div>","alt":["פִּיפְיָיארוּת","פִּיפְיָיר׳"]},"22548":{"h":"פיפילון","r":"Q00788","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פָּפִילְיוֹן\">פָּפִילְיוֹן</a></div>","alt":[]},"22549":{"h":"פִּיפָנִי","r":"Q00789","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Ἐπιφάνεια) <i>Epiphania</i>, a city of Syria. <span class=\"citation\">Gen. R. s. 37</span> (expl. <span dir=\"rtl\">החמתי</span>, <span class=\"citation\">Gen. X, 18</span>; Targ. Y. I, II a. l. <span dir=\"rtl\">אנטכואי</span>, <a href=\"#\" data-headword=\"אַנְטוּכְיָא\">אנטוכיא</a>).</div>","alt":[]},"22550":{"h":"פיפקין","r":"Q00790","html":"<div class=\"sense\">, <span class=\"citation\">Ruth R. s. 3</span> <span dir=\"rtl\">נטל פ׳</span>, v. <a href=\"#\" data-headword=\"פָּפִילְיוֹן\">פָּפִילוֹן</a></div>","alt":[]},"22551":{"h":"פִּיץ","r":"Q00791","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*פְּצַץ\">פְּצַץ</a></div>","alt":[]},"22552":{"h":"פִּיצּוּלַיָּא","r":"Q00792","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּצַל\">פְּצַל</a>) <i>shrivelled fruit</i>, esp. <i>grapes which fell in an unripe state and were put in the sun to ripen</i> (cmp. <a href=\"#\" data-headword=\"פַּצְעִילִין\">פַּצְעִילִין</a>). <span class=\"citation\">Y. Bets. IV, 62ᵇ</span> bot. <span dir=\"rtl\">באילין פ׳ הוה עובדא</span> the question turned on the sun-dried grapes; <span class=\"citation\">Y. Maasr. I, end, 49ᵇ</span> <span dir=\"rtl\">באילין פצולי אילין הוה וכ׳</span> (corr. acc.).</div>","alt":["פִּצּ׳"]},"22553":{"h":"פִּיצְטְלִין","r":"Q00793","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּסְטְלִין\">פַּסְטְלִין</a></div>","alt":[]},"22554":{"h":"פִּיצְעָא","r":"Q00794","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פֶּצַע\">פֶּצַע</a>, <i>wound.</i>—Pl. <a href=\"#\" data-headword=\"פִּיגְעָא\">פִּיצְעִין</a>, <a href=\"#\" data-headword=\"פִּיצְעָא\">פִּצְ׳</a>. <span class=\"citation\">Koh. R. to I, 8</span> <span dir=\"rtl\">עד דאיתמלאון פִּיצְעֵי פ׳</span> until their heads were full of wounds.</div>","alt":["פִּצְ׳"]},"22555":{"h":"פִּיצְּתָא","r":"Q00795","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*פְּצַץ\">פְּצַץ</a> or <a href=\"#\" data-headword=\"פּוּץ\">פוץ</a> <i>to split, break</i>; cmp. <a href=\"#\" data-headword=\"פִּיסָא\">פִּיסָא</a>) <i>arbitration, lot, share</i>. <span class=\"citation\">Targ. Y. Deut. XXXII, 8</span>, sq. (not <a href=\"#\" data-headword=\"צִיפְתָּא\">ציפתא</a>). <span class=\"citation\">Ib. IV, 34</span>. <span class=\"citation\">Targ. Prov. XVIII, 18</span> (ed. Wil. <a href=\"#\" data-headword=\"פִּצְתָּא\">פִּצְתָּא</a>). <span class=\"citation\">Targ. Ps. CXXV, 3</span>; a. fr.</div>","alt":["פִּצְּתָּא"]},"22556":{"h":"פִּיקָא","r":"Q00796","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">פקק</span>; cmp. <a href=\"#\" data-headword=\"פְּקַעַת\">פְּקַעַת</a>) <i>lump, ball, swelling</i>, esp. </div><div class=\"sense\"><b>1)</b> <i>protruding cartilage</i>. <span class=\"citation\">Ḥull. X, 4</span> (<span class=\"citation\">134ᵇ</span>) <span dir=\"rtl\">פ׳ של גרגרת</span> thyroid cartilage; <span class=\"citation\">Neg. X, 9</span>. <span class=\"citation\">Ib. 10</span> <span dir=\"rtl\">פ׳ של צואר</span> the protruding cartilage of the neck; <span class=\"citation\">Tosef. ib. IV, 12</span> <span dir=\"rtl\">פ׳ של פירקא</span>. <span class=\"citation\">Bekh. VII, 6</span> (<span class=\"citation\">45ᵃ</span>) <span dir=\"rtl\">פ׳ יוצאה מגודלו</span> (not <span dir=\"rtl\">יצא</span>) one that has a lump on his thumb; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>a protuberance on the blossom end of fruits</i>, v. <a href=\"#\" data-headword=\"פִּיטְמָא II\"><span dir=\"rtl\">פִּיטְמָא</span> II</a>. <span class=\"citation\">Y. Succ. III, 53ᵈ</span> <a href=\"#\" data-headword=\"פִּיקָא\">פיקא</a>.</div><div class=\"sense\"><b>—3)</b> <i>spinner’s coil.</i> Ohol. VII, 4 <span dir=\"rtl\">עד שיעגילו ראש כפ׳</span> until the embryos (on leaving the vagina) form a round head like a coil; expl. <span class=\"citation\">Bekh. 22ᵃ</span> <span dir=\"rtl\">כפ׳ של צמר</span> like a coil of wool. Ib.; <span class=\"citation\">Tosef. Ohol. VIII, 8</span> <span dir=\"rtl\">פ׳ של שתי</span> the coil containing the warp; <span dir=\"rtl\">פ׳ של ערב</span> containing the woof. Bekh. l. c. <span dir=\"rtl\">נראית פ׳ מתוך פ׳</span> it has the appearance of a coil coming forth out of a coil, v. <a href=\"#\" data-headword=\"*טְפִיפִית\">טְפִיפִית</a>.</div><div class=\"sense\"><b>—4)</b>  (<span dir=\"rtl\">של כוש</span>) <a href=\"#\" data-headword=\"פ׳\">פ׳</a> <i>whorl.</i> <span class=\"citation\">Kel. XI, 6</span>. <span class=\"citation\">Par. XII, 8</span>; a. e.</div><div class=\"sense\"><b>—5)</b> <i>coil</i> or <i>tuft</i> used as <i>a stopper</i> (v. <a href=\"#\" data-headword=\"פָּקַק\">פָּקַק</a>). <span class=\"citation\">Kel. XVII, 12</span>.—Pl. <a href=\"#\" data-headword=\"פִּיקִים\">פִּיקִין</a>; <span dir=\"rtl\">פִּיקוֹת</span>. <span class=\"citation\">Bekh. 45ᵃ</span> <span dir=\"rtl\">בעל הפיקין</span> (not <span dir=\"rtl\">הקיפין</span>) one afflicted with lumps; (Ar. Var. <span dir=\"rtl\">הפיקס</span>; Ar. s. v. <a href=\"#\" data-headword=\"כֶּסֶת\">כסת</a>: <span dir=\"rtl\">הפִּיקָן</span>; Mish. ib. VII, 6 <span dir=\"rtl\">בעל פיקה</span>; Talm. ed. 45ᵃ <span dir=\"rtl\">הפיקום</span>, Rashi: <span dir=\"rtl\">הפיקין</span>). Ib. 22ᵃ שלש פ׳ שמעתי וכ׳ I learned of three sizes of coils, one of the warp, one of the woof, and one large coil, that of the sack-weavers; <span class=\"citation\">Tosef. Kel. B. Mets. VII, 1</span>, v. <a href=\"#\" data-headword=\"סַקָּי I\"><span dir=\"rtl\">סַקָּי</span> I</a>. <span class=\"citation\">Lev. R. s. 14</span> <span dir=\"rtl\">פ׳ פ׳</span> coils upon coils (in the abdomen). <span class=\"citation\">Tosef. Ohol. XIII, 5</span>, v. <a href=\"#\" data-headword=\"לָבַשׁ\">לָבַשׁ</a>; a. e.</div>","alt":["פִּיקָה I"]},"22557":{"h":"פִּיקָא ²","r":"Q00797","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פּוּק\">פוק</a>) = b. h. <a href=\"#\" data-headword=\"פּוּקָה\">פּוּקָה</a>, <i>gliding, sinking</i>. <span class=\"citation\">Sabb. 147ᵇ</span> <span dir=\"rtl\">משום פ׳</span> on account of sinking in the clay-soil (<a href=\"#\" data-headword=\"*פִּילוֹמָא\">פִּילוֹמָא</a>, which makes walking a labor; Rashi: he might stain his garments when sinking in the muddy soil, and then wring them out).—<span class=\"citation\">Tosef. ib. VII</span> (<span class=\"citation\">VIII), 21</span> <span dir=\"rtl\">מבעיתין לעוית ולפ׳ וכ׳</span> (Var. <span dir=\"rtl\">ולפוקה</span>) you may shock a person in convulsions, or in an attack of vertigo, and it is not forbidden as a superstitious practice, v. <a href=\"#\" data-headword=\"אֱמוֹרִי\">אֱמוֹרִי</a>.—<span class=\"citation\">Yalk. Esth. 1054</span> <span dir=\"rtl\">מכניסין פ׳ בממונו וכ׳</span> they (the Jews) cause a sinking (decline) in the wealth of the world (<span class=\"citation\">Esth. R. to III, 8</span> <a href=\"#\" data-headword=\"פַּחַת\">פַּחַת</a>).—<span class=\"citation\">Snh. 111ᵇ</span> (ref. to <span dir=\"rtl\">פקו</span>, <span class=\"citation\">Is. XXVIII, 7</span>) <span dir=\"rtl\">אין פוקה אלא גהינם</span> (Ms. K. <span dir=\"rtl\">פקו</span>) ‘sinking’ means going to Gehenna.</div>","alt":["פִּיקָה II"]},"22558":{"h":"פִּיקָא ³","r":"Q00798","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bar-Piḳa</i>. <span class=\"citation\">Y. Naz. IX, 57ᵈ</span></div>","alt":["פִּיקָה III","בר פ׳"]},"22559":{"h":"פִּיקָּדוֹן","r":"Q00799","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פִּיקּוּד\">פִּקּ׳</a>.</div>","alt":["פִּיקְּדוֹנָא"]},"22560":{"h":"פִּיקָה","r":"Q00800","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיקָא\">פִּיקָא</a></div>","alt":[]},"22561":{"h":"פִּיקּוּד","r":"Q00801","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>charge, trust</i>. <span class=\"citation\">Num. R. s. 1</span>, end <span dir=\"rtl\">לא נמצא נאמן בפִיקּוּדוֹ</span> (not <span dir=\"rtl\">נאה</span>) was not found true to his charge.</div><div class=\"sense\"><b>—2)</b> <i>count, muster.</i>—Pl. <span dir=\"rtl\">פִּיקּוּדִים</span>, <a href=\"#\" data-headword=\"פִּיקּוּד\">פִּקּ׳</a>. <span class=\"citation\">Sot. 36ᵇ</span>; <span class=\"citation\">Yoma VII, 1</span>, a. e. <span dir=\"rtl\">חומש הפ׳</span> the Book of Numbers, v. <a href=\"#\" data-headword=\"חוֹמֶשׁ\">חוֹמֶשׁ</a>.</div>","alt":["פִּקּ׳"]},"22562":{"h":"פִּיקּוּדָא","r":"Q00802","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>command</i>. <span class=\"citation\">Targ. Ps. XIX, 9</span>. <span class=\"citation\">Targ. Y. Deut. XXVII, 26</span>; a. e.—<i>Pl.</i> (<i>masc</i>.) <span dir=\"rtl\">פִּיקּוּדַיָּיא</span>, <a href=\"#\" data-headword=\"פִּקָּדוֹן\">פִּיקּ׳</a>. Targ. Ps. l. c. <span class=\"citation\">Targ. Deut. XXVIII, 1</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>muster, count</i>.—<i>Pl.</i> as ab. <span class=\"citation\">Y. Shek. I, 46ᵇ</span> (ref. to <span class=\"citation\">Ex. XXX, 14</span>) <span dir=\"rtl\">כל דעבר על פ׳ יתן</span> all those who passed the mustering (<span class=\"citation\">Num. I</span>) shall give (half a Shekel, exempting the tribe of Levi, acc. to <span class=\"citation\">Num. I, 47</span>).</div>","alt":["פִּקּ׳"]},"22563":{"h":"פִּיקּוּחַ","r":"Q00803","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּקַח\">פָּקַח</a>) <i>removing debris</i>; <span dir=\"rtl\">פ׳ נפש</span> <i>removing a person from under debris</i>, in gen. <i>saving an endangered life</i>. <span class=\"citation\">Keth. 5ᵃ</span> <span dir=\"rtl\">מפקחין פ׳ נפש בשבת</span> you must remove debris to save a life on the Sabbath. Ib. 15ᵇ <span dir=\"rtl\">אין הולכין בפ׳ נ׳ אחר הרוב</span> as to saving life (on the Sabbath), we do not judge by the majority of the residents of a place (whether the person in the ruins is or is not presumably a Jew); <span class=\"citation\">Yoma 84ᵇ</span>. <span class=\"citation\">Ib. 85ᵃ</span> <span dir=\"rtl\">מנין לפ׳ נ׳ שדוחה וכ׳</span> whence is it proven that the duty of saving life supersedes the Sabbath laws? <span class=\"citation\">Keth. 19ᵃ</span> <span dir=\"rtl\">אין לך דבר שעומד בפני פ׳ נ׳ וכ׳</span> there is nothing (no religious law) that stands before (must not yield to) the duty of saving life, except three things: idolatry, incest and bloodshed (which you dare not commit even to save your life); <span class=\"citation\">Yoma 82ᵃ</span>; a. fr.</div>","alt":["פִּקּ׳"]},"22564":{"h":"*פִּיקוּם","r":"Q00804","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"פִּיקָא\"><span dir=\"rtl\">פִּיקָה</span> I</a>) <i>formation of lumps</i> on the body; v. <a href=\"#\" data-headword=\"פִּיקָא\"><span dir=\"rtl\">פִּיקָה</span> I</a>.</div>","alt":[]},"22565":{"h":"פִּיקּוּסָא","r":"Q00805","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"*פִּקּוּסִים\">פִּיקּוּסִין</a>, <span dir=\"rtl\">פִּיקּוּסַיָּא</span> (v. <a href=\"#\" data-headword=\"פָּקַס II\"><span dir=\"rtl\">פָּקַס</span> II</a>) <i>removing the coils on the blossom end of gourds</i>. <span class=\"citation\">B. Mets. 88ᵇ</span> <span dir=\"rtl\">עד דגמר לפִיקּוּסַיְּהוּ</span> (v. Rabb. D. S. a. l. note 80) until he has finished the entire work of removing &amp;c.; <span dir=\"rtl\">מדמתחלן פיקוסייהו</span> Ms. M. (ed. <span dir=\"rtl\">מכי אתחולי</span>) when the removing work has been started.</div>","alt":[]},"22566":{"h":"פיקורין","r":"Q00806","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פוֹקָרִין\">פּוֹקָרִין</a></div>","alt":[]},"22567":{"h":"פִּיקֵּחַ","r":"Q00807","html":"<div class=\"sense\">, v. <span dir=\"rtl\">פִּקֵּהַ</span></div>","alt":["פִּיקַּחַת"]},"22568":{"h":"פִּיקְטִים","r":"Q00808","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּקְטִים\">פִּקְטִים</a></div>","alt":["פִּיקְטִין"]},"22569":{"h":"*פִּיקְטְנִי","r":"Q00809","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (a corrupt. of fictile) <i>earthen</i> (<i>wine</i>) <i>vessel</i>. <span class=\"citation\">Tosef. B. Bath. V, 4</span> <span dir=\"rtl\">המוכר בפ׳</span> he who sells wine by the vessel, opp. <span dir=\"rtl\">בקטלזון</span>.</div>","alt":[]},"22570":{"h":"פיקי","r":"Q00810","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*פִּיקְיָילִין\">next w.</a></div>","alt":[]},"22571":{"h":"*פִּיקְיָילִין","r":"Q00811","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (facialis, φακιόλιον S.) <i>turban</i>. <span class=\"citation\">Y. Bets. V, 63ᵃ</span> <span dir=\"rtl\">אפרח רוחא פִּיקְיָילֵיה וכ׳</span> (not <span dir=\"rtl\">פיקי ליה</span>) the wind made his turban fly off R. Meir’s neck.</div>","alt":[]},"22572":{"h":"פִּיקִים","r":"Q00812","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיקָא\"><span dir=\"rtl\">פִּיקָה</span> I</a>, a. <a href=\"#\" data-headword=\"פִּיקָס\"><a href=\"#\" data-headword=\"פִּיקָס\">פִּיקָס</a>.</a></div>","alt":["פִּיקִין"]},"22573":{"h":"פיקלין","r":"Q00813","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ps. 820</span>, v. <a href=\"#\" data-headword=\"פִּילְקִין\">פִּילְקִין</a></div>","alt":[]},"22574":{"h":"פִּיקָן","r":"Q00814","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"פִּיקָא\"><span dir=\"rtl\">פִּיקָה</span> I</a>) <i>afflicted with lumps</i>, v. <a href=\"#\" data-headword=\"פִּיקָא\"><span dir=\"rtl\">פִּיקָה</span> I</a>.</div>","alt":[]},"22575":{"h":"פִּיקָס","r":"Q00815","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פִּיקָא\"><span dir=\"rtl\">פִּיקָה</span> I</a>; φῦκος, fucus, of Semitic origin) [<i>coil</i>,] </div><div class=\"sense\"><b>1)</b> <i>sea-weed</i> or <i>rock-lichen</i> used as a dye; <i>red color, rouge</i>. Sifra M’tsorʿa, Neg., Par. 1 (ref. to <a href=\"#\" data-headword=\"שני\">שני</a>, <span class=\"citation\">Lev. XIV, 4</span>) <span dir=\"rtl\">יכול פ׳ ת&quot;ל תולעת</span> from <a href=\"#\" data-headword=\"שני\">שני</a> you might infer that you may use the dye from <i>fucus</i>, therefore <i>tolaʿath</i> is added (to indicate that it must be won from a worm, the snail); <span class=\"citation\">Yalk. Lev. 559</span> <a href=\"#\" data-headword=\"פִּיקִים\">פִּיקִים</a>.</div><div class=\"sense\"><b>—2)</b> <i>the dried up blossoms of gourds</i>. <span class=\"citation\">B. Mets. 88ᵇ</span> (expl. <span dir=\"rtl\">משיפקסו</span>, <span class=\"citation\">Maasr. I, 5</span>) <span dir=\"rtl\">משינטל פ׳ שלהן</span> (Rashi to <span class=\"citation\">Bets. 13ᵇ</span> <a href=\"#\" data-headword=\"פָּקַס I\">פֶּקֶס</a>) as soon as their blossoms are removed.</div><div class=\"sense\"><b>—3)</b> <i>lump</i>. <span class=\"citation\">Bekh. 45ᵃ</span> Var. Ar., v. <a href=\"#\" data-headword=\"פִּיקָא\"><span dir=\"rtl\">פִּיקָה</span> I</a>.</div>","alt":["פֶּיקָס"]},"22576":{"h":"פִּיקְסִינָה","r":"Q00816","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πύξινον = πύξος) <i>box-tree, box-wood</i>. <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span> (expl. <span dir=\"rtl\">תאשור</span>, <span class=\"citation\">Is. XLI, 19</span>) <a href=\"#\" data-headword=\"פִּיקְסִינָה\">פיקסינה</a>; <span class=\"citation\">Gen. R. s. 15</span> <a href=\"#\" data-headword=\"פִּקְסִינָה\">פקסינון</a>; Tanḥ. T’rum. 9 <a href=\"#\" data-headword=\"פקטנין\">פקטנין</a>; ed. Bub. <a href=\"#\" data-headword=\"נקשונין\">נקשנון</a>, Var. <a href=\"#\" data-headword=\"נקשונין\">נקשונין</a>, <a href=\"#\" data-headword=\"נקסטן\">נקסטן</a> (corr. acc.). <span class=\"citation\">Y. Yoma III, 41ᵃ</span> top (expl. <a href=\"#\" data-headword=\"אֶשְׁכְּרוֹעַ\">אשכרוע</a>) <a href=\"#\" data-headword=\"פסקינון\">פסקינין</a> (corr. acc.).</div>","alt":["פִּיקְסִינוֹן","פִּקְ׳"]},"22577":{"h":"פִּיקְעָא","r":"Q00817","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּקַע\">פְּקַע</a>) <i>split</i>, esp. <i>slits in the rectum</i>. <span class=\"citation\">Ab. Zar. 28ᵃ</span> sq. <span dir=\"rtl\">חש בפ׳</span> suffered from slits. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ליתי … ולינח פ׳ להדי פ׳</span> let him get the kernel of a bramble fruit and place its split (wedge-shaped) side against the slit. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ עילאה</span> slits in the upper part of the rectum, <span dir=\"rtl\">פ׳ תיתאה</span> in the lower part.</div>","alt":[]},"22578":{"h":"פִּיקְעִין","r":"Q00818","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> = h. <span dir=\"rtl\">פַּקּוּעוֹת</span>, <i>Coloquintidas, Bitter-Apples</i> (v. Löw, Pfl., p. 332, sq.). <span class=\"citation\">Targ. II Kings IV, 39</span>.</div>","alt":["פִּקְ׳"]},"22579":{"h":"פִּיקְפּוּק","r":"Q00819","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פִּיקְסִינָה\">פִּקְ׳</a>.</div>","alt":["פִּיקְפֵּק"]},"22580":{"h":"פִּיקְקוֹ","r":"Q00820","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּקֶק\">פֶּקֶק</a></div>","alt":[]},"22581":{"h":"*פַּיְקַר","r":"Q00821","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. paigâr, Koh. in Ar. Compl. s. v.) <i>dissension, dispute</i>. <span class=\"citation\">Taan. 24ᵇ</span> לא ליהוי פ׳ וכ׳ Ar. (ed. <span dir=\"rtl\">לך עסק דברים …</span>) have no quarrel with those Jews.</div>","alt":[]},"22582":{"h":"פיקרין","r":"Q00822","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פוֹקָרִין\">פּוֹקָרִין</a></div>","alt":[]},"22583":{"h":"פִּיקַרְסוּת","r":"Q00823","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַפְקַרְסִין\">אַפְקַרְסִין</a>) <i>underwear</i>. <span class=\"citation\">Nidd. 48ᵇ</span> בפִיקַרְסוּתָן Ar. (ed. <span dir=\"rtl\">באפקריסותן</span>).</div>","alt":[]},"22584":{"h":"פִּיקַרְסִין","r":"Q00824","html":"<div class=\"sense\"> m. pl. <a href=\"#\" data-headword=\"פִּיקַרְסוּת\">same</a>. <span class=\"citation\">Kel. XXIX, 1</span> R. S. (ed. <a href=\"#\" data-headword=\"אַפְקַרְסִין\">אפקרסין</a>).</div>","alt":[]},"22585":{"h":"פִּיר","r":"Q00825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַר\">פָּרַר</a>) <i>rubble, loose ground; quarry</i> (cmp. German <i>Bruch</i>). <span class=\"citation\">Ned. 81ᵇ</span>; <span class=\"citation\">Keth. 71ᵇ</span> <span dir=\"rtl\">לא מצינו שועל שמת בעפר פ׳</span> it does not occur that a fox dies in the dust of rubble, i.e. you do not feel the absence of comforts to which you are not used; Y. ib. VII, 31ᵇ <span dir=\"rtl\">אין שועל עפר פרין מת</span> (read: <span dir=\"rtl\">מת בעפר פֵּרִין</span>; pl. of <a href=\"#\" data-headword=\"פָּר\">פֵּר</a>). Bab. <span class=\"citation\">ib. 79ᵇ</span> <span dir=\"rtl\">פ׳ של גפרית</span> a sulphur quarry.</div>","alt":[]},"22586":{"h":"פֵּירָא I","r":"Q00826","html":"<div class=\"sense\">, <i>ditch, pit, cavity</i>. <span class=\"citation\">Taan. 24ᵃ</span>, v. <a href=\"#\" data-headword=\"כַּוְורָא\">כַּוְורָא</a>. <span class=\"citation\">Kidd. 72ᵃ</span>, v. <a href=\"#\" data-headword=\"קְפֵי\">קְפֵי</a>. <span class=\"citation\">Erub. 26ᵃ</span> <span dir=\"rtl\">פ׳ דבי תורי</span> pit (dumping ground) where offal of dates is deposited on which cattle feeds; <span class=\"citation\">ib. 60ᵃ</span>. <span class=\"citation\">B. Bath. 11ᵃ</span>, v. <a href=\"#\" data-headword=\"סוּפְלֵי\">סוּפְלֵי</a>. <span class=\"citation\">Keth. 79ᵃ</span>, v. next w.—Pl. <a href=\"#\" data-headword=\"פֶּירִי\">פֵּירִי</a>. <span class=\"citation\">Gitt. 60ᵇ</span> <span dir=\"rtl\">קא יבשי פֵּירָין</span> our ditches will dry out.</div>","alt":[]},"22587":{"h":"פֵּירָא II","r":"Q00827","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פְּרִי\">פֶּרִי</a>, <i>fruit, crop</i>. <span class=\"citation\">B. Bath. 36ᵇ</span> <span dir=\"rtl\">פ׳ רבא</span> the large crop (of grain); <span dir=\"rtl\">פ׳ זוטא</span> the small crop (of vegetables &amp;c.). <span class=\"citation\">Succ. 31ᵇ</span> <span dir=\"rtl\">לא גמר פ׳</span> the fruit (Ethrog) is not ripe. <span class=\"citation\">Ber. 39ᵃ</span> <span dir=\"rtl\">פ׳ עדיף</span> fruit (vegetable) has the preference (over meat, for the purposes of benediction); a. fr.—Trnsf. <i>fruition, usufruct</i>. <span class=\"citation\">Keth. 79ᵃ</span> <span dir=\"rtl\">זרדתא … אמרי לה פ׳</span> some say the right of felling service-trees or fishing in a pond comes under the category of usufruct, opp. <a href=\"#\" data-headword=\"קְרַן II\">קרנא</a> property (which the heir may sell). <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">פ׳ תקינו … פ׳ דפ׳ וכ׳</span> the Rabbis allowed the husband the usufruct (the births of the animals belonging to his wife), but not the fruition of the usufruct (e.g. the fine which the thief has to pay for stealing the calf). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עיילא ליה גלימא פ׳ הוי וכ׳</span> if she brought in a cloak, he has the use of it, he may cover himself with it, until it is worn out; a. fr.—Pl. <a href=\"#\" data-headword=\"פֶּירִי\">פֵּירֵי</a>, <span dir=\"rtl\">פֵּירִין</span>, <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּר׳</a>. <span class=\"citation\">Targ. Gen. I, 11</span>, sq. <span class=\"citation\">Targ. Prov. VIII, 19</span> <a href=\"#\" data-headword=\"פִּרְיָה\">פִּרְיַי</a>; a. fr.—<span class=\"citation\">Shebu. 48ᵃ</span> <span dir=\"rtl\">פ׳ עבידי דמרקבי</span> fruits are liable to rot; a. fr.</div>","alt":["פֵּרָא"]},"22588":{"h":"פירבורין","r":"Q00828","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּרִיכוֹרִין\">פְּרִיכוֹרִין</a></div>","alt":[]},"22589":{"h":"פִּירְדָּה","r":"Q00829","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּרֶד II\"><span dir=\"rtl\">פֶּרֶד</span> II</a></div>","alt":[]},"22590":{"h":"פירה","r":"Q00830","html":"<div class=\"sense\">, Y. Maas. Sh. I, end, 53ᵃ <span dir=\"rtl\">בי פ׳</span>, or <span dir=\"rtl\">כי פ׳</span>, a corruption; perh. to be read: <span dir=\"rtl\">ר׳ יוסי בר חנינה אמר פּוֹדֶה</span>.</div>","alt":[]},"22591":{"h":"פֵּירוּג I","r":"Q00831","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּרַג I\">פְּרַג</a>) <i>exchange, price</i>. <span class=\"citation\">Targ. Y. Deut. XXIII, 19</span> (h. text <a href=\"#\" data-headword=\"מְחִיר\">מחיר</a>). <span class=\"citation\">Targ. Job XV, 31</span> (h. text <a href=\"#\" data-headword=\"תְּמוּרָה\">תמורה</a>); a. e.—Pl. <a href=\"#\" data-headword=\"פֵּירוּלִין\">פֵּירוּגִין</a>, <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּר׳</a>. <span class=\"citation\">Ib. XVII, 2</span> (ed. Wil. <span dir=\"rtl\">פרונ׳</span>, corr. acc.; h. text <span dir=\"rtl\">המרות׳</span>). <span class=\"citation\">Targ. Ps. XLIV, 13</span> (ed. Wil. <span dir=\"rtl\">פרונ׳</span>, corr. acc.).</div>","alt":["פֵּרוּג"]},"22592":{"h":"פֵּירוּג II","r":"Q00832","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פֵּירוּג I\">preced.</a>) <i>Perug</i>. <span class=\"citation\">Targ. I Chr. IV, 11</span> (h. text <a href=\"#\" data-headword=\"מְחִיר\">מחיר</a>).</div>","alt":[]},"22593":{"h":"פֵּירוּדָא","r":"Q00833","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּרִידָא I\"><span dir=\"rtl\">פְּרִידָא</span> I</a></div>","alt":[]},"22594":{"h":"פֵּירוּז","r":"Q00834","html":"<div class=\"sense\"><b>1)</b>  <span dir=\"rtl\">פ׳ אנדרפטא</span> name of a <i>bird</i>, v. <a href=\"#\" data-headword=\"*אִנְדְּרַפְטָא\">אִנְדְרַפְטָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>Peruz</i>, name of a (wicked) man. <span class=\"citation\">Ḥull. 62ᵇ</span></div>","alt":[]},"22595":{"h":"פִּירוֹזָג","r":"Q00835","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. fayrûzah, Arab, fayruzaǵ, Fl. to Levy Targ. Dict. II, 574ᵇ) <i>turquois</i>. <span class=\"citation\">Targ. Cant. V, 14</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"פְּרוֹזָג\">פְּרוֹזָג</a>).</div>","alt":[]},"22596":{"h":"פֵּירוּי","r":"Q00836","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פרי\">פָּרָה</a>) <i>fruitfulness, plenty</i>. Esth. R. end.</div>","alt":[]},"22597":{"h":"פֵּירוּכָא","r":"Q00837","html":"<div class=\"sense\"> c. (פְּרַךְ I) <i>broken corn, grist</i>(h. . <span class=\"citation\">Targ. O. Lev. II, 16</span> (ed. Berl. <span dir=\"rtl\">גירס׳</span>); a. e.—Pl. <a href=\"#\" data-headword=\"פֵּירוּלִין\">פֵּירוּכִין</a>, <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּירוּכַיָּיא</a>, <span dir=\"rtl\">פֵּ־רוּכָן</span>. Targ. O. a. Y. ib. 14. Targ. Y. ib. 16 <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּירוּכְיָיהּ</a> (ed. Amst. <span dir=\"rtl\">פֵּירוּכַיָּיהּ</span>; ed. Vien. <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פִּירוּכַיָּיא</a>).</div>","alt":["פֵּר׳ I"]},"22598":{"h":"פֵּירוּכָא ²","r":"Q00838","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (פְּרַךְ II, v. <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">next w.</a>) [<i>dried ears</i>,] <i>sheaf.</i>—Pl. <a href=\"#\" data-headword=\"פֵּירוּלִין\">פֵּירוּכִין</a>. <span class=\"citation\">Targ. Y. Gen. XXXVII, 7</span>, v. <a href=\"#\" data-headword=\"כְּרִיכָא II\"><span dir=\"rtl\">כְּרִיכָא</span> II</a>.</div>","alt":["פֵּר׳ II"]},"22599":{"h":"פֵּירוּכְיָיא","r":"Q00839","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"פֵּירוּכָא ²\"><span dir=\"rtl\">פֵּירוּכָא</span> I</a>. <span class=\"citation\">Targ. Y. Lev. II, 16</span>, v. <a href=\"#\" data-headword=\"פֵּירוּכָא ²\"><span dir=\"rtl\">פֵּירוּכָא</span> I</a>.</div><div class=\"sense\"><b>—2)</b>  (= h. <span dir=\"rtl\">מלילות</span>) <i>dry ears.</i>—Pl. <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּירוּכְיָין</a>, <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּר׳</a>. <span class=\"citation\">Targ. Y. Deut. XXIII, 26</span>.—Denom. <a href=\"#\" data-headword=\"פְּרַךְ II\"><span dir=\"rtl\">פְּרַךְ</span> II</a>.</div>","alt":["פֵּר׳"]},"22600":{"h":"פֵּירוּלִין","r":"Q00840","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"בֵּירוּלִין\">בֵּירוּלִין</a>, <span class=\"citation\">Targ. Y. Ex. XXVIII, 9</span> Mus. (ed. <span dir=\"rtl\">בולא</span>, <a href=\"#\" data-headword=\"כּוֹל\">כולא</a>, read: <a href=\"#\" data-headword=\"בּוּרְלָא\">בּוּרְלָא</a>).</div>","alt":[]},"22601":{"h":"פֵּירוּעַ","r":"Q00841","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֵּרוּעַ\">פֵּרוּעַ</a></div>","alt":[]},"22602":{"h":"פִּירוּצִין","r":"Q00842","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּירוּלִין\">בֵּירוּלִין</a> a. <a href=\"#\" data-headword=\"*בִּירוּצִין\"><a href=\"#\" data-headword=\"*בִּירוּצִין\">בִּירוּצִין</a>.</a></div>","alt":[]},"22603":{"h":"פֵּירוּק","r":"Q00843","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַק\">פָּרַק</a>) <i>taking apart</i> (of the Tabernacle), <i>breaking up</i>. <span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">פֵּירוּקָן בשעת וכ׳</span> the taking apart on moving the articles of the Tabernacle took place in the same order as they were put up. <span class=\"citation\">Num. R. s. 12</span>, v. <a href=\"#\" data-headword=\"עֲמִידָא\">עֲמִידָה</a>; a. e.—Pl. <a href=\"#\" data-headword=\"פֵּירוּלִין\">פֵּירוּקִין</a>, <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּר׳</a>. Ib. <span class=\"citation\">Y. Yoma I, 38ᵇ</span>, sq.; a. e.</div>","alt":["פֵּר׳"]},"22604":{"h":"פֵּירוּקָא","r":"Q00844","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּרַק\">פְּרַק</a>) <i>solution</i> of a problem, <i>reply, argument</i>, opp. <a href=\"#\" data-headword=\"קוּשְׁיָא\">קושיא</a>. <span class=\"citation\">B. Kam. 117ᵃ</span> <span dir=\"rtl\">האי קושיא … האי פ׳ והאי פ׳</span> such and such a problem and such and such a solution. <span class=\"citation\">Ab. Zar. 30ᵃ</span> <span dir=\"rtl\">פ׳ לסכנתא</span> (Rashi <span dir=\"rtl\">פֵּירוּקֵי</span> <i>pl.</i>) you offer argument where danger to life is concerned? a. e.—<i>Pl.</i> <span dir=\"rtl\">פֵּירוּקֵי</span>, <a href=\"#\" data-headword=\"פֵּירוּכָא\">פּר׳</a>. <span class=\"citation\">B. Mets. 84ᵃ</span> <span dir=\"rtl\">ומפריקנא ליה … פ׳</span> and I gave him twenty-four answers. <span class=\"citation\">Hor. 13ᵇ</span> <span dir=\"rtl\">כתבי פ׳ ושדי</span> they wrote down answers and cast them (into the schoolhouse); a. e.</div>","alt":["פֵּר׳"]},"22605":{"h":"פֵּירוּר","r":"Q00845","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַר\">פָּרַר</a>) </div><div class=\"sense\"><b>1)</b> <i>crumbling</i>. <span class=\"citation\">Pes. 28ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">בעי פ׳</span> must be crumbled (before being thrown into the river).</div><div class=\"sense\"><b>—2)</b> <i>crumb</i>.—Pl. <span dir=\"rtl\">פֵּירוּרִים</span>, <a href=\"#\" data-headword=\"פֵּירוּלִין\">פֵּירוּרִין</a>, <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּר׳</a>. <span class=\"citation\">Sabb. XXI, 3</span> (<span class=\"citation\">143ᵃ</span>). <span class=\"citation\">Men. 75ᵇ</span> (ref. to <span class=\"citation\">Lev. II, 6</span>) <span dir=\"rtl\">יכול יעשינה פ׳ וכ׳</span> you might think, he must break it up into crumbs &amp;c., v. <a href=\"#\" data-headword=\"פְּתִיתָה\">פְּתִיתָה</a>; a. fr.—<span class=\"citation\">Ab. d’R. N. ch. XXXIII</span> <span dir=\"rtl\">לא … עד שיֵעָשֶׂה לפנינו פ׳ פ׳</span> (ed. Schechter <span dir=\"rtl\">שנעשה</span>) we shall not cross the sea until it is broken into solid pieces before us; Tanḥ. <span class=\"citation\">B’shall. 10</span> <span dir=\"rtl\">ונעשו המים פר׳</span>; <span class=\"citation\">Yalk. Ex. 233</span> <span dir=\"rtl\">ונעשה פ׳ פ׳</span> (with ref. to <span dir=\"rtl\">פוררת</span>, <span class=\"citation\">Ps. LXXIV, 13</span>).—3) = <a href=\"#\" data-headword=\"פַּרְפֶּרֶת\">פַּרְפֶּרֶת</a>, <i>nibblings, desert, delicacies</i>. <span class=\"citation\">Y. Ber. VI, end, 10ᵈ</span>, v. <a href=\"#\" data-headword=\"פִּיתָּא\">פִּיתָּא</a>.</div>","alt":["פֵּר׳"]},"22606":{"h":"פֵּירוּרָא","r":"Q00846","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"פֵּירוּר\">preced.</a>) <i>mush</i> (made of crumbs), <i>paste</i>. <span class=\"citation\">Pes. 42ᵇ</span> <span dir=\"rtl\">פר׳ דאושכפי</span> (Rashi: <a href=\"#\" data-headword=\"פִּרְפֵּר\">פיר׳</a>) shoemaker’s paste.</div>","alt":["פֵּר׳"]},"22607":{"h":"פֵּירוּשׁ","r":"Q00847","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a>) <i>distinct expression, directness; explanation; commentary</i>. <span class=\"citation\">B. Bath. 52ᵃ</span> <span dir=\"rtl\">וכולן … יעשה כפֵירוּשָׁן ואם לאו יעשה פ׳ לפירושן</span> and as to all of them (a woman, a slave, or a minor), if they declared before dying, ‘these things belong to—’, he (the trustee) may do according to their explicit declaration, or else (having reasons to distrust their statements) he must make a commentary to their statement (explain the motive they may have had for telling a falsehood). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אי … עשה כפֵירוּשָׁה וכ׳</span> if you believe her to be trustworthy, do according to her explicit statement, if not, make a commentary &amp;c. (find out the real state of affairs). <span class=\"citation\">Y. Gitt. V, end, 47ᶜ</span>; <span class=\"citation\">Y. Shebi. V, end, 36ᵃ</span> <span dir=\"rtl\">וסתמו לאו כפֵירוּשׁוֹ הוא</span> is the silent lending of a untensil not equal to an explicit statement of the use to be made of it? <span class=\"citation\">Snh. 87ᵃ</span>, v. <a href=\"#\" data-headword=\"עִיקָּר\">עִיקָּר</a>; a. fr.—<span dir=\"rtl\">בפ׳</span> (also in Chald. dict.) <i>distinctly, explicitly, directly</i>. <span class=\"citation\">Ḥull. 95ᵃ</span>, a. fr. <span dir=\"rtl\">בפ׳ איתמר</span>, v. <a href=\"#\" data-headword=\"כְּלָלָא\">כְּלָלָא</a>. <span class=\"citation\">Snh. VII, 5</span> <span dir=\"rtl\">אמור מה ששמעת בפ׳</span> tell plainly now what thou hast heard (the blasphemer say, i.e. repeat without euphemistic disguise, v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>). <span class=\"citation\">Pes. 13ᵃ</span> <span dir=\"rtl\">בפ׳ אמרת לן</span> you told us plainly. <span class=\"citation\">Sabb. 39ᵇ</span> <span dir=\"rtl\">בפ׳ שמיע לך וכ׳</span> did you hear that tradition directly or only by implication?; a. fr.—[In commentaries and glosses: <a href=\"#\" data-headword=\"פֵּירוּשׁ\">פירוש</a>, abbrev. <span dir=\"rtl\">פי׳</span>, <i>this means</i>.]</div>","alt":["פֵּר׳"]},"22608":{"h":"פֵּירוּשׁ ²","r":"Q00848","html":"<div class=\"sense\">, ch. <a href=\"#\" data-headword=\"פֵּירוּשׁ\">same</a>. <span class=\"citation\">Targ. Y. Lev. XXVII, 2</span>. <span class=\"citation\">Targ. O. Num. XXX, 7</span> (Y. <a href=\"#\" data-headword=\"פֵּירוּשׁ\">פֵּירוּשֵׁי</a> pl.; h. text <span dir=\"rtl\">מִבְטָא</span>); ib. 9. <span class=\"citation\">Targ. Ps. XXXI, 3</span> (h. <span dir=\"rtl\">ארשת</span>). <span class=\"citation\">Targ. Cant. V, 11</span>. <span class=\"citation\">Targ. Esth. X, 2</span> (h. text <span dir=\"rtl\">פרשת</span>).—Y. Gitt. V, end, 47ᶜ <span dir=\"rtl\">הא בפ׳ לא</span> but if the purpose be explicitly stated, you must not lend it (v. <a href=\"#\" data-headword=\"פֵּירוּשׁ\">preced.</a>; <span class=\"citation\">Y. Shebi. V, end, 36ᵃ</span> <span dir=\"rtl\">במפרש</span>). Y. B. Bath. IV, beg. 14ᶜ <span dir=\"rtl\">כל הדין פ׳ הפרש וכ׳</span> (read <a href=\"#\" data-headword=\"אַפְרַשׁ\">אפרש</a>) did R. Ḥ. … enter into such details (in explaining the Mishnah) to you? <span class=\"citation\">Ab. Zar. 4ᵃ</span> <span dir=\"rtl\">ולא ידע … פ׳ דהאי פסוקא</span> and he did not know how to explain that verse to us; a. e.—Pl. <span dir=\"rtl\">פֵּירוּשִׁין</span>, constr. <a href=\"#\" data-headword=\"פֵּירוּשׁ\">פֵּירוּשי</a>, <a href=\"#\" data-headword=\"פֵּירוּכְיָיא\">פֵּר׳</a>, v. supra.</div>","alt":["פֵּירוּשָׁא","פֵּר׳"]},"22609":{"h":"פֵּירוֹת","r":"Q00849","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּרִי\">פֶּרִי</a></div>","alt":[]},"22610":{"h":"פירזומטא","r":"Q00850","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּרִיזוֹמָטָא\">פְּרִיזוֹמָטָא</a></div>","alt":[]},"22611":{"h":"פִּירְחָא","r":"Q00851","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּרַח II\">פִּרְחָא</a></div>","alt":[]},"22612":{"h":"פִּירְטָא","r":"Q00852","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּרַט\">פְּרַט</a>) <i>detailed statement, inventory</i>. <span class=\"citation\">Gitt. 57ᵇ</span> שדא פירטא בביתיה וכ׳ Ar. (ed. <span dir=\"rtl\">שדר שטר פרטתא</span>, Rashi <a href=\"#\" data-headword=\"פִּרְפֵּר\">פיר׳</a>) he sent a document containing the inventory and disposal of his property to his house, and became a proselyte; v. <a href=\"#\" data-headword=\"פִּיטְרָא II\"><span dir=\"rtl\">פִּיטְרָא</span> II</a>; <span class=\"citation\">Snh. 96ᵇ</span> <span dir=\"rtl\">שדר פּוּרְטִיתָא לביתיה</span>.</div>","alt":["פִּירְטְתָא","פִּרְ׳"]},"22613":{"h":"פִּירָטָא","r":"Q00853","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πειρατής, pirata) <i>pirate</i>.—Pl. <span dir=\"rtl\">פִּירָטִין</span>. <span class=\"citation\">Ex. R. s. 17</span>, end <span dir=\"rtl\">ספינות של פ׳</span> (not <span dir=\"rtl\">טון …</span>) pirate ships. <span class=\"citation\">Lev. R. s. 25</span> beg. [read:] <span dir=\"rtl\">מתיירא אני … ובים מפני הפ׳</span> I am afraid of robbers on the high-way, and on sea of the pirates; <span class=\"citation\">Yalk. ib. 615</span> <span dir=\"rtl\">וביום מפני אפרטין</span> (corr. acc.).</div>","alt":["פִּירָטֵיס"]},"22614":{"h":"פִּירְטְתָא I","r":"Q00854","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּירְטָא\">פִּירְטָא</a></div>","alt":[]},"22615":{"h":"פִּירְטְתָא II","r":"Q00855","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"פִּרְטְתָא II\"><span dir=\"rtl\">פִּרְטְתָא</span> II</a>.</div>","alt":[]},"22616":{"h":"פֶּירִי","r":"Q00856","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּרִי\">פֶּרִי</a>, <a href=\"#\" data-headword=\"פֵּירָא I\"><a href=\"#\" data-headword=\"פֵּירָא I\">פֵּירָא</a>.</a>—[<span class=\"citation\">B. Mets. VI, 1</span> (<span class=\"citation\">75ᵇ</span>) <span dir=\"rtl\">פירי אפירין</span>; Ms. R. 1, v. <a href=\"#\" data-headword=\"*פִּרְיָיפְרִין\">פִּרְיָיפְרִין</a>.]</div>","alt":["פֵּירֵי"]},"22617":{"h":"פִּירְיָיפְרִין","r":"Q00857","html":"<div class=\"sense\">, v. <span dir=\"rtl\">פִּרְיָי׳</span></div>","alt":[]},"22618":{"h":"פִּירְכָא","r":"Q00858","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (פְּרַךְ I) <i>refutation, objection</i>. <span class=\"citation\">Gitt. 83ᵃ</span> <span dir=\"rtl\">כולהו אית להו פ׳ … דלית ליה פ׳</span> to all of them objections may be raised, except the opinion of R. E. which is unobjectionable. <span class=\"citation\">Men. 66ᵃ</span> <span dir=\"rtl\">חזי ליה פ׳</span> saw an objection to it. <span class=\"citation\">B. Bath. 130ᵇ</span> <span dir=\"rtl\">כי אתא … וחזיתו ביה פ׳</span> if a legal decision of mine comes before you, and you see in it something objectionable; a. fr.—Pl. <a href=\"#\" data-headword=\"פִּירְקָא\">פִּירְכֵי</a>, <a href=\"#\" data-headword=\"פּוּרְיוֹמָא\">פִּרְ׳</a>. <span class=\"citation\">Ḥull. 76ᵇ</span> <span dir=\"rtl\">הדורי אפי׳</span>; (<span class=\"citation\">Nidd. 65ᵇ</span> <span dir=\"rtl\">אפירכא</span>), v. <a href=\"#\" data-headword=\"הֲדַר\">הֲדַר</a>.</div>","alt":["פִּרְ׳"]},"22619":{"h":"פִּירְכּוּס I","r":"Q00859","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (פִּרְכֵּס I) <i>painting, dyeing the hair</i>; trnsf. <i>giving a fraudulent appearance, deception</i>. <span class=\"citation\">B. Mets. 60ᵇ</span> <span dir=\"rtl\">פ׳ דאדם מאי היא</span> what is (in a legal sense) deception in selling a human being? (Answ. dyeing a slave’s hair). Y. ib. IV, end, 9ᵈ <span dir=\"rtl\">יש פירק׳ בכלים</span> (not <span dir=\"rtl\">כאוכלין</span>) giving a deceptive appearance to garments is forbidden <span class=\"citation\">Keth. 17ᵃ</span> <span dir=\"rtl\">לא פ׳</span> there is no paint (deception), v. <a href=\"#\" data-headword=\"כּוֹחָל\">כּוֹחָל</a>; <span class=\"citation\">Snh. 14ᵃ</span> <a href=\"#\" data-headword=\"פִּירְכֵּס\">פירכס</a> (corr. acc.).</div>","alt":["פִּירְקוּס","פִּרְ׳"]},"22620":{"h":"פִּירְכּוּס II","r":"Q00860","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (פִּרְכֵּס II) <i>jerking motion, struggling, spasmodic movement</i>, as a symptom of vitality. <span class=\"citation\">Ḥull. 38ᵃ</span> <span dir=\"rtl\">הרי זה פ׳</span> these are symptoms of vitality (proving that the slaughtered animal was not on the point of dying a natural death). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ שאמרו בתחלת שחיטה</span> the symptoms of vitality of which they speak refer to the beginning of the slaughtering act. <span class=\"citation\">Ab. Zar. 16ᵃ</span> <span dir=\"rtl\">חיה … בהמה דקה לפ׳</span> a large beast of chase is like a small domestic animal as regards the symptoms of vitality required at slaughtering; a. e.</div>","alt":["פִּרְ׳"]},"22621":{"h":"פִּירְכּוּסָא","r":"Q00861","html":"<div class=\"sense\">—Pl. <a href=\"#\" data-headword=\"פִּירְכּוּס I\">פִּירְכּוּסֵי</a>, <a href=\"#\" data-headword=\"פּוּרְיוֹמָא\">פִּרְ׳</a>. <span class=\"citation\">B. Bath. 142ᵇ</span> <span dir=\"rtl\">פרכס תלתא פ׳</span> it (the embryo in coming to light) made three spasmodic motions (and expired).</div>","alt":["פִּרְ׳"]},"22622":{"h":"פירכורין","r":"Q00862","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּרִיכוֹרִין\">פְּרִיכוֹרִין</a></div>","alt":[]},"22623":{"h":"פִּירְכֵּס","r":"Q00863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּרְכֵּס I\">פִּרְכֵּס</a>.—[<span class=\"citation\">Snh. 14ᵃ</span>, v. <a href=\"#\" data-headword=\"פִּירְכּוּס I\"><span dir=\"rtl\">פִּירְכּוּס</span> I</a>.]</div>","alt":[]},"22624":{"h":"פִּירְמָא","r":"Q00864","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּרַם\">פְּרַם</a>) <i>piece, slice; hash, mush</i>. <span class=\"citation\">Ḥull. 120ᵃ</span> (expl. <span dir=\"rtl\">קיפה</span>, Mish. <span class=\"citation\">ib. IX, 1</span>) <a href=\"#\" data-headword=\"פ׳\">פ׳</a> the particles of boiled meat which form a mush. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">פ׳ דסילקא</span> hashed beets.—Pl. <a href=\"#\" data-headword=\"פִּירְקָא\">פִּירְמֵי</a>. <span class=\"citation\">Ber. 39ᵃ</span> פ׳ רברבי Ar. (ed. <span dir=\"rtl\">פְּרִימָא רבא</span>; Ms. M. <span dir=\"rtl\">פְּרִימֵי רברבי</span>), v. <a href=\"#\" data-headword=\"פְּרַם\">פְּרַם</a>.</div>","alt":[]},"22625":{"h":"*פֵּירָן","r":"Q00865","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פרי\">פָּרָה</a>) <i>breeding establishment, stables</i>. <span class=\"citation\">Bekh. 40ᵃ</span> <span dir=\"rtl\">מעשה בפ׳ של בית מנחם</span> it happened in the stables of the house of Menaḥem (Rashi: at <i>Peran of the house</i> &amp;c., name of a village); <span class=\"citation\">Tosef. ib. IV, 8</span> <span dir=\"rtl\">בפדה</span>.</div>","alt":[]},"22626":{"h":"פִּירְנוּס","r":"Q00866","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פּוּרְיוֹמָא\">פִּרְ׳</a>.</div>","alt":["פִּירְנוּק","פִּירְנֵס"]},"22627":{"h":"פירנס","r":"Q00867","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 68</span> some ed., v. <a href=\"#\" data-headword=\"פורנס\">פורנס</a></div>","alt":[]},"22628":{"h":"פִּירְסוּמֵי","r":"Q00868","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פַּרְסֵם\">פַּרְסֵם</a>) </div><div class=\"sense\"><b>1)</b> <i>uncovering</i>. <span class=\"citation\">Targ. Y. Lev. XVIII, 6</span>.</div><div class=\"sense\"><b>—2)</b> <i>divulging, betraying</i>. <span class=\"citation\">Targ. Y. Gen. XIX, 26</span> <span dir=\"rtl\">בפ׳ עניא</span> (ed. Amst. <span dir=\"rtl\">בפִירְסוֹמִי</span>, corr. acc.) by betraying the presence of a poor man in her house (v. <span class=\"citation\">Gen. R. s. 51</span>).—<span dir=\"rtl\">פרסומי ניסא</span>, v. <a href=\"#\" data-headword=\"פַּרְסֵם\">פַּרְסֵם</a>.</div>","alt":["פִּרְ׳"]},"22629":{"h":"פִּירְסִיקָא","r":"Q00869","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פּוּרְיוֹמָא\">פִּרְ׳</a>.</div>","alt":["פִּירְסֵם","פִּירְסְקָא"]},"22630":{"h":"פֵּירָעוֹן","r":"Q00870","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַע\">פָּרַע</a>) <i>paying a debt, payment</i>. <span class=\"citation\">Shebu. 41ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">פ׳ מעליא הוי</span> it was a real payment of a debt (and not a mere deposit). <span class=\"citation\">M. Kat. 9ᵇ</span>; <span class=\"citation\">Ab. Zar. 6ᵇ</span> <span dir=\"rtl\">עכ&quot;ום לענין פ׳ לעולם מיצר</span> the gentile will always grieve over the payment of a debt (whereas the Jew is glad to have rid himself of an obligation). <span class=\"citation\">B. Mets. 13ᵇ</span>, a. fr. <span dir=\"rtl\">חיישינן לפ׳</span> (in the case of a note of indebtedness being found) we apprehend that payment may have been made (and therefore it must not be returned to the creditor). <span class=\"citation\">Y. Keth. X, end, 34ᵃ</span> <span dir=\"rtl\">אל יהא לך פ׳ אלא מזה</span> you shall be paid only from this (only this portion of my property is pledged). <span class=\"citation\">Koh. R. to VII, 2</span> <span dir=\"rtl\">מדה שיש בה פ׳</span>; <span dir=\"rtl\">מדת פ׳</span> an act of benevolence with which a divine reward is connected. <span class=\"citation\">Yalk. Ex. 180</span> <span dir=\"rtl\">קבל פ׳ מהקב&quot;ה</span> he received payment (was punished) at the hands of God; a. fr.</div>","alt":["פֵּרָ׳"]},"22631":{"h":"פִּירְפֵּר","r":"Q00871","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּרְפֵּר\">פִּרְפֵּר</a></div>","alt":[]},"22632":{"h":"פִּירְצָא","r":"Q00872","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פֵּירוּכָא\">פְּרַ׳</a>) <i>break, gap, perforation</i>.—Pl. <span dir=\"rtl\">פִּירְצֵי</span>. <span class=\"citation\">Sabb. 108ᵃ</span> <span dir=\"rtl\">כיון דאית ביה פ׳ פ׳</span> because it (the skin of the plucked bird) is full of holes.—[<a href=\"#\" data-headword=\"פִּירוּצִין\">פִּירְצִין</a>, v. <a href=\"#\" data-headword=\"פְּרִיצָא I\">פְּרִיצָא</a>.]</div>","alt":["פִּרְ׳"]},"22633":{"h":"פִּירְצָה","r":"Q00873","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּרְצָה\">פִּרְצָה</a></div>","alt":[]},"22634":{"h":"פִּירְקָא","r":"Q00874","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פֵּירוּכָא\">פר׳</a>.</div>","alt":["פֵּירָקוֹן","פִּירְקוֹנָא","פִּירְקֵי"]},"22635":{"h":"פִּירְקוּס","r":"Q00875","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּירְכּוּס I\"><span dir=\"rtl\">פִּירְכּוּס</span> I</a></div>","alt":[]},"22636":{"h":"פִּירְקְתָא","r":"Q00876","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּרַק\">פְּרַק</a>) <i>joint</i>, esp. <span dir=\"rtl\">פִּירְקַת צַוְרָא</span>, <span dir=\"rtl\">פִּירְקַת קְדַל</span> <i>neck</i>. Targ. Y. a. O. <span class=\"citation\">Deut. XXXIII, 29</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"פְּרִיקֵי\">פְּרִיקֵי</a>, <span dir=\"rtl\">פְּרִיקַת</span>; h. text <span dir=\"rtl\">במותימו</span>). <span class=\"citation\">Targ. Ps. LX, 10</span> ed. Lag. <a href=\"#\" data-headword=\"פֶּתֶן ²\">פו׳</a> (ed. Wil. <a href=\"#\" data-headword=\"פּוּרְיוֹמָא\">פִּרְ׳</a>; Regia <span dir=\"rtl\">פְּרִיקַת</span>). <span class=\"citation\">Targ. Lam. V, 5</span> (Levita <span dir=\"rtl\">פרי׳</span>). <span class=\"citation\">Targ. Y. Gen. XLV, 14</span> (ed. Vien. <span dir=\"rtl\">פרי׳</span>).</div>","alt":["פּוּרְ׳"]},"22637":{"h":"פִּירְשָׁא","r":"Q00877","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פֶּרֶשׁ\">פֶּרֶשׁ</a>, <i>secretion</i>. <span class=\"citation\">Ḥull. 116ᵇ</span> <span dir=\"rtl\">חלב … פ׳ בעלמא הוא</span> the milk in the stomach of a suckling animal is considered a mere secretion (no longer real milk). <span class=\"citation\">Bekh. 7ᵇ</span> <span dir=\"rtl\">פ׳ בעלמא הוא</span> it is a mere secretion (a false membrane, no real skin); a. e.—Pl. <span dir=\"rtl\">פַּירְשַׁיָּיא</span>, <a href=\"#\" data-headword=\"פּוּרְיוֹמָא\">פִּרְ׳</a>. <span class=\"citation\">Zeb. 85ᵃ</span> <span dir=\"rtl\">ניקרבינהו בפִרְשַׁיְיהוּ</span> shall the entrails be offered with the excrements in them?</div>","alt":["פִּר׳"]},"22638":{"h":"פִּירְשָׁע","r":"Q00878","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>ebony</i> or <i>box-wood</i>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 19</span> (<span class=\"citation\">Kel. XII, 8</span> <a href=\"#\" data-headword=\"אֶשְׁכְּרוֹעַ\">אשכרוע</a>).</div>","alt":["פִּרְ׳"]},"22639":{"h":"פִּישּׁוּט","r":"Q00879","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּשַׁט\">פָּשַׁט</a>) <i>spreading, stretching forth</i>. Y. Ab. Zar. IV, end, 44ᵇ <span dir=\"rtl\">בתוך פ׳ ידים</span> within reach of the hands; <span dir=\"rtl\">חוץ לפ׳ ידים</span> beyond reach. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כשם שנתנו פ׳ ידים לטהרות וכ׳</span> as proximity within reach of the hands is made a criterion for levitical uncleanness (<span class=\"citation\">Toh. VII, 2</span>), so it is made for wine (suspected of having been touched by an idolater, v. <a href=\"#\" data-headword=\"נֶסֶךְ\">נֶסֶךְ</a>); a. e.—פ׳ ידים ודגלים <i>prostration accompanied by stretching of hands and feet</i>. <span class=\"citation\">Ber. 34ᵇ</span>; <span class=\"citation\">Meg. 22ᵇ</span>; <span class=\"citation\">Shebu. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"הִשְׁתַּחֲוָאָה\">הִשְׁתַּחֲוָאָה</a>; a. fr.—[Mekh. B’shall. beg. <span dir=\"rtl\">בפישוטן</span>, read: <span dir=\"rtl\">בפְשׁוּטָה</span>, v. <a href=\"#\" data-headword=\"פָּשׁוּט\">פָּשׁוּט</a>.]</div>","alt":["פִּשּׁ׳"]},"22640":{"h":"פִּישׁוֹן I","r":"Q00880","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Pishon</i>. <span class=\"citation\">Yeb. 107ᵇ</span> פ׳ הגמל Pishon the camel-driver, v. <a href=\"#\" data-headword=\"כָּפַשׁ\">כָּפַשׁ</a>.</div>","alt":[]},"22641":{"h":"פִּישׁוֹן II","r":"Q00881","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (b. h.) <i>Pishon</i>, name of a river., name of a river. <span class=\"citation\">Gen. R. s. 16</span> (ref. to <span class=\"citation\">Gen. II, 11</span>) <span dir=\"rtl\">פ̇יש̇ון שהוא מגדל פ̇ש̇תן ומימיו מהלכין בש̇ופ̇י</span> its name was Pishon, because it raises flax (on its shores), and its waters run gently; Yalk. ib. 21.</div>","alt":[]},"22642":{"h":"פַּיְשׂוֹנָא","r":"Q00882","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*פַּיְישׂוֹנָא\">פַּיְישׂוֹנָא</a></div>","alt":[]},"22643":{"h":"פישׁן","r":"Q00883","html":"<div class=\"sense\">, read: <span dir=\"rtl\">פ&quot;י ש&quot;ין</span> <i>Pe’ Shin</i>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> <span dir=\"rtl\">פ&quot;י ש&quot;ין שיני</span> if a vessel is found inscribed Pé Shin, the contents are second tithes <span dir=\"rtl\">(פירקון שני</span>), v. <span class=\"citation\">Tosef. ib. V, 1</span>.</div>","alt":[]},"22644":{"h":"פִּישְׁפּוּשׁ","r":"Q00884","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פִּישְׁרָא\">פִּשְׁ׳</a>.</div>","alt":["פִּישְׁפִּישׁ","פִּישְׁפָּשׁ","פִּישְׁפֵּשׁ"]},"22645":{"h":"פִּישְׁפָּשָׁה","r":"Q00885","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Pishpashah</i>. <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> bot.</div>","alt":[]},"22646":{"h":"פִּישְׁקָא","r":"Q00886","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוּשְׁקָא\">פּוּשְׁקָא</a></div>","alt":[]},"22647":{"h":"פִּישְׁרָא","r":"Q00887","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּשַׁר I\">פְּשַׁר</a>) </div><div class=\"sense\"><b>1)</b> <i>solution, interpretation</i>. <span class=\"citation\">Targ. Jud. VII, 15</span>. Constr. <a href=\"#\" data-headword=\"פְּשַׁר I\">פְּשַׁר</a>. <span class=\"citation\">Targ. Koh. VIII, 1</span>.—V. <a href=\"#\" data-headword=\"פּוּשְׁרָנָא\">פּוּשְׁרָנָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>dissolved food, cud</i>. <span class=\"citation\">Targ. Lev. XI, 3</span>, sq. (h. text <span dir=\"rtl\">גרה</span>); a. e.</div><div class=\"sense\"><b>—3)</b> <i>thawing snow</i>.—Pl. <span dir=\"rtl\">פִּישְׁרֵי</span>, <a href=\"#\" data-headword=\"פִּישְׁרָא\">פִּשְׁ׳</a>. Targ. II Esth. III, 8, v. <a href=\"#\" data-headword=\"חַצְבָּא\">חַצְבָּא</a>.—<span class=\"citation\">Kidd. 73ᵇ</span>, v. <a href=\"#\" data-headword=\"פְּשׁוּרָא\">פְּשׁוּרָא</a>.</div>","alt":["פִּשְׁ׳"]},"22648":{"h":"פִּיתָּא","r":"Q00888","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פַּת\">פַּת</a>, <i>piece, bread</i>. <span class=\"citation\">Targ. O. Gen. XVIII, 5</span>. <span class=\"citation\">Targ. Y. I ib. XL, 16</span>; a. fr.—<span class=\"citation\">Ber. 40ᵇ</span> <span dir=\"rtl\">בריך רחמנא מריה דהאי פ׳</span> blessed be the Merciful One, the owner of this bread. <span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot., v. <a href=\"#\" data-headword=\"אָרְסְקִינָס\">אָרֶסְקִינָס</a>. <span class=\"citation\">Y. Ter. VIII, 45ᵈ</span> top <span dir=\"rtl\">פ׳ תחות וכ׳</span> (you must not put) a piece of bread under the arm-pit (a superstitious practice); <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> bot. <a href=\"#\" data-headword=\"פּוּתְתָא\">פותתא</a>. <span class=\"citation\">Y. Ber. VI, end, 10ᵈ</span> <span dir=\"rtl\">פ׳ ופירור</span> when there is before you bread and some delicacy; a. fr.—Pl. <span dir=\"rtl\">פִּיתִּין</span>, <a href=\"#\" data-headword=\"פָּתִין\">פִּתִּין</a>. <span class=\"citation\">Targ. I Sam. X, 3</span> (h. text <span dir=\"rtl\">ככרות</span>).</div>","alt":["פִּתָּא"]},"22649":{"h":"פִּיתְגָּם","r":"Q00889","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּתְגָּם\">פִּתְגָּם</a></div>","alt":["פִּיתְגָּמָא"]},"22650":{"h":"פִּיתּוּחַ","r":"Q00890","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> פָּתַח <i>Pi.</i>) <i>incision, engraving, engraved design</i>. <span class=\"citation\">Y. Nidd. III, 50ᵈ</span> <span dir=\"rtl\">פ׳ ידים ורגלים וכ׳</span> it (the embryo) has no incisions indicating the outlines of hands and of feet. <span class=\"citation\">Y. Ab. Zar. III, 43ᵇ</span> bot. <span dir=\"rtl\">הומר היא בפ׳</span> the law is stricter in the case of an engraving made on a tree (Asherah).—Pl. <span dir=\"rtl\">פִּיתּוּחִים</span>, <span dir=\"rtl\">פִּיתּוּחִין</span>, <a href=\"#\" data-headword=\"פִּיתּוּחַ\">פִּתּ׳</a>. Ib. <span dir=\"rtl\">העכיר את הפ׳</span> if he effaced the engraving. Ohol. XIV, 1 <span dir=\"rtl\">העטרות והפ׳</span> the wreaths and engravings (mouldings above the entrance); Tosef. ib. XIV, 10 <span dir=\"rtl\">הפִּתּוּיִין</span>.</div>","alt":["פִּתּ׳"]},"22651":{"h":"פִּיתּוּחָא","r":"Q00891","html":"<div class=\"sense\">, <i>engraving, moulding</i>. <span class=\"citation\">Targ. Zeph. II, 14</span> <span dir=\"rtl\">פִּיתּוּחַ תרעיא</span> (Levita <span dir=\"rtl\">פִּיחּוּחֵי</span> pl.; h. text <span dir=\"rtl\">כפתר׳</span>).</div>","alt":["פִּתּ׳"]},"22652":{"h":"פִּיתּוּי","r":"Q00892","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּתָה\">פָּתָה</a>) </div><div class=\"sense\"><b>1)</b> <i>persuasion, enticing</i>. Tanḥ. Sh’moth 19; <span class=\"citation\">Ex. R. s. 3</span> בפ׳ באתי אליך וכ׳ I came to thee with persuasiveness (making thee believe that thou didst hear thy father’s voice), that thou be not afraid, <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בתחלה פ׳ פיתיתי אותך וכ׳</span> at first I spoke persuasively to thee, now I will speak to thee words of truth (earnest admonition). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין פתי אלא לשון פ׳</span> <i>pethi</i> (<span class=\"citation\">Prov. XIV, 15</span>) has the meaning of ‘persuasion’ (one easily persuaded); a. fr.—Esp. <i>enticing a virgin, claims of the seduced</i> (<span class=\"citation\">Ex. XXII, 15</span>). <span class=\"citation\">Keth. 35ᵇ</span> <span dir=\"rtl\">אין לה לא קנס ולא פ׳</span> she has no claim either of fine (for outrage) or of indemnity for seduction. <span class=\"citation\">Ib. 36ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  dialect. for <a href=\"#\" data-headword=\"פִּיתּוּחַ\">פִּיתּוּחַ</a> (cmp. <a href=\"#\" data-headword=\"פּוֹתִי\">פּוֹתִי</a> a. <a href=\"#\" data-headword=\"פּוֹתֵחַ\">פּוֹתֵחַ</a>) <i>engraving, moulding</i>.—Pl. <span dir=\"rtl\">פִּיתּוּיִין</span>, <a href=\"#\" data-headword=\"פִּיתּוּחַ\">פִּתּ׳</a>. <span class=\"citation\">Tosef. Ohol. XIV, 10</span> (R. S. to Ohol. XIV, 1 <span dir=\"rtl\">פִּיתּוּחִין</span>), v. <a href=\"#\" data-headword=\"פִּיתּוּחַ\">פִּיתּוּחַ</a>.</div>","alt":["פִּתּ׳"]},"22653":{"h":"פִּיתּוּלָא","r":"Q00893","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּתַל\">פְּתַל</a>) [<i>twisting</i>,] </div><div class=\"sense\"><b>1)</b> <i>perverseness</i>. <span class=\"citation\">Targ. Prov. VIII, 8</span>.</div><div class=\"sense\"><b>—2)</b> <i>turn of events, vicissitudes</i>. <span class=\"citation\">Yalk. Gen. 127</span> (play on <span dir=\"rtl\">נפתולי</span>, <span class=\"citation\">Gen. XXX, 8</span>) <span dir=\"rtl\">פִּיתּוּלֵיה לא דידי הוה וכ׳</span> were not his vicissitudes mine? did not Jacob come to Laban for my sake (I being predestined to become his wife)?; <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">פִּיתּוּלַיֵּיה לא דידי הויין</span> (<i>pl.</i>).</div>","alt":["פִּתּ׳"]},"22654":{"h":"פִּיתוֹם I","r":"Q00894","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Pithom</i>, a storage city of Egypt. <span class=\"citation\">Sot. 11ᵃ</span> <span dir=\"rtl\">ולמה נקרא שמה פ׳ שראשון ראשון פ̇י̇ ת̇הו̇ם̇ בולעו</span> why was Raameses named Pithom? Because the mouth of the deep swallowed every foundation as it was laid; <span class=\"citation\">Ex. R. s. 1</span>. Mekh. B’shall. s. 1 (ref. to <span dir=\"rtl\">פי החירת</span>, <span class=\"citation\">Ex. XIV, 2</span>) <span dir=\"rtl\">לשעבר היתה נקראת פ׳</span> formerly its name was Pithom; a. e.</div>","alt":[]},"22655":{"h":"פִּיתוֹם II","r":"Q00895","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּתָה\">פָּתָה</a>, adapt. of πύθων) [<i>seducer</i>,] <i>necromancer, conjurer, ventriloquist</i>. <span class=\"citation\">Snh. VII, 7</span> בעל אוב זה פ׳ המדבר משחיו <i>baʿal ob</i> is the <i>pithom</i> that makes the dead speak from his armpit; Sifra E’dosh. Par. 3, ch. VII; ib. Par. 4, ch. XI; <span class=\"citation\">Tosef. Snh. X, 6</span> <span dir=\"rtl\">פ׳ המדבר בין פרקיו וכ׳</span> that talks between his joints and from between his armpits; a. e.</div>","alt":["פִּיתּוּם"]},"22656":{"h":"פִּיתוּנַיָּא","r":"Q00896","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּתֶן\">פֶּתֶן</a> ch.</div>","alt":[]},"22657":{"h":"פִּיתוֹס","r":"Q00897","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיטּוּס\">פִּיטּוּס</a></div>","alt":[]},"22658":{"h":"פִּיתּוּתָא","r":"Q00898","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*פְּתַת\">פְּתַת</a>) <i>bread to be broken</i>. <span class=\"citation\">Y. Dem. I, 22ᵃ</span> <span dir=\"rtl\">יתיב אכיל נפל פ׳ מיניה</span> sat down to a meal, and the bread fell out of his hand when he was about to break it.</div>","alt":[]},"22659":{"h":"פִּיתֵּחַ","r":"Q00899","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּתַח\">פָּתַח</a>) <i>open-eyed, seeing</i>. <span class=\"citation\">Arakh. 17ᵇ</span>; <span class=\"citation\">B. Bath. 128ᵃ</span>, v. <a href=\"#\" data-headword=\"סָמָא\">סָמָא</a>.</div>","alt":["פִּתֵּ׳"]},"22660":{"h":"פִּיתְח־","r":"Q00900","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּתַח\">פֶּתַח</a></div>","alt":[]},"22661":{"h":"פִּיתְחָא","r":"Q00901","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">פִּתְח׳</span>.</div>","alt":["פִּיתְחוֹן"]},"22662":{"h":"פיתם","r":"Q00902","html":"<div class=\"sense\">, Y. Sabb. XIV, 14ᵃ bot., v. <a href=\"#\" data-headword=\"פִּיטּוּס\">פִּיטּוּס</a></div>","alt":[]},"22663":{"h":"פִּיתְנָא","r":"Q00903","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּתֶן\">פֶּתֶן</a> ch.</div>","alt":[]},"22664":{"h":"פִּיתָּק","r":"Q00904","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּתַק\">פָּתַק</a>; v. <a href=\"#\" data-headword=\"פִּיטֵּק\">פִּיטֵּק</a>) <i>ball, stone, tablet, ballot; lot, decree</i>. Tanḥ. B’haʿăl. 12 <span dir=\"rtl\">כל מי שהיה עולה בידו פ׳ כתוב וכ׳</span> he who drew a ballot on which ‘elder’ was written. Tanḥ. B’midb. 21 <span dir=\"rtl\">אם עלה בידו פ׳ כתוב וכ׳</span> if he drew a ballot on which ‘Levi’ was written, he knew that a Levite had redeemed him. <span class=\"citation\">Num. R. s. 4</span> [read:] <span dir=\"rtl\">מי אומר לך שאם היה שם פי׳ של לוי שלא וכ׳</span> who tells thee that I should not have drawn it, had there been a ballot inscribed ‘Levi’ in the box? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ כתב וכ׳</span> (read <span dir=\"rtl\">כתוב</span>) a ballot inscribed &amp;c. <span class=\"citation\">Sot. 12ᵃ</span> <span dir=\"rtl\">לא היו בפִיתְקָהּ של חוה</span> they were not included in the decree pronounced on Eve (<span class=\"citation\">Gen. III, 16</span>). <span class=\"citation\">Snh. 102ᵃ</span> (ref. to <span class=\"citation\">I Kings XI, 29</span>) <span dir=\"rtl\">יצא מפיתקה של ירושלים</span> (Rashi <span dir=\"rtl\">מפִּתְקָהּ</span>) he went out of the destiny of Jerusalem (i.e. was to have no share in the welfare of Jerusalem); a. fr.—Pl. <span dir=\"rtl\">פְּתָקִים</span>, <span dir=\"rtl\">פְּתָקִין</span> (Chald. form) <a href=\"#\" data-headword=\"פִּילְקִין\">פִּיתְקִין</a>. <span class=\"citation\">Esth. R. to I, 2</span>; v. <a href=\"#\" data-headword=\"דדי\">דָּדָה</a>. <span class=\"citation\">Gen. R. s. 91</span> <span dir=\"rtl\">לערב הביאו לו את הפ׳</span> in the evening they brought him the tablets (on which every traveller had written his name). Num. R. l. c. <span dir=\"rtl\">כתב על … פ׳ לוי לוי</span> he (Moses) wrote on each of twenty-two thousand ballots, Levi &amp;c. (v. <a href=\"#\" data-headword=\"פִּיטֵּק\">פִּיטֵּק</a>). Tanḥ. l. c. <span class=\"citation\">Snh. 17ᵃ</span> <span dir=\"rtl\">טלו פִיתְקֵיכֶם</span> draw your ballots; a. fr.</div>","alt":["פֶּתֶק"]},"22665":{"h":"פִּיתַק","r":"Q00905","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XIX, 23</span> (Ms. <a href=\"#\" data-headword=\"פִּיטְקָא\">פיטקא</a>; h. text <span dir=\"rtl\">ספר</span>). Targ. II Esth. I, 8 <span dir=\"rtl\">כסא … שמיה פ׳</span> a large goblet … which was named <i>Pithḳa</i> (Decree, v. <a href=\"#\" data-headword=\"פּוּסְקָא\">פּוּסְקָא</a>).—<span class=\"citation\">Y. Sot. I, 17ᵇ</span> bot. <span dir=\"rtl\">כתוב חד פיתק דתרין וכ׳</span> write out one edict (order) for two men whom I may take with me; <span class=\"citation\">Num. R. s. 9</span>. <span class=\"citation\">Kidd. 73ᵇ</span> <span dir=\"rtl\">תלי פ׳</span> if the infant wears a tablet (with an inscription). <span class=\"citation\">Y. Bicc. III, 65ᵈ</span> אוף … הוי בפ׳ R. J. was likewise on the list (of those to be appointed). <span class=\"citation\">Hor. 13ᵇ</span> <span dir=\"rtl\">הוו כתבי קושייתא בפ׳ וכ׳</span> (some ed. <span dir=\"rtl\">בפסקא</span>) wrote out questions on a tablet and threw them into the school-house. <span class=\"citation\">Kidd. 70ᵃ</span>, v. <a href=\"#\" data-headword=\"הַזְמָנָא\">הַזְמָנָא</a>; a. fr.—[<span class=\"citation\">Ḥull. 31ᵃ</span> <span dir=\"rtl\">דכולה פתקא</span>, v. <a href=\"#\" data-headword=\"פִּקְתָא\">פִּקְתָא</a>.]—Pl. <a href=\"#\" data-headword=\"פִּילְקִין\">פִּיתְקִין</a>, <a href=\"#\" data-headword=\"פִּיתַק\">פִּתְ׳</a>. <span class=\"citation\">Gen. R. s. 91</span> <span dir=\"rtl\">והוה … ומקבל פ׳</span> and Manasseh stood there (at the gates) receiving the tablets (with the names of the arrivals, v. <a href=\"#\" data-headword=\"פִּיתָּק\">preced.</a>).</div>","alt":["פִּיתְקָא","פִּתְ׳"]},"22666":{"h":"*פִּיתְקוֹנָא","r":"Q00906","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּיתַק\">preced.</a>) <i>decree</i>. <span class=\"citation\">Targ. II Chr. XXXI, 5</span> ed. Beck (oth. ed. <a href=\"#\" data-headword=\"פִּתְגָּם\">פתגמא</a>).</div>","alt":[]},"22667":{"h":"פִּיתְרָא","r":"Q00907","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּתַר II\"><span dir=\"rtl\">פְּתַר</span> II</a></div>","alt":[]},"22668":{"h":"פִּיתְּתָא","r":"Q00908","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*פְּתַת\">פְּתַת</a>) <i>piece</i> (<i>of bread</i>). <span class=\"citation\">Targ. Prov. XXVIII, 21</span>.—<span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> bot., v. <a href=\"#\" data-headword=\"פִּיתָּא\">פִּיתָּא</a>.</div>","alt":["פִּתְּ׳"]},"22669":{"h":"פַּךְ","r":"Q00909","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>flask, jar</i> with a narrow neck, v. <a href=\"#\" data-headword=\"טָפִי\">טָפִי</a>. <span class=\"citation\">Y. Hor. III, 47ᶜ</span> bot. <span dir=\"rtl\">נמשחו מן הפך</span> were anointed out of a flask, opp. <a href=\"#\" data-headword=\"קְרַן I\">קרן</a>; <span class=\"citation\">Meg. 14ᵃ</span>. <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">I Sam. II, 1</span>) <span dir=\"rtl\">רמה קרני ולא רמה פַּכִּי</span> ‘my horn is high’, but not ‘my flask is high.’ <span class=\"citation\">Tosef. Succ. III, 10</span> <span dir=\"rtl\">כמין פי הפך</span> as if coming forth through the mouth of a flask, v. <a href=\"#\" data-headword=\"פִּכְפֵּךְ\">פִּכְפֵּךְ</a>. <span class=\"citation\">Neg. XII, 5</span> <span dir=\"rtl\">חסה התורה … ועל פַּכֹּו</span> the Torah has regard … even for a man’s flask; Sifra M’teorʿa, <span class=\"citation\">Neg., ch. III</span>, Par. 5. <span class=\"citation\">Gen. R. s. 69</span>, end <span dir=\"rtl\">שופע … כמלא פי הפך</span> the oil was poured down for him from heaven in large drops as if coming out of a flask; <span class=\"citation\">Yalk. ib. 120</span>; a. fr.—Pl. <span dir=\"rtl\">פַּכִּים</span>, <span dir=\"rtl\">פַּכִּין</span>. <span class=\"citation\">Sabb. 84ᵇ</span> <span dir=\"rtl\">פ׳ קטנים</span> small flasks (into which you cannot dip your finger); <span class=\"citation\">B. Kam. 25ᵇ</span>. <span class=\"citation\">Ḥull. 91ᵃ</span> (ref. to <span class=\"citation\">Gen. XXXII, 25</span>) <span dir=\"rtl\">נשתייר על פ׳ קטנים</span> he remained behind for the sake of some small jars. <span class=\"citation\">Kel. II, 2</span>; a. fr.</div>","alt":[]},"22670":{"h":"פָּכָה","r":"Q00910","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פכי\">פכי</a></div>","alt":[]},"22671":{"h":"פָּכוֹרָא","r":"Q00911","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּכַר\">פְּכַר</a>) <i>breaker, destroyer</i>. <span class=\"citation\">Gen. R. s. 67</span>, beg. <span dir=\"rtl\">פ׳ תרעיא היך תרעך פכור וכ׳</span> thou, breaker of gates, how is thy gate broken into and ruined!</div>","alt":[]},"22672":{"h":"*פָּכוֹרָה","r":"Q00912","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Pakhora</i>. <span class=\"citation\">Y. Sot. IX, 24ᵃ</span> bot. <span dir=\"rtl\">יהודה בן פ׳</span>; (Y. Maas. Sh. V, end, 56ᵈ <span dir=\"rtl\">פתורה</span>).</div>","alt":[]},"22673":{"h":"פָּכַח","r":"Q00913","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פָּכַךְ\">פָּכַךְ</a>) [<i>to break through</i>,] <i>to ooze out, evaporate</i>.</div><div class=\"sense\"><b>Pi. פִּכֵּחַ</b> <div class=\"sense\"><i>to cause evaporation, to counteract the effect of</i>. <span class=\"citation\">B. Bath. 10ᵃ</span> <span dir=\"rtl\">יין קשה שינה מְפַכַּחְתֹּו</span>, Ms. R. <span dir=\"rtl\">מפקחתו</span>, v. Rabb. D. S. a. l. note 6) wine is strong (overpowering man), sleep makes it evaporate.</div></div>","alt":[]},"22674":{"h":"פְּכַח","r":"Q00914","html":"<div class=\"sense\"> <span class=\"citation\">Meg. 12ᵇ</span> למחר פ׳ ליה חמריה Ms. M. (Ms. O. a. L. <a href=\"#\" data-headword=\"פֶּקַע I\">פקע</a>; ed. <span dir=\"rtl\">פסיק</span>; v. Rabb. D. S. a. l. note; Ar. <span dir=\"rtl\">מפכח</span>) by to-morrow his wine will have evaporated (his intoxication will be gone).</div><div class=\"sense\"><b>Pa. מְפַּכְּחָא</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּדִיחוּתָא\">בְּדִיחוּתָא</a>. <span class=\"citation\">Taan. 13ᵇ</span>; <span class=\"citation\">B. Mets. 66ᵇ</span> <span dir=\"rtl\">לפַכּוּחֵי</span>, v. <a href=\"#\" data-headword=\"פַּחַד ²\">פַּחְדָּא</a>.—Part. pass. <span dir=\"rtl\">מְפַכַּח</span>. <span class=\"citation\">Nidd. 20ᵇ</span> <span dir=\"rtl\">ומִפְכַּח הוא דקמפכח ואזיל</span> (Ar. <span dir=\"rtl\">פַּכּוּחֵי הוא דפכח ואזיל</span>) it (the blood-stain in drying up) becomes constantly fainter.</div></div>","alt":[]},"22675":{"h":"פַּכְחוּתָא","r":"Q00915","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּכַח\">preced.</a>) <i>that which evaporates, fluid</i>, opp. <span dir=\"rtl\">חרותא</span> sediment. <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">פ׳ דדיותא</span> the fluid portion of the ink.</div>","alt":[]},"22676":{"h":"פכי","r":"Q00916","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"פַּכְחוּתָא\">preced.</a> wds.) <i>to break through, penetrate</i>.—<i>Pi.</i> פִּכָּה <i>to ooze, drop</i>. <span class=\"citation\">Yalk. Ez. 383</span> <span dir=\"rtl\">מי הבאר … ומְפַכִּין ונובעין וכ׳</span> well-water shall in future days rise from under the threshold of the Temple, and shall ooze and bubble and go forth in three parts; <span class=\"citation\">Pirké d’R. El. ch. LI</span> <span dir=\"rtl\">ומפרין</span> (corr. acc.). <span class=\"citation\">Tosef. Succ. III, 3</span>, v. <a href=\"#\" data-headword=\"פִּכְפֵּךְ\">פִּכְפֵּךְ</a>.</div>","alt":["פָּכָה"]},"22677":{"h":"פכי ²","r":"Q00917","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. VIII, 34</span> <a href=\"#\" data-headword=\"פכי\">פַּכֵּי</a> some ed., read: <span dir=\"rtl\">סִפִּי</span>.—<span class=\"citation\">Ib. VII, 15</span> <span dir=\"rtl\">דמפכא</span>, <span dir=\"rtl\">דמפכיא</span>, read with ed. Lag. <span dir=\"rtl\">דמְסַכְּיָא</span>, v. <a href=\"#\" data-headword=\"סְכֵי\">סְכֵי</a>.</div>","alt":[]},"22678":{"h":"פָּכַךְ","r":"Q00918","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פָּכָה\">פָּכָה</a>) <i>to ooze, drop</i>.—Denom. <a href=\"#\" data-headword=\"פַּךְ\">פַּךְ</a>.</div>","alt":[]},"22679":{"h":"פכך","r":"Q00919","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. V, 22</span> <span dir=\"rtl\">נתפכיך</span> some ed., v. <a href=\"#\" data-headword=\"פְּכַר\">פְּכַר</a>.</div>","alt":[]},"22680":{"h":"פַּכְסְמִין","r":"Q00920","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (παξαμᾶς) <i>biscuits</i>. <span class=\"citation\">Num. R. s. 7</span>.</div>","alt":[]},"22681":{"h":"פַּכְסַס","r":"Q00921","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Pakhsas</i>. <span class=\"citation\">Y. Naz. VII, beg. 55ᵈ</span> <span dir=\"rtl\">יוסי בן פ׳</span>; Sifra Emor beg. <span dir=\"rtl\">יוסף בן פ׳</span>.</div>","alt":[]},"22682":{"h":"פִּכְפֵּךְ","r":"Q00922","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פָּכַךְ\">פָּכַךְ</a>) <i>to ooze, drip</i>. <span class=\"citation\">Tosef. Succ. III, 3</span> [read:] <span dir=\"rtl\">ר׳ אליעזר אומר והנה מים מפכים מלמד שמים מְפַכְפְּכִין ועולין כמין פי הפך וכ׳</span> R. El. … says, ‘And behold waters dripping’ (<span class=\"citation\">Ez. XLVII, 2</span>), this intimates that in the days to come water oozing out and rising, as if coming out of a flask, will come forth from under the threshold &amp;c., v. <a href=\"#\" data-headword=\"פָּכָה\">פָּכָה</a>. Ib. 11 <span dir=\"rtl\">כך היתה הבאר … מְפַכְפֶּכֶת ועולה וכ׳</span> (Var. <span dir=\"rtl\">מפרפר</span>) so the well that travelled with Israel in the desert, resembling a rock of the size of a k’barah <a href=\"#\" data-headword=\"כְּבָרָה\">(כְּבָרָה</a></div>","alt":[]},"22683":{"h":"פָּכַר","r":"Q00923","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">פִּיכֵּר</span> (v. <a href=\"#\" data-headword=\"פְּכַר\">next w.</a>) <i>to split, break</i>. <span class=\"citation\">Gen. R. s. 23</span> <span dir=\"rtl\">פָּכְרָה רוח … ופְכָרוֹ</span> (or <span dir=\"rtl\">פִּכְּרָה</span>, <span dir=\"rtl\">ופִכְּרוֹ</span>) the wind split (knocked down) one tree, and it fell on its neighbor and knocked it down; (Yalk. ib. 39 <span dir=\"rtl\">פֵּרְכָה … ופֵירְכוֹ</span>).—Part. pass. <span dir=\"rtl\">פָּכוּר</span>, v. <a href=\"#\" data-headword=\"פְּכַר\">next w.</a></div>","alt":[]},"22684":{"h":"פְּכַר","r":"Q00924","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פָּכָה\">פָּכָה</a>) </div><div class=\"sense\"><b>1)</b> <i>to insert, interlace, clasp</i>. <span class=\"citation\">Sabb. 10ᵃ</span> <span dir=\"rtl\">פ׳ ידיה ומצלי</span> he clasped his hands (in reverence) and prayed; Yalk. Am. 542.—Part. pass. <span dir=\"rtl\">פְּכִיר</span>; pl. <span dir=\"rtl\">פְּכִירִין</span>. <span class=\"citation\">Targ. Esth. VIII, 15</span>.</div><div class=\"sense\"><b>—2)</b> <i>to split, break open</i>. Part. pass. <span dir=\"rtl\">פְּכִיר</span>. <span class=\"citation\">Gen. R. s. 67</span> Ar. (ed. <span dir=\"rtl\">פָּכוּר</span> h. form), v. <a href=\"#\" data-headword=\"פָּכוֹרָא\">פָּכוֹרָא</a>.</div><div class=\"sense\"><b>Pa. פַּכֵּר</b> <div class=\"sense\"><b>1)</b> <i>to split, break in, demolish</i>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 6</span> (ed. Vien. <span dir=\"rtl\">פָּכְרוּ</span> <i>Pe.</i>). <span class=\"citation\">Targ. Y. Num. XXI, 35</span> (ed. Vien. <a href=\"#\" data-headword=\"פָּלְחָא\">פָּ׳</a>); a. e.—<span class=\"citation\">Targ. Koh. III, 3</span> <span dir=\"rtl\">לפַכָּרָא</span> ed. Lag. (Ar. a. Levita <span dir=\"rtl\">לפכורא</span>, read: <span dir=\"rtl\">לפַכּוּרֵי</span>; ed. <span dir=\"rtl\">לפרכא</span>, <span dir=\"rtl\">לכפרא</span>, corr. acc.; h. text <span dir=\"rtl\">לפרוץ</span>).—<span class=\"citation\">Gen. R. s. 86</span> end <span dir=\"rtl\">פַּכְּרוּן</span> (not <a href=\"#\" data-headword=\"פָּרוּכְתָּא\">פרכ׳</a>), v. <a href=\"#\" data-headword=\"נִיבָא I\"><span dir=\"rtl\">נִיבָא</span> I</a>. <span class=\"citation\">Lam. R. to V, 1</span> (transl. <span dir=\"rtl\">ערו</span>, <span class=\"citation\">Ps. CXXXVII, 7</span> פַּכְּרוּ Ar. (ed. <span dir=\"rtl\">פגרו</span>, v. <a href=\"#\" data-headword=\"פְּגַר I\"><span dir=\"rtl\">פְּגַר</span> I</a>).</div><div class=\"sense\"><b>—2)</b> <i>to entangle, confound</i>. <span class=\"citation\">Targ. Y. Lev. XXVI, 30</span> (ed. Vien. <span dir=\"rtl\">אַפְכַּר</span> <i>Af.</i>).</div></div><div class=\"sense\"><b>Ithpe. אִתְפְּכַר</b> <div class=\"sense\"><i>to be entangled, caught</i>. <span class=\"citation\">Targ. Prov. V, 22</span> <span dir=\"rtl\">נִתְפְּכֵיר</span> ed. Lag. (Ar. <span dir=\"rtl\">יִתְפְּכַר</span>; some ed. <span dir=\"rtl\">נתּפכיך</span>, corr. acc.; h. text <span dir=\"rtl\">יתמך</span>).</div></div>","alt":[]},"22685":{"h":"פָּלָא","r":"Q00925","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פלי\">פלי</a></div>","alt":["פְּלָא"]},"22686":{"h":"פֶּלֶא","r":"Q00926","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"פָּלָא\">preced.</a>) <i>strange thing, wonder, miracle</i>. Mekh. B’shall., Shir., s. 8 (ref. to <span class=\"citation\">Ex. XV, 11</span>) <span dir=\"rtl\">עשה עמנו פ׳ וכ׳</span> he has done wonders for us, and he will do &amp;c.; a. e.—Pl. <span dir=\"rtl\">פְּלָאִים</span>, <span dir=\"rtl\">פְּלָאִין</span>, <span dir=\"rtl\">פְּלָאוֹת</span>. <span class=\"citation\">Midr. Till. to Ps. CVI</span>, beg. (ref. to <span class=\"citation\">Ps. CXXXVI, 4</span>; <span class=\"citation\">13</span>; <span class=\"citation\">25</span>) <span dir=\"rtl\">מה הפרנסה … בלא ניסין ובלא פ׳</span> as the world cannot exist without sustenance (which the Lord provides), so it cannot exist without (daily) signs and wonders. Ib. <span dir=\"rtl\">ואינו יודע כמה פ׳ עשה וכ׳</span> ed. Bub. (ed. <span dir=\"rtl\">מה פלאי</span>, corr. acc.) and man knows not how many miraculous salvations the Lord works for him. <span class=\"citation\">Gen. R. s. 20</span> (ref. to <span class=\"citation\">Ps. CXXXVI, 24</span> sq.) <span dir=\"rtl\">מה גאולה פ׳ אף פרנסה פ׳</span> as the redemption was miraculous, so man’s sustenance is miraculous. <span class=\"citation\">Ex. R. s. 12</span>, end (expl. <span dir=\"rtl\">אפילת</span>, <span class=\"citation\">Ex. IX, 32</span>) <span dir=\"rtl\">פ׳ עשה הק&quot;בה בהם</span> the Lord showed wonders by them. <span class=\"citation\">Snh. 109ᵇ</span> (play on <span dir=\"rtl\">פלת</span>, <span class=\"citation\">Num. XVI, 1</span>) <span dir=\"rtl\">שנעשו לו פ׳</span> wonderful things (delivery from destruction with Korah) happened to him (On); <span class=\"citation\">Num. R. s. 18</span>; (Tanḥ. Kor. 10 <a href=\"#\" data-headword=\"נִפְלָא III\">נפלאות</a>). Midr. Till. To <span class=\"citation\">Ps. CXIX, 18</span> <span dir=\"rtl\">פ׳ היא התורה</span> the Law is full of strange (obscure) things. <span class=\"citation\">Ib. 129</span>; a. fr.—[<span class=\"citation\">Yalk. Gen. 47</span> <span dir=\"rtl\">ומקרע בפלאות</span>, read: <span dir=\"rtl\">בכִילָאוֹת</span>, v. <a href=\"#\" data-headword=\"כִּילָה\">כִּילָה</a>.]</div>","alt":[]},"22687":{"h":"פֶּלֶא ²","r":"Q00927","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">פִּלְאִין</span>, <span dir=\"rtl\">פְּלָאִין</span>. <span class=\"citation\">Targ. Y. Ex. VIII, 18</span>. <span class=\"citation\">Targ. Y. II ib. XV, 18</span>.</div>","alt":[]},"22688":{"h":"פְּלָאגֵי","r":"Q00928","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוּג\">פְּלוּג</a></div>","alt":[]},"22689":{"h":"פלאגרה","r":"Q00929","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוֹדַגְרָא\">פּוֹדַגְרָא</a></div>","alt":[]},"22690":{"h":"פלאטוני","r":"Q00930","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלָּטִינוֹס\">פַּלָּטִינוֹס</a></div>","alt":["פלאטיני","פלאטנוס"]},"22691":{"h":"פֶּלִאי","r":"Q00931","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Peli</i> (<i>unknown</i>). <span class=\"citation\">Num. R. s. 10</span> (ref. to <span class=\"citation\">Jud. XIII, 18</span>) <span dir=\"rtl\">שם שמו המלאך פ׳ וכ׳</span> there (on that occasion) his name was ‘the angel Peli’, corresponding to his mission, as he came to recommend a vow of abstinence (with ref. to <span dir=\"rtl\">יַפְלִא</span>, <span class=\"citation\">Num. VI, 2</span>).</div>","alt":[]},"22692":{"h":"פִּלְאֲתָא","r":"Q00932","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">פלא</span>) <i>dark saying, allegory</i>. <span class=\"citation\">Targ. Prov. I, 6</span> (h. text <a href=\"#\" data-headword=\"מְלִיצָה\">מליצה</a>).</div>","alt":[]},"22693":{"h":"*פִּלְבֵּל","r":"Q00933","html":"<div class=\"sense\"> (prob. to be read: <a href=\"#\" data-headword=\"פִּלְפֵּל\">פִּלְפֵּל</a>, v. <a href=\"#\" data-headword=\"פַּלְפֵּל II\"><span dir=\"rtl\">פַּלְפֵּל</span> II</a>) <i>to roll</i>. Tanḥ. ed. Bub. Ḥuck. 3 <span dir=\"rtl\">ראו עיניה מְפַלְבְּלוֹת</span> they saw the eyes of the cow roll (squint to look at the yoke, v. <a href=\"#\" data-headword=\"*פָּזַל\">פָּזַל</a>). Ib. <span dir=\"rtl\">כשהן באין … מפלבלות עיניה</span> (prob. to be read: <span dir=\"rtl\">היתה מְפַלְבֶּלֶת</span>) when they came to put a yoke on her, she rolled her eyes.</div>","alt":[]},"22694":{"h":"פָּלַג","r":"Q00934","html":"<div class=\"sense\"> (b. h.) <i>to separate, split</i>.</div><div class=\"sense\"><b>Hif. הִפְלִיג</b> <div class=\"sense\"><b>1)</b> <i>to part, go away</i>. Y. Ber. I, 2ᵈ bot. <span dir=\"rtl\">ומצאו שה׳ אף הוא ה׳</span> (not <span dir=\"rtl\">עוד</span>) and finding that he (the friend that had knocked at the door) had withdrawn, he withdrew likewise.—Esp. <i>to go to sea</i> (cmp. <a href=\"#\" data-headword=\"פִּילָגוֹס\">פִּילָגוֹס</a>). <span class=\"citation\">Erub. IV, 1</span> <span dir=\"rtl\">הִפְלִיגָה ספינתם בים</span> their ship went out on the open sea. <span class=\"citation\">Sabb. 19ᵃ</span> <span dir=\"rtl\">אין מַפְלִיגִין בספינה וכ׳</span> you must not start on a sea-voyage less than three days before the Sabbath; <span class=\"citation\">Num. R. s. 16</span>, beg. <span dir=\"rtl\">אין מפליגין בספינה בים הגדול</span> (contrad. to <a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a> along the sea coast).</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">ה׳ ממלאכה</span> (or sub. <span dir=\"rtl\">ממלאכה</span>) <i>to rest from work; to pause</i>. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">לכשיַפְלִיג</span>, v. <a href=\"#\" data-headword=\"לָקַשׁ\">לָקַשׁ</a>. <span class=\"citation\">Tosef. Ber. IV, 21</span> <span dir=\"rtl\">הִפְלִיגוּ צריכין וכ׳</span> (not <a href=\"#\" data-headword=\"צריך\">צריך</a>) when the laborers take a recess, they must say the benediction for what they have been eating while at work. Y. Yoma III, 40ᵇ bot. <span dir=\"rtl\">להפליג</span>, v. <a href=\"#\" data-headword=\"הֶפְלֵג\">הֶפְלֵג</a>.</div><div class=\"sense\"><b>—3)</b> <i>to divert, put off; to discard</i>. Bab. ib. 66ᵇ <span dir=\"rtl\">לא מפני שהִפְלִיגָן בדברים וכ׳</span> (he made an evasive reply) not because he desired to divert their minds with words (counterquestions), but because he never said anything that he had not heard from his teacher; <span class=\"citation\">Tosef. Yeb. III, 4</span>; <span class=\"citation\">Succ. 27ᵇ</span>. Y. Ab. Zar. II, 40ᶜ bot. <span dir=\"rtl\">אם שאלו … יַפְלִיגֶינּוּ כשם שה׳ וכ׳</span> if he asks him whither he is going, let him put him off (state a distant destination), as did Jacob to Esau; <span class=\"citation\">Tosef. Ab. Zar. III, 4</span> <span dir=\"rtl\">מַפְלִיגוֹ</span>. <span class=\"citation\">Tosef. Gitt. VII</span> (<span class=\"citation\">V), 8</span> <span dir=\"rtl\">כל תנאי שאי אפשר … לא נתכוון זה אלא להַפְלִיגָהּ</span> whenever an impossibility is made the condition of a letter of divorce, he (the husband) has had only the intention to divert her mind; Y. B. Mets. VII, end, 11ᶜ (corr. acc.). Y. Ber. IX, end, 14ᵈ <span dir=\"rtl\">כיון שה׳ דעתו ממנה</span> when he turns his attentions from her (makes her feel that he does not intend to marry her). <span class=\"citation\">Gen. R. s. 17</span> <span dir=\"rtl\">ראה … והִפְלִיגָהּ ממנו</span> when he saw her full mucus and blood, he kept her away from him; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to reject, disregard, discard</i>. <span class=\"citation\">Pesik. R. s. 31</span> <span dir=\"rtl\">היתה פושעת … ומַפְלֶגֶת את גזירותיו</span> she was careless about his honor and disregarded his decrees. <span class=\"citation\">Ib. s. 3</span> [read:] <span dir=\"rtl\">כל זמן … הוא מַפְלִיג וכ׳</span> as long as his teacher is alive, he (the pupil) is careless, (saying) whenever it be needed, here is my teacher &amp;c. <span class=\"citation\">Ab. IV, 3</span> <span dir=\"rtl\">אל תהי מפליג לכל דבר</span> discard nothing (saying, this will never happen). <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">ה׳ דרכן של רשעים וכ׳</span> he removed the way of the wicked out of his sight (disregarded the evil doings of the future man); <span class=\"citation\">Midr. Till. to Ps. I</span> ed. Bub. (oth. ed. <a href=\"#\" data-headword=\"פָּלַג\">פִּילֵּג</a> <i>Pi.</i>); a. e.</div><div class=\"sense\"><b>—5)</b> <i>to decline from the road</i>. <span class=\"citation\">Gen. R. s. 48</span> <span dir=\"rtl\">אם אני רואה אותן שהִפְלִיגוּ את דרכם וכ׳</span> when I see that they wend their way hither &amp;c.; <span dir=\"rtl\">וכיון שראה אותם שהפליגו</span> and when he saw that they were declining; Yalk. ib. 82.—Trnsf. <i>to be mistaken</i>. <span class=\"citation\">Bekh. 43ᵇ</span> bot. <span dir=\"rtl\">הִיפְלַגְתָּ</span> thou art mistaken (Rashi: thou hast gone too far, v. infra); Sifra Emor, ch. II, Par. 3 <span dir=\"rtl\">הִפְלַגְתָּה</span>.—<span class=\"citation\">Koh. R. to XI, 9</span> <span dir=\"rtl\">אל תַּפְלִיג עצמך בדברי תורה</span> do not go thy own way in the interpretation of the Law (cling to tradition).</div><div class=\"sense\"><b>—6)</b>  <span dir=\"rtl\">ה׳ עצמו</span> [<i>to withdraw one’s self</i>,] <i>to be reserved, speak in indefinite and general terms</i>, opp. <span dir=\"rtl\">פרסם עצמו</span> to reveal one’s self, speak in definite terms. Midr. Sam. ch. XIV (ref. to <span class=\"citation\">I Sam. IX, 15</span>, sq.) <span dir=\"rtl\">לשעבר לא אלא עד שלא הגיע הקץ הקב&quot;ה מפליג עצמו … מפרסם עצמו</span></div><div class=\"sense\"><b>—7)</b> <i>to differ.</i> <span class=\"citation\">Yalk. Jer. 320</span> <span dir=\"rtl\">מי שמפליג על דבריו של אל</span> who opposes the words of God. Y. Pes. V, 32ᶜ bot. <span dir=\"rtl\">ומה מַפְלִיגִין</span> and wherein do they differ?; a. e.</div><div class=\"sense\"><b>—8)</b> <i>to go too far</i>. Y. Nidd. I, beg. 48ᵈ, v. <a href=\"#\" data-headword=\"פָּרַז\">פָּרַז</a>. <span class=\"citation\">Bekh. 43ᵇ</span> bot.; Sifra Emor l. c., v. supra.—<i>Part. pass.</i> מוּפְלָג <i>a</i>) <i>removed; far</i>. Sifra M’tsorʿa, Zab., Par. 5, ch. VIII <span dir=\"rtl\">מ׳ מנידתה</span> some time after her menstruation, opp. <a href=\"#\" data-headword=\"סָמוּךְ\">סמוך</a>; <span class=\"citation\">Nidd. 73ᵃ</span> <span dir=\"rtl\">מ׳ לנדתה</span>. <span class=\"citation\">Gen. R. s. 44</span>, v. <a href=\"#\" data-headword=\"אָחַר\">אחַר</a>; a. e.—<i>b</i>) <i>distinguished, special expert</i>. <span class=\"citation\">Tosef. Ḥag. II, 9</span>, v. <a href=\"#\" data-headword=\"מוּפְלָא\">מוּפְלָא</a>.—<span class=\"citation\">Erub. 63ᵃ</span> <span dir=\"rtl\">דמופלג</span>, v. <a href=\"#\" data-headword=\"פְּלַג I\">next w.</a></div></div><div class=\"sense\"><b>Pi. פִּלֵּג</b> <div class=\"sense\"><i>to remove, disregard</i>. <span class=\"citation\">Midr. Till. to Ps. I</span>, v. supra.</div></div><div class=\"sense\"><b>Hithpa. הִתְפַּלֵּג</b> <div class=\"sense\"><i>to be divided, go apart</i>. <span class=\"citation\">Gen. R. s. 15</span> <span dir=\"rtl\">וכל מימי בראשית מִתְפַּלְּגִין מתחתיו</span> and all the waters of creation started from under it; <span class=\"citation\">Midr. Till. to Ps. I</span>; Y. Ber. I, 2ᶜ bot., v. <a href=\"#\" data-headword=\"פִּילּוּג\">פִּילּוּג</a>.</div></div>","alt":[]},"22695":{"h":"פְּלַג I","r":"Q00935","html":"<div class=\"sense\"><b>1)</b> <i>to divide, share</i>. <span class=\"citation\">Targ. Ex. XXI, 35</span> (O. ed. Vien. <span dir=\"rtl\">יְפַלְּג׳</span> <i>Pa.</i>). <span class=\"citation\">Targ. Prov. XXIX, 24</span>. <span class=\"citation\">Ib. 23</span> (h. text <span dir=\"rtl\">יתמך</span>); a. fr.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"פְּלֵיג\">פְּלִיג</a>; f. <a href=\"#\" data-headword=\"פְּלִיגָא I\">פְּלִיגָא</a>; pl. <span dir=\"rtl\">פְּלִיגִין</span>, <span dir=\"rtl\">פְּלִיגֵי</span>; <span dir=\"rtl\">פְּלִיגָן</span> <i>a</i>) <i>divided</i> (<i>at heart</i>), <i>undecided</i>. <span class=\"citation\">Targ. Hos. XI, 7</span>. <span class=\"citation\">Targ. I Kings XVIII, 37</span>. <span class=\"citation\">Ib. 21</span>; a. e.—[<span class=\"citation\">Targ. Ps. XLIV, 19</span>, v. infra.]—<i>b</i>) (with <span dir=\"rtl\">על</span>) <i>differing in opinion</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 1</span>.—<span class=\"citation\">B. Mets. 5ᵃ</span>, a. fr. <span dir=\"rtl\">תנא הוא ופ׳</span> he is a Tannai, and (as such) he differs (from the Mishnah). <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> top, a. fr. <span dir=\"rtl\">מתניתא פ׳ על וכ׳</span> the Boraitha differs from Rab. <span class=\"citation\">Ḥull. 92ᵇ</span> <span dir=\"rtl\">הא מִפְלֵיג פליגי ביה</span> are there not differing opinions about it? <span class=\"citation\">Ber. 23ᵇ</span> <span dir=\"rtl\">ופליגא דר׳ חייא</span> and R. Ḥia’s opinion differs (from what has just been said). <span class=\"citation\">Ib. 33ᵇ</span> <span dir=\"rtl\">מכלל דפליגי</span> this implies that scholars differ about it; <span dir=\"rtl\">ולא פ׳</span> and do they not differ?; a. v. fr.—<i>c</i>) <i>distinguished, rare</i>, v. infra.</div><div class=\"sense\"><b>Pa. פַּלֵּג</b> <div class=\"sense\"><b>1)</b> <i>to divide; to distribute, assign a share</i>. <span class=\"citation\">Targ. O. Ex. XXI, 35</span>, v. supra. <span class=\"citation\">Targ. O. Gen. XV, 10</span>. <span class=\"citation\">Targ. Ps. XLIV, 19</span> (not <a href=\"#\" data-headword=\"פְּלֵיג\">פְּלִיג</a>), v. <a href=\"#\" data-headword=\"זְהַהּ\">זְהַהּ</a>. <span class=\"citation\">Targ. Job XXXIX, 17</span>. <span class=\"citation\">Targ. Ps. LXVIII, 14</span>. <span class=\"citation\">Ib. 13</span> Ms. (ed. <span dir=\"rtl\">מַפְלְגָא</span> <i>Af.</i>). <span class=\"citation\">Targ. I Chr. XXVI, 5</span>; a. fr.—<span class=\"citation\">B. Bath. 119ᵇ</span> <span dir=\"rtl\">דפ׳ ליה רביה יקרא</span> when his teacher did him honor. Y. Shek. II, end, 47ᵃ <span dir=\"rtl\">מה את פַּלֵּיג ליה וכ׳</span> why wilt thou do him (the idol) honor?; Y. Ber. II, 4ᵇ <span dir=\"rtl\">איתפליג</span> (corr. acc.). Y. Sabb. VII, 10ᵃ bot. <span dir=\"rtl\">כד מְפַלֵּג</span> when he divides (the flax stalks). <span class=\"citation\">Lev. R. s. 3</span>, beg. <span dir=\"rtl\">ומְפַלְּגָא לבישיא</span>, v. <a href=\"#\" data-headword=\"גּוּף\">גּוּף</a> I ch.; <span class=\"citation\">Koh. R. to IV, 6</span>; a. e.—[Y. Kidd. IV, 65ᶜ top <span dir=\"rtl\">פלגין</span>, v. <a href=\"#\" data-headword=\"פְּלַג II\"><span dir=\"rtl\">פְּלַג</span> II</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to divert the mind</i>. <span class=\"citation\">Targ. Y. Deut. IV, 19</span>. <span class=\"citation\">Ib. XXII, 1</span>.</div><div class=\"sense\"><b>—3)</b> <i>to speak differently from what one thinks, flatter</i>. <span class=\"citation\">Targ. Prov. XXVIII, 23</span> Ms. (ed. <i>Af.</i>).</div></div><div class=\"sense\"><b>Af. אַפְלֵג</b> <div class=\"sense\"><b>1)</b> <i>to separate</i>. <span class=\"citation\">Targ. Y. Gen. XLIX, 7</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to divert</i>. <span class=\"citation\">Targ. Y. II, Gen. XLV, 26</span> <span dir=\"rtl\">וְאַ׳ ליביה</span> (Y. I <span dir=\"rtl\">יפַּלֵּיג</span>, ed. Vien. <span dir=\"rtl\">ופְלֵיג</span>) he turned his mind off it (gave up hope, would not believe; h. text <span dir=\"rtl\">ויפג</span>). <span class=\"citation\">Targ. Prov. XIV, 30</span> <span dir=\"rtl\">דמַפְלִיג חמתא וכ׳</span> who diverts the anger of his heart; a. e.</div></div><div class=\"sense\"><b>Ithpa. אִתְפַּלֵּג</b> </div><div class=\"sense\"><b>Ithpe. אִתְפְּלֵג  אִיפְּלִיג</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אִפְּ׳</a> </div><div class=\"sense\"><b>1)</b> <i>to be divided, dispersed</i>. <span class=\"citation\">Targ. Num. XXVI, 53</span>; <span class=\"citation\">55</span>. <span class=\"citation\">Targ. Gen. XIV, 15</span>; a. fr.—<span class=\"citation\">B. Bath. 121ᵇ</span> א&quot;י לשבטים נתחלקה או דילמא קרקף גברא אִיפַּלְּגָא Ms. M. was the land of Israel divided according to tribes (in equal shares for each tribe), or according to the number of heads?; ed. <span dir=\"rtl\">א&quot;י לשבטים אִיפְּלוּג … איפלוג</span> (sub. <span dir=\"rtl\">נחלות</span></div><div class=\"sense\"><b>—2)</b> <i>to be different from the rest, rare, distinguished</i>. Ib. 120ᵃ <span dir=\"rtl\">דמִפְּלִיג בחכמה</span> (Ms. R. <span dir=\"rtl\">דפליג</span>) of rare wisdom, <span dir=\"rtl\">דמפ׳ בזקנה</span> extremely old. <span class=\"citation\">Gitt. 28ᵃ</span> <span dir=\"rtl\">כיון דאיפ׳ אפ׳</span> having reached a rare old age, he may as well be presumed to be more distinguished (and be still alive). <span class=\"citation\">Erub. 63ᵃ</span> <span dir=\"rtl\">שאני … דמִיפְּלַג</span> (Ar. a. Ms. O. <span dir=\"rtl\">דמוּפְלָג</span> h. form) it is different with R. …, for he was very distinguished (for age and learning); a. e.</div><div class=\"sense\"><b>—3)</b>  (cmp. <span dir=\"rtl\">גזר</span>) <i>to be decreed</i>. <span class=\"citation\">Targ. Y. Gen. XIV, 7</span> (v. <a href=\"#\" data-headword=\"פִּילּוּג ²\">פִּילּוּגָא</a>).</div><div class=\"sense\"><b>—4)</b> <i>to secede; to differ.</i> <span class=\"citation\">Targ. O. Num. XVI, 1</span> (h. text <span dir=\"rtl\">ויקח</span>). <span class=\"citation\">Targ. II Kings XVII, 21</span>; a. fr.—Y. Taan. IV, 67ᵈ top <span dir=\"rtl\">ואפי׳ עלה לא הוה צריך מִתְפַּלְּגָה</span> even about this it was unnecessary to assume a difference of opinion. <span class=\"citation\">Gen. R. s. 21</span> אִיתְפַּלְּגוּן ר׳ וכ׳ R. A. and R. H. differ (in their interpretations). <span class=\"citation\">Ber. 22ᵇ</span> bot. <span dir=\"rtl\">בהא קמִיפַּלְּגֵי</span> (popular pronunciation <span dir=\"rtl\">קמִיפְלְגֵי</span>) on this principle their difference rests. <span class=\"citation\">Ib. 23ᵃ</span>; a. v. fr.</div></div>","alt":["פְּלֵיג"]},"22696":{"h":"פֶּלֶג","r":"Q00936","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"פְּלַג I\">preced.</a>) <i>part, share</i>. Tanḥ. <span class=\"citation\">Mishp. 7</span> (ref. to <span class=\"citation\">Prov. XXVIII, 23</span>) <span dir=\"rtl\">כל המוכיח … זוכה לפ׳ של הקב&quot;ה</span> he who reproves his neighbor for the sake of heaven, will be granted a share of divine grace; (<span class=\"citation\">Tam. 28ᵃ</span> <span dir=\"rtl\">לחלקו</span>).—Pl. <a href=\"#\" data-headword=\"פְּלַגּוֹת\">פְּלַגּוֹת</a>. <span class=\"citation\">Gitt. 89ᵇ</span> (borrowing the phrase from <span class=\"citation\">Jud. V, 16</span>) <span dir=\"rtl\">עדיין לא הגיע לפ׳ ראובן</span> he (that minor, although physically developed beyond his age) has not yet obtained ‘the parts of Reuben’ (mental maturity, and none will consider him an adult).</div>","alt":[]},"22697":{"h":"פָּלָג","r":"Q00937","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פֶּלֶג\">preced.</a>) <i>part, middle</i>. <span class=\"citation\">Ber. IV, 1</span>, a. e. <span dir=\"rtl\">פּלג המנחה</span>, v. <a href=\"#\" data-headword=\"מִנְחָה\">מִנְחָה</a>.</div>","alt":[]},"22698":{"h":"פְּלַג II","r":"Q00938","html":"<div class=\"sense\"><b>1)</b> <i>part, half</i>. <span class=\"citation\">Targ. O. Gen. XV, 10</span> (ed. Berl. <a href=\"#\" data-headword=\"פְּלַג I\">פַּלַג</a>; ed. Vien. <a href=\"#\" data-headword=\"פִּלּוּג\">פִּלּוּג</a>). <span class=\"citation\">Targ. Ex. XXV, 10</span> (Y. also <a href=\"#\" data-headword=\"פּוּלְגָּא\">פּוּלְגָּא</a>); a. fr.—[<span class=\"citation\">Targ. I Chr. XVI, 3</span>, v. <a href=\"#\" data-headword=\"פְּלוּג\">פְּלוּג</a>.]—<span class=\"citation\">B. Bath. 62ᵇ</span> <span dir=\"rtl\">פ׳ דאית לי בארעא פ׳</span> if the deed reads, ‘the half share which is mine in that field’, he has sold half the field (his entire share); <span dir=\"rtl\">פ׳ בארעא דאית לי ריבעא</span> but if it reads, ‘half of that field which is mine’, he has sold him one fourth of the field (or half his share). Ib. <span dir=\"rtl\">מצר ארעא דמינה פ׳ פ׳</span> (Ms. M. <a href=\"#\" data-headword=\"פְּלִיגָא I\">פְּלִיגָא</a>) if he writes, ‘these are the borders of the field of which I sell a portion’, it means <i>half</i>, contrad. to <a href=\"#\" data-headword=\"פְּסִיקָא I\">פְּסִיקָא</a>; ib. 63ᵃ. <span class=\"citation\">Sabb. 89ᵇ</span> <span dir=\"rtl\">דל תרתי סרי ופ׳ וכ׳</span> deduct (from the years of life) twelve years and a half for prayer, eating &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ עלי ופ׳ עלך</span> let me bear the failings of half the remaining years, and bear thou the other half. <span class=\"citation\">Pes. 79ᵇ</span> <span dir=\"rtl\">פ׳ ופ׳</span> equal numbers on both sides. Y. Kidd. IV, 65ᶜ top <span dir=\"rtl\">דבהתין פַּלְגּוֹן מן פלגון</span> (not <span dir=\"rtl\">מן פלג</span>) one half of them is afraid of the other half of them; <span class=\"citation\">Num. R. s. 8</span> <span dir=\"rtl\">פלגין מן פלגין</span> (corr. acc.); a. v. fr.—Pl. <span dir=\"rtl\">פַּלְגַּיָּא</span>, <a href=\"#\" data-headword=\"פַּלְגּוּתָא\">פַּלְגֵּי</a>. <span class=\"citation\">Targ. O. Gen. XV, 10</span>. <span class=\"citation\">Ib. 17</span> (h. text <span dir=\"rtl\">הגזרים</span>). <span class=\"citation\">Ib. 11</span> ed. Berl. (v. <a href=\"#\" data-headword=\"פְּגַר III\">פִּגְרָא</a>); a. e.—<span class=\"citation\">Yoma 83ᵇ</span>, v. <a href=\"#\" data-headword=\"פְּלוּג\">פְּלוּג</a>.</div><div class=\"sense\"><b>—2)</b>  רוח פלגא <i>the demon Palga, a disease</i> (paralysis?). <span class=\"citation\">Pes. 111ᵃ</span></div>","alt":["פַּלְגָּא"]},"22699":{"h":"פַּלָּגָא","r":"Q00939","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְגָּאָה\">next w.</a></div>","alt":[]},"22700":{"h":"פַּלְגָּאָה","r":"Q00940","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (פְּלַג I) <i>disputer, controversialist</i>. <span class=\"citation\">Erub. 61ᵇ</span> <a href=\"#\" data-headword=\"פ׳\">פ׳</a> thou disputer (Mar Judah)! <span class=\"citation\">Kidd. 58ᵃ</span> <span dir=\"rtl\">פַּלָּגָא איקמיינכי</span> that disputer (Mar Judah) has put you up to it. <span class=\"citation\">Gitt. 31ᵇ</span> <span dir=\"rtl\">מקמי פ׳ ניקום</span> shall we rise for that querulous man (G’nibah)?</div>","alt":[]},"22701":{"h":"פְּלָגָה","r":"Q00941","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"הַפְלָגָה\">הַפְלָגָה</a> <i>separation</i> (of languages), <i>scattering</i>. <span class=\"citation\">Yalk. Gen. 62</span> (quot. fr. Seder ʿOlam).</div>","alt":[]},"22702":{"h":"פַּלְגּוּ","r":"Q00942","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּלָגָה\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>half; middle</i>. <span class=\"citation\">Targ. Lev. VI, 13</span>. <span class=\"citation\">Targ. O. Ex. XI, 4</span>; a. fr.—<span class=\"citation\">B. Kam. 15ᵃ</span>, a. e. <span dir=\"rtl\">פלגו נזקא</span> Ms. H. a. Ar. (Ms. M. <a href=\"#\" data-headword=\"פַּלְגּוּתָא\">פַּלְגִּי</a>; ed. <span dir=\"rtl\">פלגא</span>) indemnity amounting to half the damage. <span class=\"citation\">Y. Keth. VII, 31ᶜ</span> <span dir=\"rtl\">פַּלְגּוּת פרן</span> (<a href=\"#\" data-headword=\"פַּרְגִּית\">פַּלְגִּית</a>) half the dowry. <span class=\"citation\">Y. Pes. V, 32ᶜ</span> bot. <span dir=\"rtl\">בפלגות פומך</span> with half thy mouth, i.e. thou art not the original author of that opinion; a. e.—<span class=\"citation\">Snh. 98ᵇ</span> <span dir=\"rtl\">פלגו קיסר</span> (<a href=\"#\" data-headword=\"פַּלְגּוּתָא\">פלגי</a>) <i>Vice-Caesar, governor</i></div><div class=\"sense\"><b>—2)</b> <i>division</i>(h. .—Pl. <span dir=\"rtl\">פַּלְגְּיָון</span>, <span dir=\"rtl\">פַּלְגְּוָואתָא</span>. <span class=\"citation\">Targ. Zech. XI, 7</span> (ed. Lag. <a href=\"#\" data-headword=\"פּוּלְגְּוָון\">פּוּלְגְּוָון</a>). <span class=\"citation\">Targ. I Chr. XXVI, 1</span>; <span class=\"citation\">12</span> <span dir=\"rtl\">פלגווא׳</span> ed. Wil. (oth. ed. <a href=\"#\" data-headword=\"פַּלְגּוּתָא\">פַּלְגּוּתָא</a>, <a href=\"#\" data-headword=\"פְּלַגּוֹת\">פַּלְגּוּת</a>, read: <a href=\"#\" data-headword=\"פַּלְגּוּתָא\">פַּלְגְּוָתָא</a>, <a href=\"#\" data-headword=\"פְּלַגּוֹת\">פַּלְגְּוַת</a>); a. e.—<span class=\"citation\">Y. Erub. IX, beg. 25ᶜ</span> <span dir=\"rtl\">ארבע פלגוון</span> four divisions (of opinions).</div><div class=\"sense\"><b>—3)</b> <i>division of heart, half-heartedness</i>. <span class=\"citation\">Targ. Y. II, Gen. XXII, 14</span>.</div><div class=\"sense\"><b>—4)</b> <i>contest</i>. <span class=\"citation\">Targ. II Sam. XXII, 44</span> ed. Wil., v. <a href=\"#\" data-headword=\"פְּלוּגְתָּא II\"><span dir=\"rtl\">פְּלוּגְתָּא</span> I</a>.</div>","alt":["פַּלְגּוּתָא"]},"22703":{"h":"פלגוגון","r":"Q00943","html":"<div class=\"sense\">, a corrupt. for <span dir=\"rtl\">פַּדְגּוֹגוֹן</span> m. (παιδαγωγῶν) <i>teaching, training</i>. Y’lamd. to Deut. V, 6 sq., quot. in Ar. <span dir=\"rtl\">אלפיים שנה היה הקב&quot;ה פ׳ בה וכ׳</span> two thousand years (two days of the Lord’s, before the creation of the world) the Lord used her (the Torah) as a pedagogue (disciplining the forces of Nature, with ref. to <span dir=\"rtl\">יום יום</span>, <span class=\"citation\">Prov. VIII, 30</span>); cmp. <span class=\"citation\">Gen. R. s. 1</span>, beg.</div>","alt":["פלגוגין"]},"22704":{"h":"פַּלְגּוֹס","r":"Q00944","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילָגוֹס\">פִּילָגוֹס</a></div>","alt":[]},"22705":{"h":"פְּלַגּוֹת","r":"Q00945","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּלֶג\">פֶּלֶג</a></div>","alt":[]},"22706":{"h":"פַּלְגּוּתָא","r":"Q00946","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְגּוּ\">פּלְגּוּ</a></div>","alt":["פַּלְגִּי"]},"22707":{"h":"פַּלְגִּיסָא","r":"Q00947","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pales of <a href=\"#\" data-headword=\"פְּלַג I\">פְּלַג</a>; cmp. <a href=\"#\" data-headword=\"*אִסְפְּרִיסָא\">אִסְפְּרִיסָא</a>) [<i>that which is to be split</i>,] <i>target for projectiles</i> (cmp. <span dir=\"rtl\">קורת חצים</span> <span class=\"citation\">Lam. R. to III, 12</span>). <span class=\"citation\">Targ. I Sam. XX, 20</span>. <span class=\"citation\">Targ. Job XVI, 12</span> (ed. Lag. <a href=\"#\" data-headword=\"פְּלַגְסָא\">פְּלַגְסָא</a>). <span class=\"citation\">Targ. Lam. III, 12</span> (ed. Lag. a. oth. <a href=\"#\" data-headword=\"פַּלְגְּלִיסָא\">פלגליסא</a>).</div>","alt":[]},"22708":{"h":"פַּלְגִיסִין","r":"Q00948","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְגְּס\">פַּלְגֵּס</a></div>","alt":[]},"22709":{"h":"פַּלְגִּיתָא","r":"Q00949","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְגּוּ\">פּלְגּוּ</a></div>","alt":[]},"22710":{"h":"פַּלְגְּלִיסָא","r":"Q00950","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְגִּיסָא\">פַּלְגִּיסָא</a></div>","alt":[]},"22711":{"h":"פלגס","r":"Q00951","html":"<div class=\"sense\">, <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> bot., v. <a href=\"#\" data-headword=\"פִּינוֹלֵס\">פִּינוֹלֵס</a></div>","alt":[]},"22712":{"h":"פַּלְגְּס","r":"Q00952","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πάλλαξ, πάλληξ, prob. of Semitic origin; cmp. <a href=\"#\" data-headword=\"פַּלְגִּיסָא\">פַּלְגִּיסָא</a>, a. <a href=\"#\" data-headword=\"פִּלֶּגֶשׁ\">פִּלֶּגֶשׁ</a>) <i>a youth in the intermediate stage between boyhood and maturity</i>; trnsf. <i>a sheep beyond the age of</i> כֶּבֶשׂ <i>and below that of</i> <a href=\"#\" data-headword=\"אַיִל\">אַיִל</a> (v. <a href=\"#\" data-headword=\"נָקַד I\">ניּקָּד</a>). <span class=\"citation\">Par. I, 3</span> רבי טרפין קורהו פ׳ R. T. named such a sheep of thirteen months a <i>pallax</i>. <span class=\"citation\">Ḥull. 23ᵃ</span>. <span class=\"citation\">Tosef. ib. I, 14</span> <span dir=\"rtl\">הפ׳ בזה ובזה פסול</span> the <i>pallax</i> is unfit for sacrifice either as <a href=\"#\" data-headword=\"כֵּבַשׁ I\">כבש</a> or as <span dir=\"rtl\">איל</span>.—Pl. ch. <a href=\"#\" data-headword=\"פַּלְגִיסִין\">פַּלְגִּיסִין</a>. <span class=\"citation\">Targ. Ps. XXXVII, 20</span> (h. text <a href=\"#\" data-headword=\"כרים\">כרים</a>).</div>","alt":[]},"22713":{"h":"פְּלַגְסָא","r":"Q00953","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְגִּיסָא\">פַּלְגִּיסָא</a></div>","alt":[]},"22714":{"h":"פִּלֶּגֶשׁ","r":"Q00954","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. Delitzsch Genesis<sup>4</sup> 360) <i>concubine</i>. <span class=\"citation\">Y. Keth. V, 29ᵈ</span> top <span dir=\"rtl\">אשה יש לה כתובה פ׳ אין וכ׳</span> the wife has a marriage contract securing a settlement for her <a href=\"#\" data-headword=\"כְּתוּבָּה\">(כְּתוּבָּה</a>), the concubine has none; (oth. opin.) <span dir=\"rtl\">אשה יש לה כתובה ותנאי כתובה פ׳ וכ׳</span> the wife has a marriage contract containing besides the settlement all conditions of a marriage contract (alimentation &amp;c.), the concubine has the contract but without the conditions; a. fr.—<span dir=\"rtl\">פ׳ בגבעה</span>, v. <a href=\"#\" data-headword=\"גִּבְעָה\">גִּבְעָה</a>.—Pl. <span dir=\"rtl\">פִּלַּגְשִׁים</span>, <a href=\"#\" data-headword=\"פִּלַּקְתָּא\">פִּילַ׳</a>. <span class=\"citation\">Snh. 21ᵃ</span>. <span class=\"citation\">Num. R. s. 9</span> (ref. to <span class=\"citation\">Cant. VI, 8</span>) <span dir=\"rtl\">שמונים … ונקראו פ׳ שהפ׳ חשודות</span> there are eighty families (of nations) that know their mothers but not their fathers, and they are called ‘concubines’, for the concubines are suspected (of faithlessness).</div>","alt":["פִּילֶגֶשׁ"]},"22715":{"h":"פְּלֻגְתָּא","r":"Q00955","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוּגְתָּא\">פְּלוּגְתָּא</a></div>","alt":[]},"22716":{"h":"פלדוס","r":"Q00956","html":"<div class=\"sense\">, read:</div>","alt":[]},"22717":{"h":"פַּלְדֵּיס","r":"Q00957","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בַּרְדְּסִין\">בַּרְדְּסִין</a>) <i>Brundisian cloak, travelling cloak</i>. Tosef. Meg. IV (III), 30 ed. Zuck. (Var. <a href=\"#\" data-headword=\"פילרוס\">פילרוס</a>, corr. acc.).</div>","alt":[]},"22718":{"h":"פַּלְדֵּיסִין","r":"Q00958","html":"<div class=\"sense\"> ch. pl. <a href=\"#\" data-headword=\"פַּלְדֵּיס\">same</a>. <span class=\"citation\">Targ. Jud. XIV, 12</span>, sq. (ed. Lag. <a href=\"#\" data-headword=\"פַּלְדֵּיסִין\">פילדי׳</a>). <span class=\"citation\">Targ. II Kings V, 23</span>. <span class=\"citation\">Targ. II Chr. IX, 24</span> <span dir=\"rtl\">פ׳ דכין</span> (ed. Wil. <span dir=\"rtl\">פ׳ דבוץ</span>; h. text <span dir=\"rtl\">שמלות</span>).</div>","alt":["פִּלְדְּסִין","פִּילְדֵּי׳"]},"22719":{"h":"פָּלָה","r":"Q00959","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פלי\">פלי</a></div>","alt":[]},"22720":{"h":"פַּלְהֶדְרִין","r":"Q00960","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּרְהֶדְרִין\">פַּרְהֶדְרִין</a></div>","alt":[]},"22721":{"h":"פְּלוּג","r":"Q00961","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּלַג I\">פְּלַג</a>) <i>a portion</i> (of meat). <span class=\"citation\">Targ. II Sam. VI, 19</span>; <span class=\"citation\">Targ. I Chr. XVI, 3</span> (ed. Lag. <a href=\"#\" data-headword=\"פְּלַג I\">פלג</a>; h. text <span dir=\"rtl\">אשפר</span>).—Pl. <span dir=\"rtl\">פְּלוּגֵי</span>. <span class=\"citation\">Meg. 7ᵇ</span> אכלי בהו שתין פ׳ I ate sixty portions of them. <span class=\"citation\">Yoma 83ᵇ</span> אהדרוהו פ׳ וצעי Ms. M. 2 a. Ar. (Ms. M. 1 <a href=\"#\" data-headword=\"פְּלָאגֵי\">פְּלָאגֵי</a>) they placed fine portions and dishes around him (v., however, <a href=\"#\" data-headword=\"לוּגָּא\">לוּגָּא</a>).</div>","alt":[]},"22722":{"h":"פִּלּוּג","r":"Q00962","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פַּיְלָוָון\">פִּילּ׳</a>.</div>","alt":["פִּלּוּגָא"]},"22723":{"h":"פְּלוֹגֶת","r":"Q00963","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּלַג\">פָּלַג</a>) <i>division, dispute</i>. <span class=\"citation\">Cant. R. to VIII, 13</span> <span dir=\"rtl\">פ׳ דברים</span> verbal disputes.</div>","alt":[]},"22724":{"h":"פְּלוּגְתָּא","r":"Q00964","html":"<div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"הַפְלָגָה\">הַפְלָגָה</a> <i>separation</i> (of races). (of races). <span class=\"citation\">Targ. Y. Gen. X, 11</span>.</div><div class=\"sense\"><b>—2)</b>  (<i>priestly</i>) <i>division</i>.—Pl. <span dir=\"rtl\">פְּלוּגְוָותָא</span>, <span dir=\"rtl\">פְּלוּגְוָתָא</span>. <span class=\"citation\">Targ. II Chr. XXIII, 8</span>. <span class=\"citation\">Ib. VIII, 14</span>. <span class=\"citation\">Ib. XXXV, 4</span>, sq.; a. e.</div><div class=\"sense\"><b>—3)</b> <i>contest, dissension</i>. <span class=\"citation\">Targ. Ps. XVIII, 44</span> פ׳ דעממיא Ms. (ed. <span dir=\"rtl\">פְּלוּגַת ע׳</span> constr.; ed. Wil. <span dir=\"rtl\">פְּלֻגַת</span>; h. text <span dir=\"rtl\">ריבי</span>); <span class=\"citation\">Targ. II Sam. XXII, 44</span> (ed. Wil. <a href=\"#\" data-headword=\"פְּלַגּוֹת\">פַּלְגוּת</a>). <span class=\"citation\">Targ. Is. XXII, 9</span>. <span class=\"citation\">Targ. Deut. XVII, 8</span>; a. e.—Tanḥ. Kor. 10 <span dir=\"rtl\">מה ליך בהדי פ׳</span> (not <span dir=\"rtl\">בהדין</span>) what hast thou to do with that contest (between Moses and Korah)?; <span class=\"citation\">Num. R. s. 18</span> (ed. Wil. <span dir=\"rtl\">בהדי פְּלוּגְתֵּיה</span> with his (Korah’s) quarrel).—Esp. <i>difference of opinion, scholarly contest</i>. <span class=\"citation\">Yoma 4ᵇ</span> … <span dir=\"rtl\">במאי קא מיפלגי בפ׳ דהני תנאי וכ׳</span> what is the basis of the difference …? The principle on which those Tannaim differ &amp;c. <span class=\"citation\">Sabb. 15ᵃ</span> <span dir=\"rtl\">היכא דליכא פ׳ דרבוותא בהדייהו</span> on a subject on which no conflicting opinions of great teachers besides them (Hillel and Shammai) are on record; a. v. fr.—<i>Pl.</i> as ab. <span class=\"citation\">Y. Pes. III, 30ᵃ</span> bot. <span dir=\"rtl\">אתיין אילין פ׳ כאילין פ׳ וכ׳</span> (not <a href=\"#\" data-headword=\"פְּלוּגְתָּא\">פלוגתא</a>) the differences in this case are based on the same principles as the differences in the following case &amp;c.; <span class=\"citation\">Y. Taan. IV, 67ᵈ</span> top; <span class=\"citation\">Y. Ned. V, 39ᵇ</span> top; a. e.—V. <a href=\"#\" data-headword=\"תַּפְלוּגְתָּא\">תַּפְלוּגְתָּא</a>.</div>","alt":["פְּלֻגְ׳"]},"22725":{"h":"פְּלוּגְתָּא II","r":"Q00965","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>P’lugta</i>, near Tiberias. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">כגון הדה בית מעון שיורדים לה מפ׳ וכ׳</span> like Beth-Maʿon to which they go down when coming from P., and up from Tiberias; (<span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">כפר שובתי</span>; Y. Sot. I, 17ᵃ bot. <a href=\"#\" data-headword=\"פלטתה\">פלטתה</a>). <span class=\"citation\">Lev. R. s. 5</span> (ref. to <span class=\"citation\">Am. VI, 6</span>) they got their wine <span dir=\"rtl\">מפ̇ל̇וג̇ת̇א שעל יינם נתפ̇ת̇ו וג̇ל̇ו וכ׳</span> from P., for on account of their wine the ten tribes were led astray, and had to go into exile (v. <a href=\"#\" data-headword=\"פְּתוּגְתָּא\">פְּתוּגְתָּא</a>); <span class=\"citation\">Num. R. s. 10</span>; Yalk. Am. 545. <span class=\"citation\">Sabb. 147ᵇ</span> <span dir=\"rtl\"><span dir=\"rtl\">חמרא דפרוגייתא</span> (דפרוגיתא</span>).</div>","alt":["פְּלוּגְתָּה"]},"22726":{"h":"פלווטין","r":"Q00966","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Yoma I, 1</span> ed. Zuck. (Var. <span dir=\"rtl\">בלווטין</span>), read: <span dir=\"rtl\">בּוּלֶוְוטִין</span>.</div>","alt":[]},"22727":{"h":"פִּלְוָון","r":"Q00967","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"פְּיָילִי I\">פְּיָילִי</a>.</div>","alt":[]},"22728":{"h":"פלוטומיא","r":"Q00968","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילוֹטִימְיָא\">פִּילוֹטִימֽיָא</a>.</div>","alt":[]},"22729":{"h":"פלוטומנין","r":"Q00969","html":"<div class=\"sense\">, <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">(פול׳</span>); <span class=\"citation\">Pesik. R. s. 7</span> <span dir=\"rtl\">פולטומין</span>, read <span dir=\"rtl\">פַּלָּטִינִין</span>.</div>","alt":[]},"22730":{"h":"פלוטית","r":"Q00970","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלֵיטִית\">פְּלֵיטִית</a></div>","alt":[]},"22731":{"h":"פלוטמיא","r":"Q00971","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילוֹטִימְיָא\">פִּילוֹטִימְיָא</a></div>","alt":[]},"22732":{"h":"פִּלּוּל","r":"Q00972","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילּוּל\">פִּילּוּל</a></div>","alt":[]},"22733":{"h":"פלולויה","r":"Q00973","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ned. VII, beg. 40ᵇ</span>, v. <a href=\"#\" data-headword=\"מסרולה\">מסרולה</a></div>","alt":[]},"22734":{"h":"פלולינא","r":"Q00974","html":"<div class=\"sense\">, read:</div>","alt":[]},"22735":{"h":"פְּלוּלִינַיָּא","r":"Q00975","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">פלל</span>, cmp. <a href=\"#\" data-headword=\"פִּלְפְּלָא\">פלפלא</a>; cmp. Syr. <span dir=\"rtl\">פלילתא</span> fœnum græcum, P. Sm. 3130) <i>a preserve or sauce of fenugrec</i>, containing an admixture of fermenting matter. <span class=\"citation\">Y. Pes. III, 30ᵃ</span></div>","alt":[]},"22736":{"h":"*פְּלוּמָא","r":"Q00976","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (pluma) <i>down, down-pillow</i>. <span class=\"citation\">Cant. R. to I, 17</span> <span dir=\"rtl\">אבנים … כמטה וכפ׳</span> the stones on which Jacob slept, became under him as (soft as) a bed and as a pillow; [<span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">וכפרנוס</span>, some ed. <span dir=\"rtl\">וכפירנס</span>; <span class=\"citation\">Yalk. ib. 119</span> <span dir=\"rtl\">וכפורנס</span>, corr. acc., or read: <span dir=\"rtl\">וכטוֹרוּס</span>.]</div>","alt":["פְּלוּמָה"]},"22737":{"h":"פְּלוֹמוֹפִּילוֹן","r":"Q00977","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corrupt. of primipilum, v. Perl. Beitr., p. 11) <i>the office of the chief Centurio of the troop called Triarii, primipilate</i>. <span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">לקיטרון … שימש פ׳ שלו וכ׳</span> like a Centurio who had served his term but failed to enter his primipilate (to which he would have been promoted in due time), but fled &amp;c.; <span class=\"citation\">Yalk. Lev. 631</span> <a href=\"#\" data-headword=\"פּוֹלִימַרְכוֹס\">פולימרכוס</a> (corr. acc.); <span class=\"citation\">Yalk. Ex. 178</span> <span dir=\"rtl\">פלומי פילון</span> (corr. acc).</div>","alt":[]},"22738":{"h":"פְּלוּמְטַר","r":"Q00978","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוּמַטְרִין\">next w.</a></div>","alt":[]},"22739":{"h":"פְּלוּמַטְרִין","r":"Q00979","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (privatarium) (<i>private</i>) <i>money chest, jewelry box</i>. <span class=\"citation\">Pesik. R. s. 10</span> <span dir=\"rtl\">למלך שהיו לו תסבריות … פ׳ אחד של זהב קטן וכ׳</span> like a king who had many (public) treasures and cared not to count them, but he had one small private chest filled with gold &amp;c. <span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot. <span dir=\"rtl\">ומפתחא דפלמנטרין בידיה</span> with the key of his money chest in his hand. <span class=\"citation\">Y. Taan. II, 65ᵈ</span> <span dir=\"rtl\">מפתח של פלמנטרין קטנה</span> (En Yaʿăḳob <a href=\"#\" data-headword=\"פלטרים\">פלטרים</a>, <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פלטרין</a>) a small key of a jewelry box. <span class=\"citation\">Ex. R. s. 20</span>, beg. <a href=\"#\" data-headword=\"דיפלומטר\">דיפלומטר</a>, <span dir=\"rtl\">הד׳</span>, read: <span dir=\"rtl\">הפלומטר</span>.</div>","alt":[]},"22740":{"h":"פלומי","r":"Q00980","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוֹמוֹפִּילוֹן\">פְּלוֹמוֹפִּילוֹן</a></div>","alt":["פ׳ פילון"]},"22741":{"h":"פְּלוּמַקְיָא","r":"Q00981","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (plumacia) <i>down-pillows</i>. <span class=\"citation\">Midr. Till. to Ps. III</span> ed. Bub. (expl. <a href=\"#\" data-headword=\"מִשְׁכָּב\">משכב</a>, <span class=\"citation\">II Sam. XVII, 28</span>) [read:] <span dir=\"rtl\">אלו פ׳ ומצעות</span> (not <a href=\"#\" data-headword=\"פלוקמיא\">פלוקמיא</a>, v. Bub. note a. l.) that means down-pillows and mattresses; (ed. <span dir=\"rtl\">כרים וכסתות</span>); <span class=\"citation\">Yalk. Sam. 151</span> <a href=\"#\" data-headword=\"פולוסיקא\">פולוסיקא</a> (corr. acc.).</div>","alt":[]},"22742":{"h":"פְּלוֹנִי","r":"Q00982","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a specified person</i> or <i>thing, such and such, name ‘blank’</i> (abbrev. <span dir=\"rtl\">פלו׳</span>). <span class=\"citation\">Gitt. VI, 3</span> <span dir=\"rtl\">במקים פ׳</span> in such and such a place. Y. ib. VIII, end, 49ᵈ (in a document) <span dir=\"rtl\">אני פ׳ בן פ׳ I</span>—, son of—. <span class=\"citation\">Kidd. 65ᵃ</span> קידשתיך בפני פ׳ ופ׳ והלכו וכ׳ I betrothed thee unto me in the presence of—and—, and they have left &amp;c. <span class=\"citation\">Tosef. Yeb. III, 4</span> <span dir=\"rtl\">ופ׳ מהו לעה&quot;ב</span> and will such and such a man have a share in the hereafter?; <span dir=\"rtl\">דומה שלא שאלתם אלא על פ׳</span> it seems to me that you inquired about such and such (naming some one else); <span class=\"citation\">Yoma 66ᵇ</span>; a. fr.—<span class=\"citation\">Koh. R. to I, 8</span>, v. <a href=\"#\" data-headword=\"יֵשׁוּ\">יֵשׁוּ</a>.—<i>Fem</i>. <a href=\"#\" data-headword=\"פְּלֹנִית\">פְּלוֹנִית</a>, <a href=\"#\" data-headword=\"פְּלֹנִית\">פְּלֹנִית</a>. <span class=\"citation\">Kidd. III, 1</span> <span dir=\"rtl\">צא וקדש לי אשה פ׳</span> go and betroth for me that certain woman. <span class=\"citation\">Y. Sot. VI, 21ᵃ</span> top <span dir=\"rtl\">פ׳ כהנת וכ׳</span> such and such is a priest’s daughter, and she has prostituted herself &amp;c.; a. fr.—Ch. <a href=\"#\" data-headword=\"פְּלַן\">פְּלַן</a>.</div>","alt":["פְּלֹנִי"]},"22743":{"h":"פלוניא","r":"Q00983","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 61</span>, v. <a href=\"#\" data-headword=\"פִּיוְולָא\">פִּיוְולָא</a></div>","alt":[]},"22744":{"h":"פלוניקיא","r":"Q00984","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פִּילוֹן\">פִּילוֹ׳</a>.</div>","alt":["פלוסופא","פלוסופוס"]},"22745":{"h":"פְּלוֹסְלוֹס I","r":"Q00985","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלֹסְלוֹס\">פְּלֹסְלוֹס</a></div>","alt":[]},"22746":{"h":"פְּלוֹסְלוֹס II","r":"Q00986","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>P’loslos</i>. <span class=\"citation\">Ab. Zar. III, 4</span> בן פ׳ Y. ed. a. Mish. Nap. (Mish. ed. <a href=\"#\" data-headword=\"פילוספוס\">פילוספוס</a>, Bab. ed. 44ᵇ <a href=\"#\" data-headword=\"פלוספיס\">פלוספיס</a>; v. Rabb. D. S. a. l. note 40); <span class=\"citation\">Yalk. Deut. 888</span> <span dir=\"rtl\">פליספ׳</span>.</div>","alt":[]},"22747":{"h":"פלוספא","r":"Q00987","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*פּילוֹסְפָא\">פִּילוֹסְפָא</a></div>","alt":[]},"22748":{"h":"פלוספיס","r":"Q00988","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוֹסְלוֹס II\"><span dir=\"rtl\">פְּלוֹסְלוֹס</span> II</a></div>","alt":[]},"22749":{"h":"פלוקמיא","r":"Q00989","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוּמַקְיָא\">פְּלוּמַקְיָא</a></div>","alt":[]},"22750":{"h":"פָּלַח","r":"Q00990","html":"<div class=\"sense\"> (b. h.) <i>to split; to dig, till; to cut out</i>. <span class=\"citation\">Ex. R. s. 27</span> <span dir=\"rtl\">על מנת לפוֹלְחָהּ</span> will you take this field with the condition that you will till it?; a. e.—2) <i>to work for, serve</i>, v. <a href=\"#\" data-headword=\"פּוֹלִחַ\">פּוֹלֵחַ</a>.—3) <i>to worship</i>. <span class=\"citation\">Tosef. Ab. Zar. I, 4</span> <span dir=\"rtl\">אינו אסור אלא לפוֹלְחִין בלבד</span> it is forbidden to deal with those only who worship (on the Calendæ), contrad. to <span dir=\"rtl\">עושין</span> who observe it as a holiday; (<span class=\"citation\">Ab. Zar. 8ᵃ</span> <span dir=\"rtl\">לעובריה</span>; Y. ib. I, 39ᶜ top <span dir=\"rtl\">לפלחין בה</span>, Chald.).</div>","alt":[]},"22751":{"h":"פְּלַח","r":"Q00991","html":"<div class=\"sense\"><b>1)</b> <i>to till, work</i>. <span class=\"citation\">Targ. Ex. XX, 9</span> (Y. ed. Vien. <i>Pa.</i>). <span class=\"citation\">Targ. Prov. X, 5</span> (h. text <a href=\"#\" data-headword=\"אִגָר\">אגר</a>). <span class=\"citation\">Targ. Gen. IV, 12</span>; a. fr.—3) <i>to serve</i> (<i>man</i> or <i>deity</i>); <i>to worship</i>. Ib. XIV, 4. Ib. XVII, 1 (h. text <a href=\"#\" data-headword=\"הָלַךְ\">התהלך</a>); a. fr.—Y. Ab. Zar. I, 39ᶜ top <span dir=\"rtl\">לפָלְחִין בה</span>, v. <a href=\"#\" data-headword=\"פָּלַח\">preced.</a> <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נשי דפלחין כפלחין</span> the wives of those who worship (on the Roman festivals) are to be treated like those who worship. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כפלחין היא</span> (not <span dir=\"rtl\">כפלחון</span>), v. <a href=\"#\" data-headword=\"שָׁמְרַיִין\">שָׁמְרַיִין</a>. Bab. <span class=\"citation\">Ab. Zar. 11ᵃ</span> <span dir=\"rtl\">פָּלְחֵי בה לע&quot;א</span> they worship the idol on it (the anniversary of death). <span class=\"citation\">Ib. 22ᵇ</span> <span dir=\"rtl\">אם איתא דפַלְחֵיה וכ׳</span> if he had worshipped it, he would not sell it. <span class=\"citation\">Snh. 102ᵇ</span> <span dir=\"rtl\">מ&quot;כ פַּלְחִיתוּ לע&quot;א</span> why do you worship idols? <span class=\"citation\">Gitt. 57ᵇ</span> <span dir=\"rtl\">פְּלַח לע&quot;א</span> worship (bow down) to &amp;c.!; a. fr.—4) <span dir=\"rtl\">פ׳ ב־</span> [<i>to work with</i>,] <i>to compel to serve</i> or <i>work, to subject</i>. <span class=\"citation\">Targ. Lev. XXV, 39</span>. <span class=\"citation\">Targ. O. ib. 43</span>. <span class=\"citation\">Targ. O. Gen. XV, 14</span>; a. fr.—5) <i>to split, distribute</i>. <span class=\"citation\">Ab. Zar. 18ᵃ</span> bot. <span dir=\"rtl\">פלגא פְלַח ופלגא וכ׳</span> one half distribute (as bribe), and one half be thine.</div><div class=\"sense\"><b>Pa. פַּלַּח</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"פָּלַח\">same</a>, <i>to dig, till, work</i>. <span class=\"citation\">Targ. Y. Ex. XX, 9</span> (v. supra). <span class=\"citation\">Targ. Ps. CXLI, 7</span>. <span class=\"citation\">Targ. Is. XXXII, 17</span>; a. e.</div></div><div class=\"sense\"><b>Af. אַפְלַח</b> <div class=\"sense\"><i>to make work, to subject, rule</i>. <span class=\"citation\">Targ. O. Ex. I, 13</span>. <span class=\"citation\">Targ. I Kings V, 4</span>; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִתְפַּלַּח</b> </div><div class=\"sense\"><b>Ithpe. אִתְפְּלַח</b> <div class=\"sense\"><b>1)</b> <i>to be worked, tilled</i>; (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to be worked with</i>. <span class=\"citation\">Targ. Deut. XXI, 3</span>. <span class=\"citation\">Targ. O. ib. 4</span>. <span class=\"citation\">Targ. Ez. XXXVI, 9</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to break through, be born</i>. <span class=\"citation\">Targ. Job XXXIX, 3</span>.</div></div>","alt":[]},"22752":{"h":"פֶּלַח","r":"Q00992","html":"<div class=\"sense\"> c. (b. h.; <a href=\"#\" data-headword=\"פְּלַח\">preced.</a> wds.) <i>segment, slice</i>; (sub. <span dir=\"rtl\">רכב</span>) <i>millstone</i>. <span class=\"citation\">Yalk. Num. 787</span> <span dir=\"rtl\">הכהו בגוש … או בפ׳ של דבילה</span> if he killed a man with a lump of salt or a slice of a fig-cake.—Pl. <span dir=\"rtl\">פְּלָחוֹת</span>, constr. <span dir=\"rtl\">פִּלְחֵי</span>. <span class=\"citation\">Dem. V, 5</span> <span dir=\"rtl\">פ׳ דבלה</span> slices of &amp;c. Yalk. l. c. <span dir=\"rtl\">שיכו אותו … ובפ׳</span> that they may kill him (the murderer) with stones, arrows or millstones.—V. <a href=\"#\" data-headword=\"פֶּלֶךְ\">פֶּלֶךְ</a>.</div>","alt":[]},"22753":{"h":"פִּלְחָא","r":"Q00993","html":"<div class=\"sense\"><b>1)</b> <i>millstone</i>. <span class=\"citation\">Targ. Job XLI, 16</span>.—<span class=\"citation\">Y. M. Kat. I, 80ᵈ</span> bot. <span dir=\"rtl\">אית לן פ׳ דמועדא</span> have we a special millstone for the festive week (dare we grind during the festive week)?</div><div class=\"sense\"><b>—2)</b> <i>slice, portion</i>. <span class=\"citation\">Y. Taan. I, 64ᶜ</span> top <span dir=\"rtl\">דלא הוה גביי אלא פִלְחִי וכ׳</span> I had with me only my own portion (luncheon); why should I have spoken to you (invited you to eat) with insincerity? <span class=\"citation\">Lev. R. s. 12</span> (vers. in Ar.) <span dir=\"rtl\">אם שתי פִּלְחֵיה חמר</span> when he drinks his regular portion of wine; <span dir=\"rtl\">יתר מן פלחיה</span> more than his wonted quantity.</div>","alt":["פִּי׳"]},"22754":{"h":"פָּלְחָא","r":"Q00994","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּלְחָא\">preced.</a> wds.) <i>worker; servant; worshipper.</i>—Pl. <span dir=\"rtl\">פָּלְחִין</span>, <span dir=\"rtl\">פָּלְחִי</span>, <a href=\"#\" data-headword=\"פָּלְחָא\">פּ׳</a>. <span class=\"citation\">Targ. Is. XIX, 9</span>. <span class=\"citation\">Targ. Ps. XLIX, 15</span> <span dir=\"rtl\">פ׳ אוריתא</span> workers (students) of the Law (Ms. <span dir=\"rtl\">פלחן בהון</span>).—Y. Ab. Zar. I, 39ᶜ top, v. <a href=\"#\" data-headword=\"פְּלַח\">פְּלַח</a>.</div>","alt":["פַּ׳ I"]},"22755":{"h":"פָּלְחָא ²","r":"Q00995","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פְּלַח\">פְּלַח</a><i>Ithpa.</i>) <i>breaking through, birth.</i>—Pl. constr. <span dir=\"rtl\">פָּלְחֵי</span>, <a href=\"#\" data-headword=\"פְּגַר III\">פַּ׳</a>; <span dir=\"rtl\">קדמוי פ׳ וולדא</span> <i>first-born</i>. <span class=\"citation\">Targ. Y. II, Ex. XXXIV, 19</span>.</div>","alt":["פַּ׳ II"]},"22756":{"h":"פָּלְחָן","r":"Q00996","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"פּוּלְחָן\">פּוּלְחָ׳</a>.</div>","alt":["פָּלְחָנָא","פָּלְחָנוּתָא"]},"22757":{"h":"פָּלַט","r":"Q00997","html":"<div class=\"sense\"> (b. h.) [<i>to break through</i>,] </div><div class=\"sense\"><b>1)</b> <i>to discharge, vomit, give out</i>. Y. B. Kam. I, 2ᵇ top [read:] <span dir=\"rtl\">היתה מהלכת ופוֹלֶטֶת על עשבים</span> if the animal walked and discharged on plants. <span class=\"citation\">Ter. X, 11</span>; <span class=\"citation\">Ḥull. 110ᵇ</span>, v. <a href=\"#\" data-headword=\"בָּלַע\">בָּלַע</a>. <span class=\"citation\">Ber. III, 6</span> <span dir=\"rtl\">שפָּלְטָה שכבת וכ׳</span> who discharged the (conceived) semen virile. <span class=\"citation\">Pes. 118ᵇ</span> <span dir=\"rtl\">פְּלוֹט אותן ליבשה</span> throw their bodies out on the dry land; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to escape, be spared</i>. <span class=\"citation\">Nidd. 61ᵃ</span> (ref. to <span dir=\"rtl\">הפליט</span>, <span class=\"citation\">Gen. XIV, 13</span>) <span dir=\"rtl\">זה עוג שפ׳ מדור וכ׳</span> that was Og who escaped the fate of the generation of the flood. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">לא פָלְטוּ</span> did not escape (punishment); a. fr.—V. <a href=\"#\" data-headword=\"פָּלֵט\">פָּלֵט</a>.—3) <i>to save</i>. <span class=\"citation\">Pirké d’R. El. ch. XXVII</span> <span dir=\"rtl\">ופְלָטוֹ הק&quot;בה מידו</span> and the Lord saved him from his (Samael’s) power. <span class=\"citation\">Snh. 19ᵇ</span> (ref. to <a href=\"#\" data-headword=\"פַּלְטִי\">פלטיאל</a>, <span class=\"citation\">II Sam. III, 15</span>) <span dir=\"rtl\">שפלטו אל מן וכ׳</span> for God saved him from sin; a. e.</div><div class=\"sense\"><b>—4)</b> <i>to tear off, detach</i>. <span class=\"citation\">Ḥull. 121ᵃ</span> <span dir=\"rtl\">בשר שפְּלָטַתּוּ סכין</span> flesh which the knife has taken off, i.e. which came off in flaying, v. <a href=\"#\" data-headword=\"מוּרְדְּקָא\">מוּרְדְּקָא</a>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">מקצתו פלטתו חיה</span> an animal tore one portion of the flesh off; <span class=\"citation\">ib. 124ᵃ</span>; a. e.</div><div class=\"sense\"><b>Nif. נִפְלָט</b> </div><div class=\"sense\"><b>Hithpa. הִתְפַּלֵּט</b> <div class=\"sense\"><i>to be saved</i>. Tanḥ. Sh’moth 17 <span dir=\"rtl\">ויִתְפַּלֵּט ממנו וכ׳</span> and Noah and his children shall be saved from it (the flood).</div></div>","alt":[]},"22758":{"h":"פְּלַט","r":"Q00998","html":"<div class=\"sense\"><b>1)</b> <i>to discharge, vomit</i>. <span class=\"citation\">Targ. Jon. II, 11</span>. <span class=\"citation\">Targ. Job XX, 15</span> Ms. (ed. <i>Pa.</i>); a. e.—<span class=\"citation\">Ned. 49ᵇ</span>; <span class=\"citation\">Tam. 27ᵇ</span> <span dir=\"rtl\">כל מילי לא תִיפְלוֹט וכ׳</span> thou must not spit out anything in the presence of thy teacher (thou must suppress vomiting), except &amp;c. <span class=\"citation\">Ḥull. 112ᵇ</span> <span dir=\"rtl\">אגב דוחקא דסכינא פָּלֵיט</span> through the pressure of the knife it (the flesh) gives out (blood). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קדמי ופלטי</span> are the first to give out (their serum); <span dir=\"rtl\">בתר … פְּלִיטֵי עופות וכ׳</span> after the fish cease to discharge, the fowl (lying in salt with them) discharge, and they (the fish) absorb; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to escape</i>. <span class=\"citation\">Targ. Prov. XII, 13</span>; a. e.—<span class=\"citation\">Yeb. 114ᵇ</span> <span dir=\"rtl\">הוא פליט</span> is it likely that he will escape? <span class=\"citation\">Keth. 112ᵃ</span> פַּלְטִי לי מחדא I have escaped one (evil destiny). <span class=\"citation\">Y. Ber. III, 6ᵃ</span> <span dir=\"rtl\">חדא מתרתי לא פַלְטַת לכון</span> one of two (mistakes) did not fail you, i.e. of the two things you did, one must be wrong; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to detach, take off</i>. <span class=\"citation\">Targ. Job XIII, 4</span>, v. <a href=\"#\" data-headword=\"מוּרְדְּקָא\">מוּרְדְּקָא</a>.</div><div class=\"sense\"><b>Pa. פַּלֵּט</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"פָּלַט\">same</a>, <i>to give out, discharge</i>. Ib. XX, 15, v. supra.—Y. Taan. I, 63ᵈ top (transl. <span dir=\"rtl\">וארץ רפאים תפיל</span>, <span class=\"citation\">Is. XXVI, 19</span>) <span dir=\"rtl\">וארעא תפקידה תְּפַלֵּט</span> the earth shall give forth her trust (the dead); Y. Ber. V, 9ᵇ top; <span class=\"citation\">Yalk. Kings 207</span>.</div></div>","alt":[]},"22759":{"h":"פָּלֵט","r":"Q00999","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּלַט\">preced.</a>) <i>escaping, spared</i>. <span class=\"citation\">Hor. 8ᵃ</span> <span dir=\"rtl\">ממונן פ׳</span> their property is spared (from destruction); <span class=\"citation\">Yeb. 9ᵃ</span>. Tanḥ. Kor. 5 <span dir=\"rtl\">שכולן אובדין ואחד פ׳</span> that all will perish and one will escape; <span class=\"citation\">Num. R. s. 18</span>; a. e.—<i>Pl.</i> <a href=\"#\" data-headword=\"פלטים\">פְּלֵטִים</a>, <a href=\"#\" data-headword=\"פַּלָּטִין\">פְּלֵטִין</a>, <a href=\"#\" data-headword=\"פְּלֵי\">פְּלֵי׳</a>. <span class=\"citation\">Num. R. s. 19</span>; <span class=\"citation\">Yalk. ib. 765</span>, v. <a href=\"#\" data-headword=\"פָּרִיץ\">פָּרִיץ</a>. <span class=\"citation\">Cant. R. to VII, 8</span>. <span class=\"citation\">Snh. 108ᵃ</span> <span dir=\"rtl\">שבחוצה לה פ׳</span> the property outside of the city is spared; a. e.—<i>Fem</i>. <a href=\"#\" data-headword=\"פְּלֵטָה\">פְּלֵטָה</a>, <a href=\"#\" data-headword=\"פְּלֵיטָה\">פְּלֵיטָה</a>; pl. <span dir=\"rtl\">פְּלֵטוֹת</span>, <a href=\"#\" data-headword=\"פְּלֵי\">פְּלֵי׳</a>. <span class=\"citation\">Tosef. Maasr. I, 6</span> <span dir=\"rtl\">שיבלים הפ׳ מן וכ׳</span> (Var. <span dir=\"rtl\">הפולטות</span>) ears which escaped the storage.</div>","alt":["פָּלֵיט"]},"22760":{"h":"פַּלְטָא","r":"Q01000","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Palṭa</i>. <span class=\"citation\">Y. Ter. X, 47ᵇ</span> bot. <span dir=\"rtl\">לוי בר פ׳</span> (<span class=\"citation\">Lev. R. s. 23</span> <a href=\"#\" data-headword=\"פִּרְטָא\">פרטא</a>).</div>","alt":[]},"22761":{"h":"פְּלֵטָאתָא","r":"Q01001","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלֵטָתָא\">פּלֵטָתָא</a></div>","alt":[]},"22762":{"h":"פְּלֵטָה","r":"Q01002","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פָּלֵט\">פָּלֵט</a>, a. <a href=\"#\" data-headword=\"פְּלֵיטָה\">פְּלֵיטָה</a>.</div>","alt":[]},"22763":{"h":"פלטום","r":"Q01003","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 80</span>; <span class=\"citation\">Yalk. ib. 885</span> <a href=\"#\" data-headword=\"פלטים\">פלטים</a>, prob. a corrupt. of <a href=\"#\" data-headword=\"פּוּטְיוֹלִין\">פּוּטְיוֹלִין</a>.</div>","alt":[]},"22764":{"h":"פלטוני","r":"Q01004","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"פַּלָּטִין\">פַּלָּטִינִי</a>, v. <a href=\"#\" data-headword=\"פַּלָּטִינוֹס\">פַּלָּטִינוֹס</a></div>","alt":[]},"22765":{"h":"פָּלָטוֹרָא","r":"Q01005","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πωλητήρ) <i>market officer.</i>—Pl. <a href=\"#\" data-headword=\"פַּלְטוֹרָה\">פָּלָטוֹרִין</a>, <a href=\"#\" data-headword=\"פָּלָטוֹרָא\">פַּלְ׳</a>. <span class=\"citation\">Targ. Ez. XXIII, 40</span>.—V. <a href=\"#\" data-headword=\"פַּלְטֵר\">פַּלְטֵרָא</a>.</div>","alt":["פַּלְ׳"]},"22766":{"h":"פַּלְטוֹרָה","r":"Q01006","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פַּלְטֵרִין</a></div>","alt":["פַּלְטוֹרִין"]},"22767":{"h":"פַּלְטִי","r":"Q01007","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Palti, Paltiel</i>, to whom Michal the daughter of Saul was given as wife, but who, according to tradition, did not live with her because of her betrothal to David. <span class=\"citation\">Snh. 19ᵇ</span>; v. <a href=\"#\" data-headword=\"פָּלַט\">פָּלַט</a>; <span class=\"citation\">Lev. R. s. 23</span>; a. e.</div>","alt":["פַּלְטִיאֵל"]},"22768":{"h":"פֹּלִטְיָא","r":"Q01008","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (πολιτεία) <i>citizenship</i>. <span class=\"citation\">Pesik. R. s. 15</span> Ar., v. <a href=\"#\" data-headword=\"אִיסוֹפֹּולִיטְיָיא\">אִיסוֹפּוֹלִיטְיָא</a>.</div>","alt":[]},"22769":{"h":"פְּלַטְיָא I","r":"Q01009","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Plaṭia</i>. <span class=\"citation\">Koh. R. to I, 4</span>.</div>","alt":[]},"22770":{"h":"פְּלַטְיָא II","r":"Q01010","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (πλατεῖα, sub. ὁδός, platea) <i>wide street, highway; open place</i> (corresp. to h. <a href=\"#\" data-headword=\"רְחוֹב\">רְחוֹב</a>). <span class=\"citation\">Sabb. 6ᵃ</span> <span dir=\"rtl\">המוציא מחנות לפ׳</span> he that carries an object from the shop to the street (or open place). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ גדולה</span> a large thoroughfare. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">וכל פ׳ ופ׳ עשרין</span> (<a href=\"#\" data-headword=\"עוּר I\">העיר</a>) <span dir=\"rtl\">וכ׳</span></span> and each open place in Jerusalem had twenty-four alleys. <span class=\"citation\">Gen. R. s. 41</span>, end (ref. to <span class=\"citation\">Is. LI, 23</span> <span dir=\"rtl\">וכחוץ</span>) <span dir=\"rtl\">מה פ׳ זו מבלה וכ׳</span> as the highway wears out the passers-by, but itself remains, so shall thy children &amp;c.; <span class=\"citation\">Yalk. Is. 337</span>; <span class=\"citation\">Gen. R. s. 69</span> <a href=\"#\" data-headword=\"פלטירה\">פלטירה</a> (corr. acc.). <span class=\"citation\">Yalk. Sam. 161</span>; Tanḥ. T’tsav 3 ed. Bub. <span dir=\"rtl\">רמז לכבשן ונעשה פ׳</span> the Lord motioned to the furnace (in a depression), and it became a level surface; Tanḥ. ib. <span dir=\"rtl\">פלניי׳</span> (corr. acc.; <span class=\"citation\">Yalk. Koh. 978</span> <span dir=\"rtl\">הציף … והשוהו לארץ וכ׳</span>; v. <span class=\"citation\">Snh. 92ᵇ</span>). <span class=\"citation\">Y. Sabb. I, 2ᵇ</span> bot. <span dir=\"rtl\">פתוחין לפ׳ אחת</span> (not <span dir=\"rtl\">לפלטית</span>) opening to the same open place or street; a. fr.—[<span class=\"citation\">Cant. R. to I, 6</span> <span dir=\"rtl\">חוץ לפ׳</span>, read: <span dir=\"rtl\">לפלטיר</span>, v. <a href=\"#\" data-headword=\"פַּלְטֵר II\"><span dir=\"rtl\">פַּלְטֵר</span> II</a>.—<span class=\"citation\">Macc. 24ᵃ</span>, v. <a href=\"#\" data-headword=\"פּוּטְיוֹלִין\">פּוּטְיוֹלִין</a>.]—Pl. <a href=\"#\" data-headword=\"פַּלְטִיוַת\">פְּלַטְיוֹת</a>, <a href=\"#\" data-headword=\"פְּלַטְיָאוֹת\">פְּלַטְיָאוֹת</a>, <a href=\"#\" data-headword=\"פְּלַטְיָא II\">פְּלַטְיי׳</a>. Y. Sabb. l. c. <span dir=\"rtl\">פתוחים לשתי פ׳</span> opening each to a different street. Lam. R. l. c. <span class=\"citation\">Gen. R. s. 41</span>; s. 69; Yalk. Is. l. c. <span dir=\"rtl\">מרביצין אותן בפלטריות וכ׳</span> (<span dir=\"rtl\">בפולטר׳</span>, read <a href=\"#\" data-headword=\"י\">י</a> for <a href=\"#\" data-headword=\"ר\">ר</a>) they laid them down (like paving stones) in the streets and passed rammers over them. <span class=\"citation\">Gen. R. s. 31</span>; <span class=\"citation\">Yalk. ib. 53</span> פלטיאות <i>aisles</i>, v. supra.</div>","alt":["פְּלַטְיָה","פְּלַטְיָי׳"]},"22771":{"h":"פְּלַטְיָא","r":"Q01011","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"פְּלַטְיָא II\">פְּלַטְיַית</a>. <span class=\"citation\">Targ. Job XXIX, 7</span> Ms. (ed. <a href=\"#\" data-headword=\"פְּתָאָה\">פתאה</a>). <span class=\"citation\">Targ. Y. Deut. XIII, 17</span> <span dir=\"rtl\">פּלְטִיתָא</span> (read: <span dir=\"rtl\">פְּלַטְיָתָהּ</span>); a. e.—Pl. <a href=\"#\" data-headword=\"פְּלַטְיָיא\">פְּלַטְיָיתָא</a>, <a href=\"#\" data-headword=\"פְּלַטְיָיא\">פְּלַטְיָאתָא</a>, <a href=\"#\" data-headword=\"פַּלָּטִין\">פַּלְטִיוָן</a>, <a href=\"#\" data-headword=\"פַּלְטִיוַת\">פַּלְטִיוָתָא</a> (incorr. <a href=\"#\" data-headword=\"פַּלְטִיוַת\">פְּלַטְיוּת</a>). <span class=\"citation\">Targ. Y. II, Gen. XIX, 2</span> <span dir=\"rtl\">פלטיות קרתא</span> (h. text <a href=\"#\" data-headword=\"רְחוֹב\">רחוב</a>). <span class=\"citation\">Targ. I Chr. I, 48</span> (h. text <span dir=\"rtl\">רחובות</span>). <span class=\"citation\">Targ. Ps. LV, 12</span> <a href=\"#\" data-headword=\"פַּלְטִיוַת\">פַּלְטִיוָתָהּ</a> ed. Lag. (ed. Wil. <a href=\"#\" data-headword=\"פַּלְטִיוַת\">פלטיותא</a>; Ms. <a href=\"#\" data-headword=\"פְּלַטְיָיא\">פְּלַטְיָיהָא</a>; h. text <span dir=\"rtl\">רְחֹבָהּ</span>). <span class=\"citation\">Targ. Job XXX, 14</span> <a href=\"#\" data-headword=\"פְּלַטְיָא II\">פְּלַטְיַית</a> ed. Lag. (ed. Wil. <a href=\"#\" data-headword=\"פַּלְטִיוַת\">פלטיות</a>). <span class=\"citation\">Targ. Y. Gen. XLII, 6</span>. <span class=\"citation\">Ib. X, 11</span> <span dir=\"rtl\">פְּלַטְיַאת קרתא</span> (not <span dir=\"rtl\">פליט׳</span>; Y. II <span dir=\"rtl\">פ׳ דקרתא</span>, h. text <span dir=\"rtl\">רחבת עיר</span>). <span class=\"citation\">Targ. Y. Num. XXII, 39</span> <span dir=\"rtl\">פלטיון קרתא</span> (h. text <span dir=\"rtl\">קרית חצות</span>); a. fr.—Y. Ber. III, 6ᵃ <span dir=\"rtl\">באילין פלטיותא וכ׳</span> in the streets of Sepphoris.</div>","alt":["פְּלַטְיָיא"]},"22772":{"h":"פְּלַטְיָאוֹת","r":"Q01012","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"פְּלַטְיָא II\"><span dir=\"rtl\">פְּלַטְיָא</span> II</a>.—[<span class=\"citation\">Yalk. Gen. 128</span>, v. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פַּלְטֵרִין</a> end.]</div>","alt":[]},"22773":{"h":"פלטיאני","r":"Q01013","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלָּטִינוֹס\">פַּלָּטִינוֹס</a></div>","alt":["פלטייאני"]},"22774":{"h":"פְּלַטְיָה","r":"Q01014","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַטְיָא\">פְּלַטְיָא</a></div>","alt":[]},"22775":{"h":"פַּלְטִיוַת","r":"Q01015","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַטְיָא\">פְּלַטְיָא</a> ch</div>","alt":["פַּלְטִיוָתָא","(פְּלַטְיוּת)"]},"22776":{"h":"פְּלַטְיָיא","r":"Q01016","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַטְיָא\">פְּלַטְיָא</a> h. a. ch.</div>","alt":["פְּלַטְיָיה","פְּלַטְיָיאוֹת","פְּלַטְיָיאתָא"]},"22777":{"h":"פלטייאני","r":"Q01017","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלָּטִינוֹס\">פַּלָּטִינוֹס</a></div>","alt":[]},"22778":{"h":"פלטים","r":"Q01018","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פלטום\">פלטום</a></div>","alt":[]},"22779":{"h":"פַּלָּטִין","r":"Q01019","html":"<div class=\"sense\"> c. (palatium, παλάτιον) <i>palace</i>. [<span class=\"citation\">Targ. Lam. IV, 1</span>, read with ed. Lag. <a href=\"#\" data-headword=\"פִּיטָלוֹן\">פִּיטָלוֹן</a>.] <span class=\"citation\">Targ. Y. II, Gen. XII, 15</span> (Ar. <a href=\"#\" data-headword=\"פַּלְטוֹרָה\">פַּלְטוֹרִין</a>). Targ. II Esth. I, 9; a. fr.—<span class=\"citation\">Gen. R. s. 12</span> <span dir=\"rtl\">לפ׳ גדולה וכ׳</span> like a large palace with many entrances. Y. Sabb. X, 12ᶜ <span dir=\"rtl\">אין גדולה בפ׳ של מלך</span> in the king’s palace (the Temple) no rank is recognized (all are alike); a. v. fr.—Pl. same. <span class=\"citation\">Targ. Y. Gen. XLVII, 27</span>.—V. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פַּלְטֵרִין</a></div>","alt":["פַּלְטִין"]},"22780":{"h":"פַּלָּטִינוֹס","r":"Q01020","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (palatinus, παλατῖνος) </div><div class=\"sense\"><b>1)</b>  (sub. mons) <i>the Palatine Hill</i>, a name given to royal residences in general (v. Dio Cassius LIII, 16); esp. <i>Palatinus</i>, a name given by the Samaritans to Mount Gerizim. <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">עבר בהדין פלטאנוס</span> (Var. <span dir=\"rtl\">ניס …</span>, <span dir=\"rtl\">נים …</span>; corr. acc.) passed that Palatinus (on his way to Jerusalem); ib. s. 81 <a href=\"#\" data-headword=\"פלטנוס\">פלטנוס</a> (not <span dir=\"rtl\">ת …</span>); <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">חד פלאטנוס</span> (corr. acc.); <span class=\"citation\">Yalk. Gen. 57</span> <span dir=\"rtl\">פלטניס</span> (corr. acc.); (<span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">הר גריזים</span>).</div><div class=\"sense\"><b>—2)</b> <i>courtier, palace-guard, nobleman.</i>—Pl. <span dir=\"rtl\">פַּלָּטִינִין</span>; (Lat. form) <a href=\"#\" data-headword=\"פַּלָּטִין\">פַּלָּטִינִי</a>, <span dir=\"rtl\">פַּלָּא׳</span>. <span class=\"citation\">Num. R. s. 1</span> <span dir=\"rtl\">שבטו של לוי פ׳ היו</span> the tribe of Levi was the palace-guard (royal body-guard in the Temple). <span class=\"citation\">Num. R. s. 5</span> <span dir=\"rtl\">אע&quot;פ שהיתה משפחת קהת פ׳ וכ׳</span> although the Kehath family vere palatini, when carrying the Ark they carried it like slaves (on their shoulders, no rank being recognized before God, v. <a href=\"#\" data-headword=\"פַּלָּטִין\">פַּלָּטִין</a>). <span class=\"citation\">Ruth R. to I, 2</span> (expl. <span dir=\"rtl\">אפרתים</span>, ib.) <a href=\"#\" data-headword=\"פלטייאני\">פלטייאני</a> (corr. acc.); Midr. Sam. ch. I <a href=\"#\" data-headword=\"פלאטוני\">פלאטוני</a> (corr. acc.); <span class=\"citation\">Lev. R. s. 2</span> (ref. to <a href=\"#\" data-headword=\"אֶפְרַיִם\">אפרים</a>, <span class=\"citation\">Jer. XXXI, 19</span>) <a href=\"#\" data-headword=\"פלטיאני\">פלטיאני</a> (corr. acc.). <span class=\"citation\">Pirké d’R. El. ch. XLV</span> (ref. to <span dir=\"rtl\">אפרת</span> <span class=\"citation\">I Chr. II, 19</span>) <span dir=\"rtl\">פלטיני בת מלכים וכ׳</span> (παλατίνη) a <i>palatina</i>, a daughter of nobles; ib. <span dir=\"rtl\">בן פלטוני בן מלכים וכ׳</span> (corr. acc.) a son of noblemen, a son of kings &amp;c. <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">בן פלוטומנין</span>, <span dir=\"rtl\">פולוט׳</span>; <span class=\"citation\">Pesik. R. s. 7</span> <span dir=\"rtl\">פולטומין</span> (corr. acc.).</div>","alt":["פַּלָּאטִ׳"]},"22781":{"h":"פַּלְטֵיר","r":"Q01021","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְטֵר\">פַּלְטֵר</a>, <a href=\"#\" data-headword=\"פַּלְטֵר\"><a href=\"#\" data-headword=\"פַּלְטֵר\">פַּלְטֵר׳</a>.</a></div>","alt":["פַּלְטֵירָא","פַּלְטֵירִין"]},"22782":{"h":"פלטירה","r":"Q01022","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 69</span>, read: <a href=\"#\" data-headword=\"פְּלַטְיָיא\">פְּלַטְיָיה</a>.</div>","alt":[]},"22783":{"h":"פלטית","r":"Q01023","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. I, 2ᵇ</span> bot., read: <a href=\"#\" data-headword=\"פְּלַטְיָה\">פְּלַטְיָה</a>.</div>","alt":[]},"22784":{"h":"פלטנוס","r":"Q01024","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלָּטִינוֹס\">פּלָּטינוֹס</a></div>","alt":["פלטנות"]},"22785":{"h":"פלטנטירין","r":"Q01025","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Num. 695</span>, v. <a href=\"#\" data-headword=\"פַּלְמַנְטָר\">פַּלְמַנְטָר</a></div>","alt":[]},"22786":{"h":"פַּלְטֵר I","r":"Q01026","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פַּלְטֵרִין</a></div>","alt":[]},"22787":{"h":"פַּלְטֵר II","r":"Q01027","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πωλητήρ, πωλητήριον) <i>shop-keeper</i>, esp. <i>seller of bakers’ ware; shop</i>, esp. <i>bakery-shop</i>. <span class=\"citation\">Ab. Zar. IV, 9</span> (<span class=\"citation\">55ᵇ</span>) <span dir=\"rtl\">מוליכין עמו פת לפ׳</span> you may carry your own bread with his (the non-observant baker’s) to the shop-keeper. <span class=\"citation\">Dem. V, 4</span> <span dir=\"rtl\">הלוקח מן הפ׳ וכ׳</span> he who buys bread at the shop (which contains bread of different batches) must give tithes of each form separately, contrad. to <a href=\"#\" data-headword=\"מָנְפּוֹל\">מנפול</a>. Y. Shek. VII, beg. 51ᵃ, a. e. <span dir=\"rtl\">לוקח מן הפ׳</span>, v. <a href=\"#\" data-headword=\"סִידְקִי\">סִידְקִי</a>. <span class=\"citation\">Y. Shebi. VII, 37ᶜ</span> top <span dir=\"rtl\">ובלבד שלא יעשה פליטר</span> (not <span dir=\"rtl\">יעשו</span>; R. S. to ib. VII, 3 <a href=\"#\" data-headword=\"פַּלְטֵר I\">פלטר</a>) provided he is not made (their regular) shop-keeper (selling at the same place, at all times). <span class=\"citation\">Cant. R. to I, 6</span> <span dir=\"rtl\">שנמכרת חוץ לפ׳</span> (not <span dir=\"rtl\">לפלטיא</span>), v. <a href=\"#\" data-headword=\"קִיבָר\">קַיבָר</a>; a. fr.</div>","alt":[]},"22788":{"h":"פַּלְטֵר","r":"Q01028","html":"<div class=\"sense\"> <span class=\"citation\">Y. Sabb. VIII, 11ᵃ</span> bot. <span dir=\"rtl\">ואנא סמיך על פ׳</span> (not <span dir=\"rtl\">לפ׳</span>) but I have to rely (for my supply) on the shop-keeper; Y. Shek. VIII, beg. 51ᵃ <span dir=\"rtl\">לטלפירא</span> (corr. acc.). <span class=\"citation\">Gen. R. s. 22</span> <span dir=\"rtl\">אזל ויתיב קמי פ׳</span> (the dog) sits down in front of the shop (or stand); <span class=\"citation\">ib.</span> <span dir=\"rtl\">מרי פ׳</span> the shop-keeper; <span class=\"citation\">Yalk. Gen. 36</span>; <span class=\"citation\">Yalk. Ps. 840</span>; [Ar. reads <a href=\"#\" data-headword=\"פַּרְטֵירָא\">פַּרְטֵירָא</a> (πρατήριον) <i>market</i>]. <span class=\"citation\">Y. B. Kam. II, end, 3ᵃ</span> <a href=\"#\" data-headword=\"פלטירה\">פַּלְטֵירֵה</a> the goods of his shop, v. <a href=\"#\" data-headword=\"*פּוּרָה\">פּוּרָה</a>; a. e.—Pl. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פַּלְטֵרִין</a>, <a href=\"#\" data-headword=\"פַּלְטֵר\">פַּלְטֵי׳</a> <i>goods for sale</i>. Y. B. Mets. III, end, 9ᵇ <span dir=\"rtl\">בר נש דיהב לחבריה פליטורין בשוקא וכ׳</span> (corr. acc., or <span dir=\"rtl\">פוֹלִיטֵירִין</span>) if a man put goods (on a stand) in the market in charge of his neighbor, and he left them in charge of his minor son or daughter, and they were stolen or lost, he is not bound to pay; <span dir=\"rtl\">שאני אומר לא על דעת פ׳ בשוק</span> (a defective sentence, perhaps <span dir=\"rtl\">מסרן לו</span> is to be supplied) for I may say, has he not given them as goods on exhibit in the market? (hence he was not bound to lock them up).</div>","alt":["פַּלְטֵרָא","פַּלְטֵי׳"]},"22789":{"h":"פלטרים","r":"Q01029","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">next w.</a></div>","alt":[]},"22790":{"h":"פַּלְטֵרִין","r":"Q01030","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πραιτώριον, prætorium) <i>headquarters; palace, residence; country-seat</i>. <span class=\"citation\">Snh. II, 3</span> (<span class=\"citation\">20ᵃ</span>) <span dir=\"rtl\">אינו יוצא מפתח פ׳ שלו</span> (Y. ed. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פלטו׳</a>, Ar. <a href=\"#\" data-headword=\"פַּלָּטִין\">פלטין</a>) must not leave his royal residence (to escort the dead). <span class=\"citation\">Num. R. s. 1</span> end <span dir=\"rtl\">אף … ועושה אותן בני פַלְטַירִי</span> so I will bring them near me and make them sons of my palace (= <a href=\"#\" data-headword=\"פַּלָּטִין\">פַּלָּטִינִי</a>); [<span class=\"citation\">Yalk. Num. 695</span> <a href=\"#\" data-headword=\"פלטנטירין\">פלטנטירין</a>; Tanḥ. B’midb. 26 <span dir=\"rtl\">פלמנטרין</span>, v. <a href=\"#\" data-headword=\"פַּלְמַנְטָר\">פַּלְמַנְטָר</a>]. <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">כשתכנס … לפ׳ שלך</span> when thou enterest thy province and comest to thy headquarters. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">והיו בני המדינה עומדים על פתח פ׳ … יכנס המלך לפַלְטרוֹ</span> (not <span dir=\"rtl\">לפלטר</span>) the citizens stood at the entrance of the palace and cried, let the king enter his palace. <span class=\"citation\">Pirké d’R. El. ch. III</span> <span dir=\"rtl\">שהוא רוצה לבנות פלטרים שלו</span> (corr. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פלטרין</a>) who wishes to build his palace; a. fr.—Pl. <a href=\"#\" data-headword=\"פַּלְטֵיר\">פַּלְטֵירִין</a>, <a href=\"#\" data-headword=\"פַּלְטוֹרָה\">פַּלְטוֹרִין</a>. <span class=\"citation\">Esth. R. to I, 2</span> <span dir=\"rtl\">כל אחד ואחד היו לו שני פ׳ וכ׳</span> each had two residences, one for the summer &amp;c.; a. e.—Fem. form: <a href=\"#\" data-headword=\"פַּלְטוֹרָה\">פַּלְטוֹרָה</a>, <a href=\"#\" data-headword=\"פלטירה\">פַּלְטֵירָה</a>. <span class=\"citation\">Sifré Deut. 309</span> <span dir=\"rtl\">פלטו׳ אחת</span>; <span class=\"citation\">Yalk. ib. 942</span> <span dir=\"rtl\">פלטי׳</span>, v. infra.—Pl. <span dir=\"rtl\">פַּלְטוֹרִיּוֹת</span>, <span dir=\"rtl\">פַּלְטֵירִיאוֹת</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מי שהורישו אביו עשר פ׳ ועמד וקנה פלטורה אחת וכ׳</span> one to whom his father left ten country-seats, but he rose and bought one with his own money, and this he loved <span dir=\"rtl\">מכל פ׳ שהנחילו אביו</span> (not <span dir=\"rtl\">רה …</span>) more than all the residences that his father had left him. <span class=\"citation\">Sifré Deut. 353</span>; <span class=\"citation\">Yalk. ib. 959</span>. <span class=\"citation\">Koh. R. to VI, 3</span> <span dir=\"rtl\">שתי פַלְטֵרִיּוֹת</span>, v. supra. <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">ירש אשר פ׳ מה וכ׳</span> (not <span dir=\"rtl\">ירש גבהי</span>) Asher possessed more residences (abroad) than Judah possessed districts; <span class=\"citation\">Yalk. ib. 128</span> <a href=\"#\" data-headword=\"פְּלַטְיָאוֹת\">פלטיאות</a> (corr. acc.).—[פלטריות <span class=\"citation\">Gen. R. s. 41</span>, a. e., v. <a href=\"#\" data-headword=\"פְּלַטְיָא\">פְּלַטְיָא</a>.]</div>","alt":["פַּלְטֵי׳","פַּלְטוֹ׳","פַּלְטֵר"]},"22791":{"h":"פְּלֵטַת","r":"Q01031","html":"<div class=\"sense\"> pr. n. f., v. <a href=\"#\" data-headword=\"פְּלֵיטִית\">פְּלֵיטִית</a></div>","alt":[]},"22792":{"h":"פְּלֵטָתָא","r":"Q01032","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פְּלֵיטָה\">פְּלֵיטָה</a>, <i>escaped, remnants</i>. <span class=\"citation\">Yalk. Jer. 265</span> <span dir=\"rtl\">לא מן פ׳ דעמא דסדום אתון</span> are you not of the escaped of the people of Sodom?; Pesik. Shimʿu, p. 117ᵇ <a href=\"#\" data-headword=\"פְּלֵטָאתָא\">פלטאתא</a>.</div>","alt":[]},"22793":{"h":"פלטתה","r":"Q01033","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sot. I, 17ᵃ</span> bot., v. <a href=\"#\" data-headword=\"פְּלוּגְתָּא II\"><span dir=\"rtl\">פְּלוּגְתָּא</span> II</a></div>","alt":[]},"22794":{"h":"*פָּלִי","r":"Q01034","html":"<div class=\"sense\"> (πόλυ) <i>much</i>. <span class=\"citation\">Y. Shebu. III, 34ᵈ</span> bot., v. <a href=\"#\" data-headword=\"*בריכסון\">בריכסון</a>.</div>","alt":[]},"22795":{"h":"פלי","r":"Q01035","html":"<div class=\"sense\"> (b. h.) <i>to split, separate; to remove; to search</i>; v. <a href=\"#\" data-headword=\"פֶּלֶא\">פֶּלֶא</a>, <a href=\"#\" data-headword=\"פְּלִיאָה\"><a href=\"#\" data-headword=\"פְּלִיאָה\">פְּלִיאָה</a>.</a></div><div class=\"sense\"><b>Nif. נִפְלָא</b> <div class=\"sense\"><i>to be remote, hidden, obscure</i>. <span class=\"citation\">Midr. Till. to Ps. CXIX, 18</span> <span dir=\"rtl\">א־נה נִפְלֵאת וכ׳</span> it (the Law) is not hidden, as it is said (<span class=\"citation\">Deut. XXX, 11</span>) &amp;c.; <span dir=\"rtl\">לא נִפְלֵאת אלא ממך וכ׳</span> it is hidden from thee only (through thy own fault), who didst not take pains to study it. V. <a href=\"#\" data-headword=\"נִפְלָא III\"><span dir=\"rtl\">נִפְלָא</span> III</a></div></div><div class=\"sense\"><b>Hif. הִפְלִיא</b> <div class=\"sense\"> (cmp. <span dir=\"rtl\">פרֹש</span>) </div><div class=\"sense\"><b>1)</b> <i>to distinguish, speak distinctly, clearly</i>; esp. (sub. <a href=\"#\" data-headword=\"נֶדֶר\">נֶדֶר</a>) <i>to utter a distinct vow</i> (with ref. to <span class=\"citation\">Num. VI, 2</span>). <span class=\"citation\">Naz. 62ᵃ</span>; <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">יודע להַפְלוֹת</span>, <span dir=\"rtl\">לַפְלוֹת</span> (from <a href=\"#\" data-headword=\"פָּלָה\">פָּלָה</a>) who knows how to express a vow (is conscious of its bearings); <span class=\"citation\">Sifré Num. 22</span>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"פֶּלֶא\">פֶּלֶא</a>) <i>to do strange, wonderful things</i>. <span class=\"citation\">Ber. 60ᵇ</span> <span dir=\"rtl\">מַפְלִיא לעשות</span> who does wonderful things.—[<span class=\"citation\">Tosef. Ab. Zar. III</span> (<span class=\"citation\">IV), 19</span> <span dir=\"rtl\">מפליא ויצא</span> ed. Zuck., missing in ed., a corrupt gloss for <span dir=\"rtl\">מפליא ליצנותא</span>, v. <a href=\"#\" data-headword=\"לֵיצָנוּתָא\">לֵיצָנוּתָא</a>.]</div><div class=\"sense\"><b>—3)</b> <i>to search, question</i>. <span class=\"citation\">Midr. Till. to Ps. III</span> <span dir=\"rtl\">ואין מי שיַפְלִיא אחריהן</span> and none questions the correctness of their decision; <span class=\"citation\">Yalk. Sam. 151</span>.</div><div class=\"sense\"><b>—4)</b> <i>to be too difficult to decide</i>. <span class=\"citation\">Num. R. s. 21</span> <span dir=\"rtl\">וה׳ ממנו</span> and he (Moses) could not decide it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שה׳ מן משה שיש צדיקים וכ׳</span> Moses was unable to decide, because many a righteous man prides himself …, and the Lord weakens his power (as a punishment).—Part. pass. <a href=\"#\" data-headword=\"מוּפְלָא\">מוּפְלָא</a> q. v.</div></div><div class=\"sense\"><b>Pi. פִּלֵּא</b> <div class=\"sense\"><i>to search</i>, v. <a href=\"#\" data-headword=\"פלי ²\">next w.</a></div></div>","alt":["פָּלָא"]},"22796":{"h":"פלי ²","r":"Q01036","html":"<div class=\"sense\"><i>to search</i>; (euphem.) <i>to search one’s garment for vermin</i>. <span class=\"citation\">Sabb. 12ᵃ</span> <span dir=\"rtl\">אין פּוֹלִין לאור הנר</span> you must not search by lamp light (on the Sabbath); a. e.</div><div class=\"sense\"><b>Pi. פִּילָּה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"פלי\">same</a>. Ib. I, 3 <span dir=\"rtl\">לא יְפַלֶּה את כליו וכ׳</span> (Y. ed. <span dir=\"rtl\">יֲפַלֵּא</span>) one must not examine one’s garments &amp;c. Tosef. ib. XVI (XVII), 22 <span dir=\"rtl\">המְפַלֶּה</span> (ed. Zuck. <span dir=\"rtl\">המְפַלֵּא</span>); Y. ib. II, 3ᵇ <span dir=\"rtl\">המפלא</span>; a. fr.—[Y. Maasr. II, 49ᵈ <span dir=\"rtl\">לפלה</span> ed. Zyt. (ed. Krot. <span dir=\"rtl\">לפנע</span>) read: <span dir=\"rtl\">לפנות</span>, v. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>.]</div></div><div class=\"sense\"><b>Hif. הִפְלָה</b> <div class=\"sense\"><b>1)</b> <i>to distinguish, speak distinctly</i>, v. <a href=\"#\" data-headword=\"פלי\">preced.</a></div><div class=\"sense\"><b>—2)</b> <i>to mystify</i>, v. <a href=\"#\" data-headword=\"פְּלֵי\">next w.</a></div></div>","alt":["פָּלָה"]},"22797":{"h":"פְּלֵי","r":"Q01037","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"פלי ²\">preced.</a> wds.) <i>to split, cut open</i>. <span class=\"citation\">B. Bath. 160ᵇ</span>; <span class=\"citation\">164ᵇ</span> <span dir=\"rtl\">פּלְיֵיה וחזייה</span> he ripped open the tied-up document and saw it (that the signature was in the folds). <span class=\"citation\">Ḥull. 11ᵃ</span> <span dir=\"rtl\">דילמא דפ׳ ליה וכ׳</span> may it not be that he (the priest) opened the skull and examined it? <span class=\"citation\">Yoma 87ᵃ</span> <span dir=\"rtl\">הוה יתיב וקא פָלֵי רישא</span> was sitting and chopping (an animal’s) head. <span class=\"citation\">Snh. 108ᵇ</span> <span dir=\"rtl\">קא פָאלֵי וכ׳</span> was opening pomegranates; a. e.</div><div class=\"sense\"><b>Pa. פַּלֵּי</b> <div class=\"sense\"><b>1)</b> <i>to search</i> (garments). Y. M. Kat. III, 82ᵃ top <span dir=\"rtl\">מְפַלֵּא מאנוי</span> searching his garments.</div><div class=\"sense\"><b>—2)</b> <i>to search after, glean; to remove</i>. <span class=\"citation\">Targ. O. Deut. XXIV, 20</span> (h. text <span dir=\"rtl\">תפאר</span>). <span class=\"citation\">Ib. XXVI, 13</span> (h. text <span dir=\"rtl\">בערתי</span>). <span class=\"citation\">Targ. I Kings XVI, 3</span>. <span class=\"citation\">Targ. Zeph. III, 15</span> (h. text <span dir=\"rtl\">פנה</span>); a. fr.—[<span class=\"citation\">Targ. I Sam. II, 25</span>, v. infra.]</div></div><div class=\"sense\"><b>Af. אַפְלֵי</b> <div class=\"sense\"><b>1)</b> <i>to do strange, wonderful things; to go to the extreme of</i>. <span class=\"citation\">Targ. Is. IX, 5</span> <span dir=\"rtl\">מַפְלֵי</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">מַפְלְיָא</span>; oth. ed. <span dir=\"rtl\">מַפְלִיא</span> Hebraism).—<span class=\"citation\">Ab. Zar. 44ᵃ</span> <span dir=\"rtl\">מַפְלְיָא</span>, v. <a href=\"#\" data-headword=\"לֵיצָנוּתָא\">לֵיצָנוּתָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>to decide, arbitrate</i>. <span class=\"citation\">Targ. I Sam. II, 25</span> (Bxt. <span dir=\"rtl\">וִיפַלֵּי</span>, <i>Pa.</i>; h. text <span dir=\"rtl\">פלל</span>).</div><div class=\"sense\"><b>—3)</b>  (with <a href=\"#\" data-headword=\"ב\">ב</a>; cmp. <span class=\"citation\">Is. XXIX, 14</span>) <i>to mystify, perplex, outwit, fool</i>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳ 8) <span dir=\"rtl\">חד … והוה מַפְלֵי … סגי</span> an Athenian used to come to Jerusalem and outwit the Jerusalemites frequently. Ib. <span dir=\"rtl\">מכאן ולהבא לא תַפְלֵי וכ׳</span> henceforth thou shalt not again attempt to outwit &amp;c. <span class=\"citation\">Gen. R. s. 42</span>, v. <a href=\"#\" data-headword=\"מְרֵי\">מְרֵי</a>. <span class=\"citation\">Gen. R. s. 91</span> <span dir=\"rtl\">למה אַפְלְיַית בי</span> why didst thou mystify (deceive) me?; <span dir=\"rtl\">לא אַפְלְיִית בך</span> I did not deceive thee; <span class=\"citation\">Koh. R. to VII, 11</span> <span dir=\"rtl\">אַפְלְיַת</span>, <span dir=\"rtl\">אַפְלִית</span>; Y. Naz. V, end, 54ᵇ <span dir=\"rtl\">אַפְלֵיתָה</span>, <span dir=\"rtl\">אַפְלֵיתִי</span>; Y. Ber. VII, 11ᵇ bot.; <span class=\"citation\">Yalk. Gen. 148</span>. <span class=\"citation\">Ib. 62</span> <span dir=\"rtl\">מה את מַפְלֵי בי</span> (<span class=\"citation\">Gen. R. s. 38</span> <span dir=\"rtl\">מה את מַפְלֶה בי</span>) why wilt thou fool me? Y. Shebi. IX, 38ᵈ, v. <a href=\"#\" data-headword=\"לֵי\">לֵי</a>; a. e.</div></div>","alt":["פְּלָא"]},"22798":{"h":"פִּלְיָא","r":"Q01038","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"פִּילְיָא\">פִּילְיָא</a></div>","alt":[]},"22799":{"h":"פַּלְיָא","r":"Q01039","html":"<div class=\"sense\"> (?) m. (perh. = <span dir=\"rtl\">פ׳ בֵי יַאֲרֵי</span> = <span dir=\"rtl\">יַעֲרֵי</span>, v. <a href=\"#\" data-headword=\"פִּלְיָא\">preced. art.</a>, a. <a href=\"#\" data-headword=\"יַעְרָא I\">יַעֲרָא</a>) [<i>searcher in forests</i>] name of a <i>locust</i> on palm-trees (h. <span dir=\"rtl\">צפורת כרמים</span>). <span class=\"citation\">Sabb. 90ᵇ</span> (Ms. M. <span dir=\"rtl\">צפורתא דפילי בידי</span>; Ms. O. <span dir=\"rtl\">פיליא בייארי</span>, Rashi: <span dir=\"rtl\">פיילי ביירי</span>). Cmp. <a href=\"#\" data-headword=\"פָּלְיַית\">פָּלְיַית</a>.</div>","alt":["פ׳ בֵיאָרִי"]}};
